/* ÇEVİRİ jv · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("jv","olay",{
"OLAYLAR_EK7:1566-09-24:0":{"b": ["Selim II tekan Istanbul lan jumeneng", "0289ef97"], "d": ["Sawisé sédané Sultan Sulaiman Sang Pembuat Undhang-undhang ing Szigetvár, Sokollu Mehmed Pasya ndhelikaké kabar iku pirang-pirang minggu supaya tatanan ora kaganggu. Miturut Ensiklopedi Islam TDV, Selânikî nyebut tanggal tekané Selim ing Istanbul yaiku 15 Rabiulawal 974 (30 September 1566), déné akèh-akèhé sejarawan jaman saiki nampa 9 Rabiulawal (24 September) sing bener. Sédané Sultan Sulaiman lagi diumumaké kanthi resmi ing Beograd tanggal 24-25 Oktober 1566.", "66da7cdb"]},
"OLAYLAR_EK7:1572-06-13:0":{"b": ["Armada sing dibangun manèh déning Kılıç Ali Pasya mudhun ing segara", "d0fc9f48"], "d": ["Sawisé kekalahan abot ing Lepanto (7 Oktober 1571), kapal-kapal dibangun ing galangan sajroné mangsa adhem kabèh. Miturut Ensiklopedi Islam TDV, tanggal 1 Sapar 980 (13 Juni 1572) armada anyar sing isiné 250 galai lan udakara 300 galai reis sukarélawan diluncuraké ing segara minangka pamèr kakuwatan.", "33415db2"]},
"OLAYLAR_EK7:1579-10-12:0":{"b": ["Sokollu Mehmed Pasya dipatèni liwat paténi gelap", "6ffa8dec"], "d": ["Sokollu Mehmed Pasya, sing patbelas taun dadi wazir agung ing jaman telung sultan, tanggal 20 Syakban 987 (12 Oktober 1579) ditusuk keris nganti séda déning darwis sing nyedhak kaya arep ngaturaké panyuwunan ing diwan asar ing omahé. Miturut Ensiklopedi Islam TDV, diperdebataké apa paténi iku ana gandhèngané karo walesan kanggo syekh Hamzawiyah, Hamza Bâlî, sing diukum pati.", "b1355377"]},
"OLAYLAR_EK7:1580-01-01:0":{"b": ["Ahidname dagang kapisan karo Inggris — wong Inggris diwènèhi kapitulasi", "59c8e3ee"], "d": ["William Harborne, wakil Inggris sing dikirim menyang Istanbul ing Oktober 1578, kanthi dhukungan Sokollu Mehmed Pasya lan Hoca Sadeddin Efendi nampa ahidname taun 1580 saka Murad III. Kanthi ahidname iki, sudagar Inggris olèh hak melu ngrasakaké hak istimewa dagang (kapitulasi) sing sadurungé diwènèhaké marang wong Prancis lan Venesia ing tingkat sing padha. Layang-layang dikirim-kirimaké antarané Ratu Elizabeth I lan Murad III, lan sesambungan resmi antarané rong nagara iku uga diadegaké. Sawisé hak istimewa iku, ing 1581 Levant Company diadegaké ing London; wong Inggris nglakokaké dagangé ing wilayah iku liwat maskapé iki nganti 1825.", "c25734eb"]},
"OLAYLAR_EK7:1580-01-22:0":{"b": ["Observatorium Istanbul dibongkar liwat hatt-ı hümâyun", "3bc0c78c"], "d": ["Amarga pangaribawa fatwa sing muni yèn observatorium nggawa apes kanggo nagara lan amarga oposisi ing kraton, Observatorium Istanbul dibongkar bebarengan karo kabèh piranti ing jeroné liwat hatt-ı hümâyun tanggal 4 Dzulhijah 987 (22 Januari 1580). Miturut Ensiklopedi Islam TDV, iki dadi pungkasan umur cendhak lembaga sing diadegaké Taqi al-Din al-Rasid.", "7b4f41fe"]},
"OLAYLAR_EK7:1582-05-29:0":{"b": ["Pahargyan sunat Pangéran Mehmed ing Alun-alun Jaran (Atmeydanı) diwiwiti", "c2926d5d"], "d": ["Pangéran Mehmed, putrané Murad III, disunati kanthi upacara mèwah sing diwiwiti tanggal 6 Jumadilawal 990 (29 Mei 1582) lan lumaku sèket enem nganti sèket pitu dina. Miturut Ensiklopedi Islam TDV, pahargyan sing dianakaké ing Atmeydanı iku salah siji pahargyan kraton paling éndah ing jamané.", "eaf7772a"]},
"OLAYLAR_EK7:1583-12-07:0":{"b": ["Nurbanu Valide Sultan séda", "77d0a577"], "d": ["Ibuné Murad III, Nurbanu Sultan, séda tanggal 22 Dzulkaidah 991 (7 Desember 1583). Miturut Ensiklopedi Islam TDV, minangka valide sultan dhèwèké surat-suratan karo kraton Venesia lan Prancis, lan ing taun sing padha senat Venesia sarujuk ngirim hadiah regané 2000 dhuwit emas Venesia minangka ijolan jasané.", "56b04854"]},
"OLAYLAR_EK7:1589-06-01:0":{"b": ["Kedadéan Beylerbeyi pecah amarga akçe sing dioplos", "db2f2e61"], "d": ["Nalika nagara mbayar nganggo akçe sing kadar pérakné dikurangi, prajurit sipahi lan Yanisari ngepung kraton lan nganakaké pambrontakan getih sing ing sajarah dikenal minangka Kedadéan Beylerbeyi. Miturut artikel Abdülkadir Şeyhî Efendi ing Ensiklopedi Islam TDV, syaikhul Islam dicopot saka jabatané amarga kedadéan iki.", "b1db5aea"]},
"OLAYLAR_EK7:1595-01-27:0":{"b": ["Mehmed III munggah tahta, sangalas pangéran dicekik", "2cd9a8c5"], "d": ["Mehmed III, sawisé sédané ramané Murad III, tekan Istanbul dina Jemuwah tanggal 16 Jumadilawal 1003 (27 Januari 1595) lan munggah tahta. Miturut Ensiklopedi Islam TDV, ing bengi sing padha sangalas pangéran, papat ing antarané wis diwasa (Mustafa, Bayezid, Osman lan Abdullah), dipatèni kanthi dicekik; iki paténi sedulur paling akèh ing sajarah Utsmaniyah.", "fee571d5"]},
"OLAYLAR_EK7:1595-02-01:0":{"b": ["Safiye Sultan olèh pangaribawa minangka valide sultan", "000bec21"], "d": ["Safiye Sultan, garwané Murad III lan ibuné Mehmed III, kanthi jumenengé putrané munggah ing kalungguhan nemtokaké ing pulitik kraton minangka valide sultan. Miturut Ensiklopedi Islam TDV, ing mangsa iki pangaribawa saka harem tekan tingkat melu campur langsung ing urusan nagara.", "dcf5f731"]},
"OLAYLAR_EK7:1596-06-20:0":{"b": ["Mehmed III budhal perang dhéwé amarga tekanan Yanisari", "d3c50656"], "d": ["Sanadyan ditentang Wazir Agung Damad Ibrahim Pasya, amarga tekanan Yanisari, Mehmed III budhal saka Istanbul tanggal 20 Juni 1596 minangka sultan kapisan wiwit Sultan Sulaiman Sang Pembuat Undhang-undhang sing mimpin dhéwé wadyabala. Miturut Ensiklopedi Islam TDV, iki ateges nguripaké manèh tradhisi ghaza lawas.", "396dc19b"]},
"OLAYLAR_EK7:1600-06-01:0":{"b": ["Pageblug pès sing diwiwiti ing taun 1570-an isih nggebug Istanbul", "eb4ca37a"], "d": ["Miturut artikel Tâun ing Ensiklopedi Islam TDV, pageblug sing diwiwiti ing taun 1570-an lumaku nganti wiwitan abad kaping 17 lan nggebug Anatolia, Balkan, Mesir lan Afrika Lor, luwih-luwih Istanbul. Mangsa pageblug dadi ancaman kronis sing kerep ngganggu urip kraton lan kutha.", "3afd5ea1"]},
"OLAYLAR_EK7:1602-02-15:0":{"b": ["Karayazıcı Abdülhalim séda, gerakan pambrontakan saya ringkih", "876ca7a6"], "d": ["Karayazıcı Abdülhalim, sing mundur nandhang tatu sawisé kekalahan abot tanggal 12 Agustus 1601 ing Sepetli cedhak Elbistan, séda ing taun 1010 (1602). Miturut Ensiklopedi Islam TDV, kabar sédané tekan Istanbul ing sasi Ramadan taun 1010 (Fèbruari-Maret 1602); sumber-sumber nyathet yèn isih diperdebataké apa sédané amarga tatu utawa ditindakaké wong-wongé dhéwé.", "f9c28a0d"]},
"OLAYLAR_EK7:1603-12-23:0":{"b": ["Pungkasan nyata tradhisi paténi sedulur", "9046c607"], "d": ["Nalika jumeneng, Ahmed I, béda karo sultan-sultan sadurungé, ora ndhawuhaké matèni seduluré, Pangéran Mustafa, nanging ngapura nyawané; keputusan iki dianggep wiwitan diangkaté kanthi nyata prinsip sing paling tuwa lan paling mumpuni (ekber-erşed) ing tatanan waris Utsmaniyah. Artikel 'Mustafa I' ing Ensiklopedi Islam TDV nyritakaké yèn wiwit tanggal iku Mustafa urip nyingkur ing kraton. Praktik iki kanthi nyata mungkasi paténi jumenengan sing wis lumaku pirang-pirang abad.", "7734428a"]},
"OLAYLAR_EK7:1609-08-09:0":{"b": ["Pondhasi Mesjid Sultanahmet dipasang", "1683262f"], "d": ["Kanthi dhawuh Ahmed I, pondhasi mesjid sing bakal dibangun arsitèk Sedefkâr Mehmed Agha dipasang kanthi upacara ing Atmeydanı. Miturut artikel 'Mesjid lan Komplèks Sultan Ahmed' ing Ensiklopedi Islam TDV, bangunan iku uga dadi sasaran kritik ing jamané amarga minangka mesjid kasultanan gedhé kapisan sing dibangun langsung saka kas nagara tanpa kamenangan penaklukan. Komplèks iku dirancang supaya, bebarengan karo mesjid, uga isiné madrasah, dapur umum lan cungkup.", "2605235a"]},
"OLAYLAR_EK7:1622-05-20:0":{"b": ["Osman Anom dipatèni Yanisari (Hâile-i Osmâniye)", "324f6582"], "d": ["Yanisari lan sipahi, sing brontak amarga krungu kabar yèn dhèwèké ngrancang lunga saka Istanbul kanthi dalih haji lan mbubaraké ocak Yanisari, nglèngsèraké Osman II lan ndhawuhaké nyekik dhèwèké ing pakunjaran Yedikule. Miturut artikel 'Osman II' ing Ensiklopedi Islam TDV, kedadéan iki minangka kasus kapisan ing sajarah Utsmaniyah sultan dipatèni kanthi terang-terangan déning pambrontakan militèr, lan nyebabaké retak jero ing sesambungan wangsa karo wadyabala. Jam-jam pungkasané mangkéné: nalika upayané ngungsi ing omahé agha Yanisari Ali Agha ora ngasilaké apa-apa, sultan, miturut tembungé TDV, 'kanthi kahanan sing ngenes, sirahé tanpa tutup, panganggoné morat-marit' ditumpakaké jaran èlèk lan, ing satengahé pisuhan abot, digawa dhisik menyang Orta Cami, panggonané Mustafa I, banjur ing sawisé awan dina iku menyang Yedikule; miturut sawetara sejarawan, kanggo mbuktèkaké sédané, kuping lan irungé dikethok lan dituduhaké marang ibuné Mustafa I. Sawisé kedadéan iku Mustafa I diunggahaké ing tahta kanggo kaping pindho. Kedadéan sing disebut 'Hâile-i Osmâniye' (bilai Osman) iki ngrusak kanthi tetep imbangan kraton-ocak lan miwiti perdebatan bab legitimasi sing bakal lumaku nganti seabad.", "cf706a0a"]},
"OLAYLAR_EK7:1622-05-20:1":{"b": ["Mustafa I diunggahaké ing tahta kanggo kaping pindho", "34a0b29a"], "d": ["Sawisé Osman Anom dipatèni Yanisari, amarga ora ana anggota lanang diwasa liya ing wangsa, Mustafa I diunggahaké ing tahta kanggo kaping pindho. Miturut artikel 'Mustafa I' ing Ensiklopedi Islam TDV, pamaréntahan kaping pindho iki, ora béda karo sing sadurungé, liwat tanpa dhèwèké kanthi nyata bisa ngurus perkara nagara, lan pamaréntahan nagara ana ing tangané para wazir lan valide sultan. Mangsa patbelas sasi iki rampung ing 1623 kanthi jumenengé Murad IV.", "0fb39afd"]},
"OLAYLAR_EK7:1633-09-01:0":{"b": ["Kobongan Cibali", "3e42fb08"], "d": ["Kobongan sing dumadi ing Cibali lan cepet sumebar amarga angin ndadèkaké pérangan gedhé Istanbul dadi awu; miturut artikel 'Istanbul' ing Ensiklopedi Islam TDV, sumber jaman iku nyritakaké yèn ewonan omah kobong. Digandhèngaké kobongan iku karo wangunan omah kayu lan udud tembako dadi alasan langsung kanggo larangan keras tembako lan warung kopi sing ora suwé banjur diumumaké Murad IV. Bilai iku mung salah siji saka kobongan gedhé sing bola-bali ing Istanbul jaman iku.", "580b710f"]},
"OLAYLAR_EK7:1633-10-01:0":{"b": ["Larangan tembako lan warung kopi déning Murad IV", "5dd71297"], "d": ["Sawisé Kobongan Cibali, amarga kuwatir bab geni lan katentreman, Murad IV nglarang udud tembako lan warung kopi; sing ora manut diukum abot, kalebu ukuman pati. Miturut artikel 'Murad IV' ing Ensiklopedi Islam TDV, sultan nindakaké pulitik dhisiplin njero sing ketat banget nganti dhèwèké dhéwé mlaku ing dalan-dalan kutha nyamar kanggo ngawasi larangan iku. Tindakan keras iki dinilai minangka pérangan saka upayané Murad IV ngadegaké manèh wewenang pusat.", "cc3ae964"]},
"OLAYLAR_EK7:1637-01-01:0":{"b": ["Pageblug pès ing Istanbul", "f33f58c5"], "d": ["Ing jaman Murad IV, Istanbul diguncang pageblug pès abot sing nggebug pérangan wigati pendhudhuk; dagang ing njero kutha lan urip saben dina kaganggu pirang-pirang sasi. Artikel 'Istanbul' ing Ensiklopedi Islam TDV nyathet yèn pageblug sing bola-bali ing abad kaping 17 banget nggebug imbangan pendhudhuk kutha. Nalika pageblug, kraton lan golongan dhuwur sauntara ngalih menyang kebon lan pesanggrahan ing njaba kutha.", "2dc59aee"]},
"OLAYLAR_EK7:1638-06-01:0":{"b": ["Mabur nganggo swiwi Hezarfen Ahmed Çelebi (dongèng)", "df474c04"], "d": ["Miturut crita sing dituturaké Evliya Çelebi, Hezarfen Ahmed Çelebi kasil ngglayang saka Menara Galata nganti Üsküdar nganggo swiwi gawéané dhéwé; sanadyan kepastian sajarahé diperdebataké, kedadéan iki dadi lambang daya khayal tèknik. Sultan, sing wiwitané mènèhi ganjaran marang Hezarfen, banjur mbuwang dhèwèké menyang Aljir amarga geger sing ditimbulaké kedadéan iku.", "f1671c60"]},
"OLAYLAR_EK7:1642-01-01:0":{"b": ["Cinci Hoca Hüseyin Efendi olèh pangaribawa ing kraton", "41d21572"], "d": ["Hüseyin Efendi, dhukun suwuk sing ditimbali menyang kraton kanggo nambani lara jiwa Sultan Ibrahim, ora suwé olèh kapercayan sultan lan munggah nganti dadi kazasker Anatolia. Miturut artikel 'Hüseyin Efendi, Cinci Hoca' ing Ensiklopedi Islam TDV, dhèwèké nggunakaké pangaribawa iku kanggo nglumpukaké bandha lan melu campur ing kedadéan pulitik jaman iku. Sawisé sédané Ibrahim, dhèwèké dicopot saka kabèh jabatané lan diukum pati ing 1648.", "af40c3d4"]},
"OLAYLAR_EK7:1644-01-31:0":{"b": ["Paukuman pati Kemankeş Mustafa Pasya", "0ecc8030"], "d": ["Kemankeş Mustafa Pasya, sing dadi wazir agung wiwit jaman Murad IV lan liwat réformasi keuangané nggawa turahan gedhé menyang kas nagara, diukum pati kanthi dicekik sawisé saingané ing kraton mangaribawani Ibrahim lan nudhuh dhèwèké nggawé pambrontakan Yanisari. Miturut artikel 'Kemankeş Mustafa Pasha' ing Ensiklopedi Islam TDV, paukuman patiné kelakon tanggal 21 Dzulkaidah 1053 / 31 Januari 1644: Kemankeş Kara Mustafa Pasya dicekik algojo Kara Ali ing Pasar Hocapaşa lan disarèkaké ing cungkupé dhéwé ing Çarşıkapı. Sédané diélingi minangka conto sing nyolok bab ora tetepé jabatan wazir agung ing jaman iku, lan mungkasi mangsa cendhak réformasi sing ketat.", "9ae1d459"]},
"OLAYLAR_EK7:1645-04-01:0":{"b": ["Ekspedisi Kreta diputusaké ing diwan lan armada budhal", "9076827e"], "d": ["Ing Diwan Agung diputusaké mbukak ekspedisi gedhé menyang pulo Kreta duwèké Venesia, lan armada Utsmaniyah sing dipimpin kapudan pasya budhal saka Istanbul menyang Kreta. Miturut artikel 'Kreta' ing Ensiklopedi Islam TDV, keputusan iki dadi wiwitan pulitik mangsa pangepungan lan perang dawa sing lumaku udakara selawé taun. Dibukaké ekspedisi iku, minangka usaha pulitik manca paling gedhé ing jaman Ibrahim, nuwuhaké perdebatan amba ing antarané para penggedhé nagara.", "da4feb76"]},
"OLAYLAR_EK7:1648-08-08:0":{"b": ["Jumenengé Mehmed IV nalika umur pitung taun", "a197a3bc"], "d": ["Sanalika sawisé Ibrahim dilèngsèraké, putrané, Mehmed, sing lagi umur pitung taun, diunggahaké ing tahta lan dadi sultan kanthi gelar Mehmed IV. Miturut artikel 'Mehmed IV' ing Ensiklopedi Islam TDV, jumeneng ing umur sing semono enomé ndadèkaké rebutan pangaribawa ing njero kraton antarané embahé, Kösem Sultan, lan ibuné, Turhan Sultan, saya panas. Rebutan kakuwasan iki bakal rampung ing 1651 kanthi dipatèniné Kösem Sultan.", "aa8955d5"]},
"OLAYLAR_EK7:1652-06-20:0":{"b": ["Réformasi anggaran imbang Tarhuncu Ahmed Pasya", "376fc7f2"], "d": ["Wazir Agung Tarhuncu Ahmed Pasya, kanggo ngatasi krisis keuangan sing dijalari taun-taun dawa perang, nindakaké program ngirit sing keras, kalebu ngenani ragad kraton, lan nyusun anggaran imbang kapisan sing dikenal ing sajarah Utsmaniyah (layiha tarhuncu). Miturut artikel 'Tarhuncu Ahmed Pasha' ing Ensiklopedi Islam TDV, réformasi iki nggawa turahan gedhé menyang kas nagara, nanging nuwuhaké ora seneng sing amba ing kalangan kraton lan birokrasi dhuwur. Ora seneng iku setaun sabanjuré bakal njalari dhèwèké diukum pati.", "c837950b"]},
"OLAYLAR_EK7:1656-03-04:0":{"b": ["Kedadéan Wit Çınar (Vak'a-i Vakvakiye)", "4c6ed90f"], "d": ["Miturut artikel Çınar Vak'ası ing Ensiklopedi Islam TDV, Yanisari lan sipahi sing bali saka ekspedisi Kreta tanpa dibayar brontak ing Istanbul lan njaluk paukuman pati kanggo para negarawan sing dituduh korupsi. Usulan Wazir Agung Zurnazen Mustafa Pasya bab nyita bandha lan mbuwang ora ditampa; dhisik telung pejabat, banjur cedhak telung puluh negarawan diukum pati lan jisimé digantung ing wit-wit çınar ing Alun-alun Sultanahmet. Mula kedadéan iku disebut Çınar Vak'ası.", "f187180a"]},
"OLAYLAR_EK7:1656-09-15:0":{"b": ["Köprülü Mehmed Pasya diangkat dadi wazir agung kanthi tampa mawa syarat", "3a6b7f8f"], "d": ["Miturut artikel Köprülü Mehmed Pasha ing Ensiklopedi Islam TDV, Köprülü Mehmed Pasya, sing umuré cedhak wolung puluh taun, lagi nampa cap sawisé Valide Turhan Sultan lan Mehmed IV sarujuk karo syarat-syarat abot sing diaturaké — pengangkatané ora diganggu lan omongan sing nyerang dhèwèké ora dipercaya. Dhèwèké wiwit njabat tanggal 26 Dzulkaidah 1066 nggantèni Boynueğri Mehmed Pasya lan miwiti ngadegaké manèh dhisiplin nagara kanthi keras.", "066ec089"]},
"OLAYLAR_EK7:1656-10-01:0":{"b": ["Gerakan Kadızadeli ditindhes déning Köprülü Mehmed Pasya", "5ec3ce84"], "d": ["Miturut artikel Kadızâdeliler ing Ensiklopedi Islam TDV, sanalika njabat, Köprülü Mehmed Pasya nangani pasulayan agama antarané golongané Kadızâde Mehmed Efendi lan para pandhèrèk tarékat. Sawisé rembugan karo ulama, sanadyan dhèwèké ngetokaké firman paukuman pati kanggo para pimpinan gerakan, Üstüvânî Mehmed Efendi, Türk Ahmed lan Divâne Mustafa, ukuman iku diowahi dadi pambuwangan lan wong telu iku dikirim menyang Siprus; kanthi mangkono tahap kaping pindho gerakan iku rampung.", "a6f49f27"]},
"OLAYLAR_EK7:1660-07-15:0":{"b": ["Kobongan gedhé ing Istanbul: Ağakapısı kobong", "b9253b66"], "d": ["Miturut artikel Ağakapısı ing Ensiklopedi Islam TDV, ing kobongan gedhé sing dumadi ing Juli 1660 jaman Mehmed IV, Ağakapısı, markas resmi agha Yanisari, kobong entèk lan banjur dibangun manèh. Kobongan iki salah siji kobongan gedhé kutha sing bola-bali nggebug Istanbul jaman iku.", "f9ae495b"]},
"OLAYLAR_EK7:1661-11-01:0":{"b": ["Köprülüzade Fazıl Ahmed Pasya diangkat dadi wazir agung", "c1999b5c"], "d": ["Miturut artikel Köprülüzade Fazıl Ahmed Pasha ing Ensiklopedi Islam TDV, sawisé sédané ramané, Köprülü Mehmed Pasya, dhèwèké diangkat dadi wazir agung tanggal 8 Rabiulawal 1072 (1 November 1661). Béda karo ramané, Fazıl Ahmed Pasya dikenal alus budiné, taat agama lan pangayom ulama lan seniman; sajroné luwih saka limalas taun dadi wazir agung, dhèwèké ngedegaké perpustakaan lan lembaga amal ing Istanbul lan tanah sing ditaklukaké.", "25ea9a1e"]},
"OLAYLAR_EK7:1665-06-01:0":{"b": ["Vânî Mehmed Efendi diangkat dadi juru khotbah Yeni Cami lan guru sultan", "7ea6aaae"], "d": ["Miturut artikel Mehmed Efendi, Vânî ing Ensiklopedi Islam TDV, Vânî Mehmed Efendi, sing ditimbali menyang Istanbul nalika Köprülüzade Fazıl Ahmed Pasya dadi wazir agung lan diaturaké marang Mehmed IV, ora suwé olèh kawigatèn raket saka sultan. Ing 1665 dhèwèké diangkat dadi juru khotbah Yeni Cami lan guru sultan, lan dadi salah siji ahli agama paling gedhé pangaribawané ing kraton.", "3b1a8c25"]},
"OLAYLAR_EK7:1676-11-05:0":{"b": ["Merzifonlu Kara Mustafa Pasya diangkat dadi wazir agung", "3d1e836c"], "d": ["Miturut artikel Merzifonlu Kara Mustafa Pasha ing Ensiklopedi Islam TDV, sawisé sédané Fazıl Ahmed Pasya, dhèwèké diangkat dadi wazir agung tanggal 28 Syakban 1087 (5 November 1676). Minangka mantu lan asuhané kulawarga Köprülü sing pengalamané suwé ing pamaréntahan nagara, Merzifonlu dadi salah siji wazir agung paling kuwat lan paling gedhé pangaribawané ing jaman Mehmed IV.", "364f6283"]},
"OLAYLAR_EK7:1685-10-12:0":{"b": ["Sédané Vânî Mehmed Efendi ing pambuwangan", "cda714aa"], "d": ["Miturut artikel Mehmed Efendi, Vânî ing Ensiklopedi Islam TDV, Vânî Mehmed Efendi, sing diétung minangka salah siji tokoh utama sing ndadèkaké sultan sarujuk karo ekspedisi Wina, sawisé ekspedisi iku rampung kanthi ambyar, kéilangan pangaribawa amarga tekanan umum lan dibuwang menyang kutha cilik Kestel ing Bursa. Dhèwèké séda ing kono tanggal 14 Dzulkaidah 1096 (12 Oktober 1685) lan disarèkaké ing lawang mlebu mesjid sing dibangun kanthi dhawuhé dhéwé.", "d8dc341f"]},
"OLAYLAR_EK7:1689-10-25:0":{"b": ["Köprülüzade Fazıl Mustafa Pasya diangkat dadi wazir agung lan réformasi keuangané", "b048570e"], "d": ["Miturut artikel Köprülüzade Fazıl Mustafa Pasha ing Ensiklopedi Islam TDV, Fazıl Mustafa Pasya, sing diangkat dadi wazir agung tanggal 11 Muharam 1101 (25 Oktober 1689), nata manèh cara nariki jizyah miturut dhasar syariat, nglawan inflasi dhuwit mangır lan nguwataké kas nagara kanthi mindhah sumber dana saka lembaga kraton. Dhèwèké uga nguwataké pamaréntahan dhaérah nganggo pejabat sing bisa dipercaya lan ndhawuhaké ngedegaké majelis lokal sing mèmper diwan pusat.", "57c6c63d"]},
"OLAYLAR_EK7:1695-01-01:0":{"b": ["Sistem malikâne wiwit lumaku", "316b8426"], "d": ["Miturut artikel Mâlikâne ing Ensiklopedi Islam TDV, ing prapatan pungkasan abad kaping 17, mundhaké ragad perang lan mudhuné pemasukan amarga ilangé tanah ndadèkaké kas nagara kena krisis keuangan abot. Ing sistem malikâne, sing wiwit lumaku taun 1106 (1695), para juru tariki pajeg diwènèhi hak pajeg tetep saumur urip, lan dorongan kanggo njaga produksi diadegaké nggantèni pemerasan jangka cendhak.", "f564e96c"]},
"OLAYLAR_EK7:1695-02-06:0":{"b": ["Jumenengé Mustafa II", "b53656c7"], "d": ["Miturut artikel Mustafa II ing Ensiklopedi Islam TDV, Mustafa II, sing munggah tahta nalika umur telung puluh siji, ngumumaké kasultanané tanpa ngentèni palilah wazir agung lan syaikhul Islam; upacara nyandhang pedhang dianakaké sawetara dina sawisé ing Eski Cami. Sultan sing munggah tahta ing mangsa nalika perang ing pirang-pirang front isih lumaku sawisé kekalahan Wina iku dadi sultan Utsmaniyah pungkasan sing budhal perang dhéwé.", "6cd0fed9"]},
"OLAYLAR_EK7:1695-05-25:0":{"b": ["Feyzullah Efendi diangkat dadi syaikhul Islam kanggo kaping pindho", "1cf14cff"], "d": ["Miturut artikel Feyzullah Efendi, Seyyid ing Ensiklopedi Islam TDV, sawisé jumenengé Mustafa II, dhèwèké diangkat dadi syaikhul Islam kanggo kaping pindho tanggal 11 Sawal 1106 (25 Mei 1695). Pangaribawané marang sultan saya gedhé sajroné mangsa jabatan iki, sing lumaku luwih saka wolung taun.", "a2d4ab3e"]},
"OLAYLAR_EK7:1703-03-01:0":{"b": ["Feyzullah Efendi ndadèkaké anak-anaké pejabat dhuwur lan reaksi sing saya nglumpuk", "a6398280"], "d": ["Miturut artikel Feyzullah Efendi, Seyyid ing Ensiklopedi Islam TDV, syaikhul Islam iku olèh saka Mustafa II firman sing durung tau ana padhané, yaiku yèn putrané, Fethullah Efendi, bakal dadi syaikhul Islam sawisé dhèwèké, lan dhèwèké manggonaké sanak-seduluré ing jabatan dhuwur nalika isih enom. Praktik iki nuwuhaké ora seneng amba ing golongan ilmiye, prajurit lan warga Istanbul; digabung karo kabar yèn ibu kutha bakal dipindhah menyang Edirne, iki nyawisaké dalan kanggo Kedadéan Edirne 1703.", "34c068d3"]},
"OLAYLAR_EK7:1703-07-17:0":{"b": ["Wiwitan Kedadéan Edirne", "5a106458"], "d": ["Miturut artikel TDV 'Edirne Vak'ası', gerakan sing diwiwiti pambrontakan prajurit sing ora bisa nampa ulufe ora suwé dadi pambrontakan amba sing diéloni Yanisari, santri madrasah, bakul lan rakyat. Sasaran utama pambrontakan yaiku Syaikhul Islam Feyzullah Efendi, sing diarani kakèhan melu campur ing urusan nagara. Massa udakara 60.000 wong mlaku saka Istanbul menyang Edirne.", "201120ba"]},
"OLAYLAR_EK7:1718-05-09:0":{"b": ["Mangsa wazir agung Nevşehirli Damad Ibrahim Pasya", "8d627a6f"], "d": ["Miturut artikel TDV 'Damad İbrâhim Paşa, Nevşehirli', nalika rundhingan damai karo Austria isih lumaku, dhèwèké diangkat dadi wazir agung tanggal 8 Jumadilakir 1130 (9 Mei 1718) lan sanalika diangkat banjur nengenaké rundhingan sing bakal mungkasi perang; rong sasi sawisé Prajanjian Passarowitz ditapaktangani (21 Juli 1718). Miturut tembungé TDV, 'dhèwèké kepéngin ngurusi perkara sosial lan keuangan, lan kangen mangsa damai sing bisa ndadèkaké wong lali marang perang-perang sing pirang-pirang taun rampung kanthi kalah'. Kanthi réformasi keuangan, dhèwèké ngurangi gajih prajurit lan nggawé turahan gedhé ing kas nagara. Mangsa wazir agungé, sing bakal lumaku rolas taun, dadi kerangka pulitik mangsa sing nggawa jenengé (Mangsa Tulip).", "5874203b"]},
"OLAYLAR_EK7:1720-06-01:0":{"b": ["Adegé Ocak Tulumbacı", "f58b0d97"], "d": ["Miturut artikel TDV 'Tulumbacı', sawisé Gerçek Dâvud, sing bali saka ekspedisi Morea 1715, nuduhaké kasil nganggo pompa geni (tulumba) ing kobongan Istanbul, Wazir Agung Nevşehirli Damad Ibrahim Pasya ngutus dhèwèké ngedegaké korps pemadam geni resmi. Korps sing diadegaké ing Barak Acemi Oğlanları kanthi enem opsir lan sèket prajurit iku tekan 150 wong ing 1724 lan 461 ing 1755. Dâvud tetep dadi pimpinan korps nganti sédané ing 1733.", "3b860f0f"]},
"OLAYLAR_EK7:1722-06-01:0":{"b": ["Pambangunan Pesanggrahan Sa'dabad", "aec9c65e"], "d": ["Miturut artikel TDV 'Sâdâbâd', ing pinggir kali Kağıthane dibangun komplèks hiburan lan plesiran sing amba, isiné pesanggrahan, kanal, pancuran lan gazebo sing kapengaruh arsitèktur kraton Prancis. Sa'dabad, sing dadi panggonan hiburan paling disenengi ing jaman iku, dadi langgeng ing geguritané pujangga Nedim. Komplèks iku umumé dirusak nalika Pambrontakan Patrona Halil 1730.", "2698478e"]},
"OLAYLAR_EK7:1722-09-03:0":{"b": ["Pasukan Rusia ngrebut Derbend: ekspedisi Kaspia Peter I", "c2b269f9"], "d": ["Nalika Nagara Safawiyah kèrid menyang kekisruhan njero amarga serbuan Afghan, Tsar Rusia Peter I budhal ekspedisi kanggo ngrebut tanah Iran ing pesisir Kaspia; kutha pesisir Derbend nyerah marang pasukan Rusia tanpa perlawanan sing wigati. Miturut artikel Derbend ing Ensiklopedi Islam TDV, pendhudhukan iki dadi wiwitan kakuwasan Rusia sauntara sing lumaku telulas taun; Nagara Utsmaniyah uga njupuk kauntungan saka kekisruhan sing padha lan ngarah menyang pérangan kulon Kaukasus. Wadyabalané wis ndharat saka Astrakhan liwat segara ing teluk Agrakhan, lan saka kono mlaku dharatan sadawané pesisir liwat Tarku; syamkhal Tarku nyuguhi Peter lan mlebu dadi bawahan Rusia.", "4220bd4e"]},
"OLAYLAR_EK7:1726-01-01:0":{"b": ["Dibubaraké syamkhalat Tarku: pamaréntahan Rusia langsung", "b0f029c6"], "d": ["Syamkhal Tarku, Adil-Girey, sing ing 1722 nyuguhi Peter lan mlebu dadi bawahan Rusia, brontak ing 1725; Yeropkin ngrusak Tarku ing mangsa gugur 1725, syamkhal dicekel lan dibuwang ing tengah Mei 1726, lan syamkhalat dibubaraké. Tarku lan sakiwa-tengené tetep ana ing pamaréntahan Rusia langsung nganti Prajanjian Ganja 1735.", "32bb2cc9"]},
"OLAYLAR_EK7:1727-07-01:0":{"b": ["Ibrahim Müteferrika olèh idin ngedegaké percétakan", "0659dd0a"], "d": ["Miturut artikel TDV 'İbrâhim Müteferrika', kanthi firman Ahmed III lan fatwa Syaikhul Islam Yenişehirli Abdullah Efendi, idin diwènèhaké kanggo ngedegaké percétakan Turki kapisan. Percétakan iku wiwit lumaku ing kampung Yavuzselim, Istanbul. Nganti sédané ing 1747, Müteferrika nyétak pitulas karya ing telulikur jilid.", "2b37f2a0"]},
"OLAYLAR_EK7:1729-02-01:0":{"b": ["Rampungé buku cithakan kapisan, Kamus Vankulu", "684700e8"], "d": ["Miturut artikel TDV 'İbrâhim Müteferrika', terjemahan basa Turki saka Sihah al-Jawhari (Kamus Vankulu), karya kapisan percétakan iku, rampung ing wiwitan 1729. Iki buku kapisan sing dicithak nganggo aksara Arab ing wilayah Utsmaniyah lan dianggep wiwitan sajarah percétakan Turki.", "d204cfc9"]},
"OLAYLAR_EK7:1730-10-01:0":{"b": ["Paukuman pati Nevşehirli Damad Ibrahim Pasya", "50c64341"], "d": ["Miturut artikel TDV 'Damad İbrâhim Paşa, Nevşehirli', jisimé wazir agung, sing dipatèni ing kraton nalika Pambrontakan Patrona Halil, digèrèd ing dalan-dalan Istanbul lan ditinggal cedhak Pancuran Ahmed III ing Alun-alun Sultanahmet. Rolas taun mangsa wazir agungé lan Mangsa Tulip kanthi mangkono rampung kanthi getihen.", "3af021b4"]},
"OLAYLAR_EK7:1730-10-02:0":{"b": ["Lèngsèré Ahmed III, jumenengé Mahmud I", "a43f5d40"], "d": ["Miturut artikel TDV 'Mahmud I', ngadhepi tekanan para pambrontak, Ahmed III lèngsèr sawisé olèh jaminan kanggo awaké lan anak-anaké, lan dhèwèké dhéwé ngunggahaké ponakané, Pangéran Mahmud, ing tahta. Mahmud I, sing lungguh ing tahta kanthi pitutur pamané, 'cekelana dhéwé urusan nagara, aja percaya sapa waé', minangka pagawéan kapisan miwiti matahaké pangaribawané golongan pambrontak sing ngunggahaké dhèwèké.", "32260f8c"]},
"OLAYLAR_EK7:1733-06-01:0":{"b": ["Humbaracı Ahmed Pasya ndandani korps artileri", "ea3a7c64"], "d": ["Miturut artikel TDV 'Humbaracı', Ahmed Pasya, opsir asal Prancis sing mlebu Islam, ing jaman Wazir Agung Hekimoğlu Ali Pasya miwiti ndandani organisasi pembom sing nampa gajih miturut cara Éropah. Dhèwèké ngedegaké susunan anyar 601 wong sing langsung kaiket marang wazir agung, 300 nampa gajih lan 301 nganggo tanah lungguh (timar). Nganggo teknologi jaman iku, dhèwèké ndhawuhaké nggawé 100 mortir lan 50.000 pelor mriem.", "bf4e60c1"]},
"OLAYLAR_EK7:1734-06-01:0":{"b": ["Adegé Hendesehane (conto kapisan sekolah teknik)", "a77ed1f3"], "d": ["Miturut artikel TDV 'Mahmud I', Humbaracı Ahmed Pasya, kanthi ngedegaké ing Üsküdar Hendesehane, sing uga disebut Humbarahane, mènèhi pendhidhikan militèr sing adhedhasar matématika lan géométri marang murid sing dipilih saka abdi kraton lan bostancı. Lembaga iki dianggep conto kapisan sekolah-sekolah teknik sing bakal berkembang ing mangsa sabanjuré.", "84b5af85"]},
"OLAYLAR_EK7:1735-03-21:0":{"b": ["Prajanjian Ganja: Derbend lan Baku dibalèkaké marang Iran", "ff19d531"], "d": ["Rusia, sing golèk sekutu karo Iran nglawan ancaman Utsmaniyah, liwat Prajanjian Ganja mbalèkaké kutha-kutha pesisir Kaspia sing wis dicekel telulas taun marang Iran sing dipimpin Nadir Khan (durung njupuk gelar syah). Miturut artikel Derbend ing Ensiklopedi Islam TDV, mundur iki asil saka ora gelemé Rusia perang ing rong front (Utsmaniyah lan Iran) bebarengan ing sisih kidul, lan nguwataké prabawa militèr Nadir sing mbukak dalan kanggo munggahé ing tahta sawetara taun sabanjuré. Tarki (Tarku) ing sangisoré pamaréntahan Rusia uga bali menyang pihak Iran liwat mundur iki (ing peta dinggo dina Ganja). Salyan lan Syabran ing sangisoré pamaréntahan Rusia uga bali menyang pihak Iran liwat mundur iki (ora ana dina mirunggan kanggo panggonan iku ing sumber, ing peta dinggo dina Ganja — kira-kira sing diterangaké).", "711f14d9"]},
"OLAYLAR_EK7:1736-03-08:0":{"b": ["Jumenengé Nadir Syah ing Ara-ara Mughan: pungkasan nyata wangsa Safawiyah", "4f640979"], "d": ["Miturut artikel Nadir Shah ing Ensiklopedi Islam TDV, kurultay sing nglumpuk ing Ara-ara Mughan, isiné udakara rong puluh èwu wong, ngeyel njaluk supaya dhèwèké mimpin Iran; Nadir nampa panawaran iki kanthi syarat pangertèn Syiah ekstrem sing nyebabaké perang antarané Safawiyah lan Utsmaniyah ditinggal lan madzhab Ja'fari sing moderat dianggo, lan tanggal 24 Sawal 1148 (8 Maret 1736) munggah tahta kanthi gelar Nadir Syah. Iki ateges pungkasané kanyatan wangsa Safawiyah sing umuré rong abad lan adegé wangsa Afshariyah.", "7f742f06"]},
"OLAYLAR_EK7:1739-06-01:0":{"b": ["Wiwitan pageblug pès ing Istanbul", "9fa82b56"], "d": ["Miturut artikel TDV 'Tâun', pageblug pès sing nggebug tlatah Islam antarané 1739-1743 uga nyerang Istanbul ing mangsa iki. Artikel iku nyathet yèn pageblug abad kaping 18 lumaku rada entheng dibandhingaké karo abad-abad sadurungé. Taun 1713, 1719, 1728-1729 lan 1759-1765 uga diétung ing mangsa pageblug.", "d650b99e"]},
"OLAYLAR_EK7:1755-09-29:0":{"b": ["Kobongan Hocapaşa", "321c7d0d"], "d": ["Miturut artikel TDV 'Mesjid Fatma Sultan', kobongan Hocapaşa sing dumadi ing wayah bengi ngrusak Bab-i Ali lan sakiwa-tengené; dikira-kira Mesjid Fatma Sultan ing tlatah iku uga rusak amarga kobongan iki. Bilai iki, salah siji kobongan gedhé sing nggebug Istanbul ing jaman Osman III, njalari karusakan abot ing pusat dagang lan pamaréntahan kutha.", "3554d781"]},
"OLAYLAR_EK7:1757-02-28:0":{"b": ["Mangsa wazir agung Koca Ragıp Mehmed Pasya", "a1846910"], "d": ["Ragıp Pasya, sing misuwur minangka pujangga lan diplomat, diangkat dadi wazir agung déning Osman III (sawisé sédané Osman III ing Oktober 1757 dhèwèké nerusaké jabatan lan nampa cap anyar saka Mustafa III). Nalika Perang Pitung Taun isih lumaku, dhèwèké nindakaké pulitik manca sing imbang sing njaga Nagara Utsmaniyah ana ing njaba pasulayan Éropah. Sajroné mangsa wazir agungé sing bakal lumaku enem taun, dhèwèké uga nggatèkaké kegiatan budaya kaya ngedegaké perpustakaan.", "d3682725"]},
"OLAYLAR_EK7:1763-04-08:0":{"b": ["Sédané Ragıp Pasya", "6bc19323"], "d": ["Ragıp Pasya séda sawisé enem taun dadi wazir agung. Kanthi sédané, mangsa wazir agung sing paling dawa lan imbang ing jaman Mustafa III rampung.", "7da43eab"]},
"OLAYLAR_EK7:1766-05-01:0":{"b": ["Lindhu gedhé Istanbul lan ambruké Mesjid Fatih", "2475b4dc"], "d": ["Miturut artikel TDV 'Mesjid lan Komplèks Fatih', ing lindhu gedhé 1766 kubah utama mesjid ambruk babar pisan lan témboké rusak ora bisa didandani manèh. Pambangunan manèh sing diwiwiti ing 1767 kanthi dhawuh Mustafa III ing sangisoré arsitèk Sarım Ibrahim Efendi lan İzzet Mehmed Bey rampung ing 1771 kanthi rancangan anyar sing béda karo rancangan lawas.", "680af5a8"]},
"OLAYLAR_EK7:1772-10-01:0":{"b": ["Uji coba sekolah artileri umur cendhak sing dipimpin Baron de Tott", "4192260c"], "d": ["Miturut artikel TDV 'Mühendishâne-i Bahrî-i Hümâyun', kegagalan ing Perang Utsmaniyah-Rusia 1768 mbukak butuhé pendhidhikan teknik militèr; sekolah artileri umur cendhak sing dibukak kanthi bantuan opsir Prancis Baron de Tott wiwit lumaku ing Oktober 1772 nanging ora ana asilé. Uji coba iki dianggep sing ngrintis Mühendishâne-i Bahrî-i Hümâyun sing bakal diadegaké ing 1775.", "1b031ce8"]},
"OLAYLAR_EK7:1789-04-07:0":{"b": ["Selim III munggah tahta", "00d046d9"], "d": ["Sawisé sédané Abdülhamid I, ponakané, Selim III, munggah tahta. Miturut artikel Selim III ing Ensiklopedi Islam TDV, sultan anyar sing wiwit dadi pangéran wis kasengsem marang réformasi wadyabala Éropah iku, ora suwé sawisé jumeneng, wiwit ndhawuhaké nyusun program pembaharuan sing radikal. Sawetara taun sabanjuré program iki bakal dikenal kanthi jeneng Nizam-ı Cedid.", "ec094618"]},
"OLAYLAR_EK7:1792-06-01:0":{"b": ["Program réformasi Nizam-ı Cedid wiwit disusun", "eff78a68"], "d": ["Selim III ndhawuhaké nyusun program pembaharuan sing jangkep miturut layiha sing dijaluk saka para negarawan lan ahli manca. Miturut artikel Nizâm-ı Cedîd ing Ensiklopedi Islam TDV, program iki ora mung winates ing ngedegaké wadyabala anyar; program iku dadi gerakan réformasi amba sing uga nyakup keuangan, pamaréntahan dhaérah lan diplomasi. Sajroné limalas taun sabanjuré program iku bakal nemu pandhukung lan penentang.", "7efcd62f"]},
"OLAYLAR_EK7:1793-03-01:0":{"b": ["Kedutaan tetep diadegaké ing ibu kutha-ibu kutha Éropah", "2e9dc8a1"], "d": ["Selim III, kanggo sepisanan ing sajarah Nagara Utsmaniyah, ngirim duta tetep sing bakal nyambut gawé terus ing pusat-pusat gedhé Éropah. Miturut artikel Elçi ing Ensiklopedi Islam TDV, langkah iki mènèhi organisasi tetep marang diplomasi Utsmaniyah, sing nganti wektu iku mung dilakokaké liwat utusan sauntara lan sepisanan. Tugas utama kedutaan anyar yaiku kanthi ajeg nglapuraké menyang Istanbul perkembangan pulitik lan militèr ing Éropah.", "8fef612b"]},
"OLAYLAR_EK7:1793-06-01:0":{"b": ["Kas Irad-ı Cedid diadegaké", "ae5c8ce2"], "d": ["Kas kapisah diadegaké kanggo nanggung ragad wadyabala Nizam-ı Cedid lan program réformasi. Miturut artikel Esham ing Ensiklopedi Islam TDV, pemasukan kas anyar iku kalebu pengelolaan langsung sawetara mukataa déning nagara lan ngawasi dodolan esham. Pranatan iki minangka upaya nggawé sumber anyar ing njaba sistem keuangan tradhisional.", "ddacec62"]},
"OLAYLAR_EK7:1807-05-25:0":{"b": ["Pambrontakan Kabakçı Mustafa diwiwiti", "b98eee17"], "d": ["Ora seneng sing nglumpuk marang Nizam-ı Cedid pecah nalika prajurit yamak brontak dipimpin Kabakçı Mustafa. Miturut artikel Pambrontakan Kabakçı ing Ensiklopedi Islam TDV, para pambrontak cepet ngrebut kontrol ing Istanbul lan njaluk sirahé para negarawan sing ndhukung Nizam-ı Cedid. Sajroné sawetara dina pambrontakan iku ndadèkaké Selim III dilèngsèraké.", "820bdd75"]},
"OLAYLAR_EK7:1807-05-29:0":{"b": ["Selim III dilèngsèraké", "ff2c30ec"], "d": ["Amarga tekanan pambrontakan Kabakçı Mustafa, Selim III dilèngsèraké kanthi fatwa sing dijupuk saka syaikhul Islam. Miturut artikel Selim III ing Ensiklopedi Islam TDV, keputusan iki dadi wektu nalika mangsa réformasi wolulas taun kanyatané rampung; wadyabala Nizam-ı Cedid uga ora suwé dibubaraké. Selim wiwit dijaga ing Kraton Topkapı.", "d4f1293b"]},
"OLAYLAR_EK7:1807-05-29:1":{"b": ["Mustafa IV munggah tahta", "8f1ac86c"], "d": ["Sanalika sawisé Selim III dilèngsèraké, ponakané, Mustafa IV, diumumaké dadi sultan. Miturut artikel Mustafa IV ing Ensiklopedi Islam TDV, sultan anyar miwiti pamaréntahan ing sangisoré pangaribawané golongan sing nentang Nizam-ı Cedid lan ndhukung pambrontakan. Mangsa cendhak iki dadi tahap ora tetep, nalika wewenang pusat saya ringkih banget.", "58865f17"]},
"OLAYLAR_EK7:1808-07-19:0":{"b": ["Alemdar Mustafa Pasya mlebu Istanbul karo wadyabalané", "0cad3dea"], "d": ["Alemdar Mustafa Pasya, ayan ing Rusçuk, teka ing ngarep Istanbul karo wadyabalané kanthi tujuan ngunggahaké manèh Selim III ing tahta. Miturut artikel Alemdar Mustafa Pasha ing Ensiklopedi Islam TDV, mlebuné ing kutha disambut Mustafa IV dhéwé; nanging sajroné sawetara dina imbangan kakuwatan ing njero kraton bakal owah babar pisan. Mlebuné iki miwiti ranté kedadéan sing ndadèkaké Selim séda lan uga ana jumenengan anyar.", "c042d316"]},
"OLAYLAR_EK7:1808-07-28:0":{"b": ["Selim III dipatèni", "e452f5f6"], "d": ["Ing dina Alemdar Mustafa Pasya ngrebut Bab-i Ali, Selim III dipatèni ing kraton kanthi dhawuh Mustafa IV. Miturut artikel Selim III ing Ensiklopedi Islam TDV, iki keputusan sing dijupuk kanggo nyegah upaya ngunggahaké manèh sultan sing wis dilèngsèraké. Sédané Selim ndadèkaké Mahmud jumeneng ing dina sing padha.", "7d63123d"]},
"OLAYLAR_EK7:1808-07-28:1":{"b": ["Mahmud II munggah tahta", "661c1974"], "d": ["Sawisé Selim III dipatèni, Mahmud, sing kari siji-sijiné anggota lanang wangsa, munggah tahta kanthi dhukungan Alemdar Mustafa Pasya. Miturut artikel Mahmud II ing Ensiklopedi Islam TDV, sultan anyar ngliwati sasi-sasi kapisan pamaréntahané ing sangisoré pangawasané Alemdar, sing ngunggahaké dhèwèké ing tahta, lan ing upaya ngadegaké manèh imbangan antarané para ayan lan pusat. Mangsa iki dadi wiwitan proses réformasi radikal rong puluh taun sabanjuré.", "491f1eb0"]},
"OLAYLAR_EK7:1808-08-15:0":{"b": ["Wadyabala Sekban-ı Cedid diadegaké", "6f9eb5e4"], "d": ["Alemdar Mustafa Pasya ndhawuhaké ngedegaké wadyabala anyar sing piranti lan gamané cara Éropah nggantèni Nizam-ı Cedid sing wis dibubaraké. Miturut artikel Sekbân-ı Cedîd ing Ensiklopedi Islam TDV, kakuwatan telung resimèn iki ing mripaté Yanisari katon minangka ancaman langsung, lan mung sawetara sasi sawisé diadegaké disirnakaké ing pambrontakan Yanisari.", "ba52d1dd"]},
"OLAYLAR_EK7:1809-12-02:0":{"b": ["Tibané Ibrail — jebolan gedhé kapisan ing garis Donau", "ee519321"], "d": ["Ing perang Rusia sing diwiwiti ing 1806, Bèntèng Ibrail ing pinggir lor Kali Donau dikepung lan dibedhili mriem déning pasukan Rusia sing dipimpin Count Kamensky. Ing jeroné ana 4100 prajurit mlaku, 1100 prajurit jaranan lan 260 mriem; bèntèng iku nyerah marang Jenderal Essen amarga kurang pangan. Pucuk lor garis pertahanan Donau kanthi mangkono kabukak.", "12ec2aef"]},
"OLAYLAR_EK7:1810-09-26:0":{"b": ["Rusçuk nyerah — pinggir kidul Kali Donau uga ucul", "084062e8"], "d": ["Rusçuk nglawan pangepungan dawa lan getihen wadyabala Rusia sing dipimpin Count Kamensky; kutha iku nyerah kanthi syarat garnisun lan warga sipil kena ninggalaké kutha kanthi aman. Tibané kutha-bèntèng paling kuwat ing pinggir kidul Donau ngowahi lakuné perang dadi nguntungaké Rusia.", "00685e1d"]},
"OLAYLAR_EK7:1826-05-15:0":{"b": ["Ocak Eşkinci diadegaké", "67c56759"], "d": ["Mahmud II ndhawuhaké ngedegaké unit anyar sing bakal dilatih cara Éropah, isiné prajurit sing dipilih saka njero ocak Yanisari. Miturut artikel Eşkinci Ocağı ing Ensiklopedi Islam TDV, unit iku wiwit latihan tanggal 12 Juni 1826, nanging Yanisari nganggep iki pungkasané ocaké dhéwé. Pambrontakan sing pecah telung dina sabanjuré uga mungkasi umur cendhak Ocak Eşkinci.", "ab923dc4"]},
"OLAYLAR_EK7:1826-06-18:0":{"b": ["Asakir-i Mansure-i Muhammediye diadegaké", "14b84a7e"], "d": ["Sanalika sawisé Ocak Yanisari dibubaraké, Mahmud II ndhawuhaké ngedegaké wadyabala anyar sing teratur lan dilatih cara Éropah minangka gantiné. Miturut artikel Asâkir-i Mansûre-i Muhammediyye ing Ensiklopedi Islam TDV, béda karo uji coba sadurungé, wadyabala iki dadi lembaga tetep kanthi susunan pangkat, program latihan lan sistem gajih. Ing taun-taun sabanjuré wadyabala iki bakal malih dadi wadyabala Nizamiye ing mangsa Tanzimat.", "2e0ee6f7"]},
"OLAYLAR_EK7:1826-06-19:0":{"b": ["Tarékat Bektasyi ditutup", "f7d9a367"], "d": ["Bebarengan karo dibubaraké Ocak Yanisari, tarékat Bektasyi, sing dingertèni nduwé sesambungan agama karo ocak iku, uga dilarang. Miturut artikel Bektaşîlik ing Ensiklopedi Islam TDV, sawetara syekh tekke cilik diukum pati, déné syekh padhépokan Hacı Bektaş dibuwang menyang Amasya lan tekke-tekke dipasrahaké marang pangurusé Naqsyabandiyah. Sanadyan kena pukulan abot iki, tarékat iku nerusaké organisasiné kanthi sesidheman.", "305773c2"]},
"OLAYLAR_EK7:1827-04-29:0":{"b": ["Kedadéan kipas — dalih kanggo pendhudhukan", "e949001e"], "d": ["Ing rundhingan sing dadi tegang amarga utang gandum lawas Prancis marang Aljir durung dibayar, Dayi Husein nggebug konsul Prancis Deval nganggo kipas sing dicekel. Kedadéan sing tuwuh saka padudon utang iki didadèkaké dalih resmi kanggo pendhudhukan sing bakal diwiwiti telung taun sabanjuré.", "0e58142a"]},
"OLAYLAR_EK7:1827-06-16:0":{"b": ["Blokade Prancis ing pesisir Aljazair — pangepungan telung taun", "d0ba97a5"], "d": ["Sawisé kedadéan kipas, Prancis ngeblokade pesisir Aljazair. Blokade lumaku telung taun; dagang segara lan sumber pemasukan ocak digaringaké, lan kakuwatané nglawan disudakaké sadurungé pendhudhukan diwiwiti.", "79d27be2"]},
"OLAYLAR_EK7:1828-06-23:0":{"b": ["Tibané Ibrail kaping pindho — Tsar Nikolai ing ngarep bèntèng", "eb6a8741"], "d": ["Ibrail, sing dibalèkaké marang Utsmaniyah ing 1812 lan dikuwataké manèh ing 1817-1818, dikepung ing April nalika ing jeroné ana 4000 penjaga lan 278 mriem. Komandhané, Ebubekir Pasya, nggawé garis pertahanan anyar; Tsar Nikolai I dhéwé teka ing ngarep bèntèng ing pungkasan Mei. Kutha iku didhudhuki Rusia, nanging bakal dibalèkaké liwat Prajanjian Edirne lan ditinggalaké marang kapangéranan Wallachia.", "b7e53f03"]},
"OLAYLAR_EK7:1829-06-01:0":{"b": ["Fez diumumaké dadi tutup sirah resmi", "f55be4eb"], "d": ["Mahmud II, kanthi owah-owahan radikal ing sandhangan pejabat lan prajurit, ngumumaké fez dadi tutup sirah resmi nggantèni serban. Miturut artikel Fes ing Ensiklopedi Islam TDV, keputusan iki diumumaké liwat hatt-ı hümâyun lan ditindakaké bebarengan karo réformasi gaya Kulon Asâkir-i Mansûre-i Muhammediyye. Owah-owahan iki uga ateges mungkasi hirarki sandhangan tradhisional.", "9739e485"]},
"OLAYLAR_EK7:1829-09-14:0":{"b": ["Akhaltsikhe ditinggalaké marang Rusia — pusat eyalet Çıldır ucul", "e2e00b2a"], "d": ["Akhaltsikhe, sing wiwit Perang Çıldır 1578 ana ing pamaréntahan Utsmaniyah lan dadi pusat eyalet Çıldır, ditinggalaké marang Rusia liwat Prajanjian Edirne sing ditapaktangani ing pungkasan perang 1828-1829. Uculé kutha iku nuwuhaké kasusahan jero ing antarané rakyat lan dadi bahan akèh tembang tangis. Kanthi kedadéan iki Akhalkalaki, Zazalo lan Ts'q'altbila (tlatah Akhaltsikhe–Akhalkalaki) pindhah menyang Rusia.", "bab87a04"]},
"OLAYLAR_EK7:1830-06-14:0":{"b": ["Pendharatan Sidi Ferruch — wadyabala Prancis ing tanah Aljazair", "33327553"], "d": ["Sawisé blokade telung taun, wadyabala pendharatan Prancis sing dipimpin Comte de Bourmont ndharataké prajurit ing teluk Sidi Ferruch ing sisih kulon Aljir. Pasukan sing maju menyang kutha njebol garis pertahanan sajroné telung minggu; tanggal 4 Juli Bèntèng Kaisar sing nguwasani kutha tiba, lan dina sabanjuré Dayi Husein nyerah.", "0d2a2c9a"]},
"OLAYLAR_EK7:1830-08-09:0":{"b": ["Pambuwangan Dayi Husein — pungkasan nyata Ocak Aljazair", "e122403b"], "d": ["Miturut syarat penyerahan, dayi Aljir pungkasan, Husein, bebarengan karo kulawarga lan bandhané, ditokaké saka kutha lan dikirim menyang Napoli. Pamaréntahan ocak, sing ing 1519 kaiket marang Selim I (Yavuz) lan suwéné telung atus taun dadi pangkalan segara Utsmaniyah paling kuwat ing Segara Tengah, kanthi mangkono rampung.", "bf7169cf"]},
"OLAYLAR_EK7:1834-01-01:0":{"b": ["Wadyabala Rusia mundur saka Wallachia lan Moldavia — pungkasan pendhudhukan enem taun", "efdb0275"], "d": ["Ing perang Utsmaniyah-Rusia 1828-1829 wong Rusia wis ndhudhuki Wallachia lan Moldavia, lan sawisé Prajanjian Edirne uga ora mundur nganti ganti rugi perang dibayar. Ing Januari 1834, nalika ganti rugi dikurangi dadi limang yuta, pasukan Rusia ngosongaké Kapangéranan Donau lan voivode anyar diangkat ing kapangéranan loro iku. Kasuzeranan Utsmaniyah bali ing kertas, nanging Rusia njaga pangaribawa sing diadegaké liwat Règlement Organique.", "312a9319"]},
"OLAYLAR_EK7:1834-07-08:0":{"b": ["Organisasi Redif-i Asakir-i Mansure diadegaké", "15947493"], "d": ["Organisasi Redif, minangka pasukan cadhangan sing bakal ndhukung Asâkir-i Mansûre-i Muhammediyye, diadegaké liwat pranatan tanggal 8 Juli 1834. Miturut artikel Redif ing Ensiklopedi Islam TDV, ing sangisoré pimpinan Serasker Koca Hüsrev Pasya, batalyon sing saben-saben isiné udakara sèwu patang atus wong dibentuk ing kaza-kaza dhaérah. Organisasi iku dirancang supaya uga ndhukung keamanan lokal tanpa dijupuk ing dinas terus-terusan.", "ca6cb4a0"]},
"OLAYLAR_EK7:1836-06-01:0":{"b": ["Kementrian Luar Negeri diadegaké", "750c6c7d"], "d": ["Mahmud II mbubaraké jabatan Reisülküttab sing ngurusi urusan manca lan ngedegaké Kementrian Luar Negeri minangka gantiné. Miturut artikel Hariciye Nezâreti ing Ensiklopedi Islam TDV, Mehmed Akif Pasya diangkat dadi mentri kapisan kementrian anyar iku, lan organisasi iku wiwit lumaku ing omahé Rıfat Bey, duta ing Wina. Pranatan iki dadi wiwitan pulitik manca Utsmaniyah dilakokaké miturut dhasar kementrian modhèrn.", "50ebd952"]},
"OLAYLAR_EK7:1838-03-24:0":{"b": ["Meclis-i Vala-yı Ahkam-ı Adliye diadegaké", "69db056e"], "d": ["Mahmud II ndhawuhaké ngedegaké Meclis-i Vâlâ-yı Ahkâm-ı Adliyye minangka majelis tingkat dhuwur kanggo ngrembug undhang-undhang lan pranatan sing bakal disusun. Miturut artikel Meclis-i Vâlâ-yı Ahkâm-ı Adliyye ing Ensiklopedi Islam TDV, majelis iku kanyatané wiwit nyambut gawé tanggal 31 Maret 1838, lan meh kabèh réformasi Tanzimat sabanjuré disusun lan diawasi liwat badan iki. Lembaga iki dadi salah siji pusat paling wigati birokrasi Utsmaniyah modhèrn.", "9346611a"]},
"OLAYLAR_EK7:1853-11-30:0":{"b": ["Serbuan Sinop", "5947e93f"], "d": ["Armada Segara Ireng Rusia, sing dipimpin Laksamana Nakhimov, nyerbu armada Utsmaniyah sing lagi labuh ing plabuhan Sinop tanpa ngumumaké perang; rolas kapal klelep, luwih saka rong èwu prajurit gugur minangka syahid, lan komandhan armada Osman Pasya ditawan. Miturut artikel Sinop ing Ensiklopedi Islam TDV, ing serbuan iku pitu mesjid cilik, rong sekolah, 247 omah lan 170 toko ing kutha uga kobong, lan warga sipil, lima Muslim lan nembelas Kristen, ilang nyawa. Kedadéan sing nggemparaké pamawas umum Éropah minangka 'bilai Sinop' iku dadi pemicu langsung Inggris lan Prancis melu perang ing pihak Utsmaniyah sajroné sawetara sasi.", "89a8c874"]},
"OLAYLAR_EK7:1862-06-27:0":{"b": ["Tasvir-i Efkâr diterbitaké", "506c98e2"], "d": ["Tasvir-i Efkâr sing diterbitaké Şinasi wiwit lumaku minangka koran basa Turki kapapat sawisé Takvîm-i Vekāyi', Cerîde-i Havâdis lan Tercüman-ı Ahvâl. Miturut artikel TDV 'Tasvîr-i Efkâr', koran iku dadi corong gerakan Utsmaniyah Anom ing jaman Namık Kemal, sing mbésuké njupuk alih jabatan pimpinan redaksi.", "72568463"]},
"OLAYLAR_EK7:1867-08-30:0":{"b": ["Paguyuban Utsmaniyah Anom diadegaké", "335fb02d"], "d": ["Para cendhekiawan Utsmaniyah sing mlayu menyang Éropah ing sangisoré pimpinan Mustafa Fazıl Pasya ngatur organisasi kanthi pranatan telulas pasal kanthi jeneng Turki Anom. Miturut artikel TDV 'Yeni Osmanlılar Cemiyeti', golongan iku nyebaraké panjaluk pamaréntahan konstitusional kanthi nerbitaké koran kaya Muhbir lan Hürriyet ing Paris, London lan Jenewa.", "169dff06"]},
"OLAYLAR_EK7:1868-03-05:0":{"b": ["Dhéwan Nagara (Şura-yı Devlet) diadegaké", "b863b306"], "d": ["Meclis-i Ahkâm-ı Adliyye dipérang dadi loro, lan diadegaké Şûrâ-yı Devlet sing nangani urusan administrasi lan Dîvân-ı Ahkâm-ı Adliyye sing ngurusi pengadilan. Miturut artikel TDV 'Şûrâ-yı Devlet', Midhat Pasya diangkat dadi pimpinan kapisan lembaga sing niru Conseil d'État Prancis iku; tujuané yaiku misahaké kakuwasan legislatif, eksekutif lan yudikatif.", "6a4ac9ed"]},
"OLAYLAR_EK7:1869-04-08:0":{"b": ["Irada ngedegé Darülfünun metu", "513704bf"], "d": ["Darülfünun resmi diadegaké liwat irada sing disusun Wazir Agung Ali Pasya lan Mentri Pendhidhikan Safvet Pasya; nanging pawulangan kapisan wis diwiwiti sadurungé, ing 1863. Miturut artikel TDV 'Darülfünun', ing Fèbruari 1870 lembaga iku kanyatané wiwit mulang ing sangisoré pimpinan Hoca Tahsin Efendi, kanthi cabang filsafat-sastra, èlmu pasti lan kukum.", "884a094b"]},
"OLAYLAR_EK7:1869-06-01:0":{"b": ["Pagawéan Mecelle-i Ahkam-ı Adliye diwiwiti", "8abdcbee"], "d": ["Paguyuban Mecelle, sing dibentuk dipimpin Ahmed Cevdet Pasya, ketua Dîvân-ı Ahkâm-ı Adliyye, miwiti nyawisaké kitab undhang-undhang perdata adhedhasar fikih Hanafi. Miturut artikel TDV 'Mecelle-i Ahkâm-ı Adliyye', pérangan pungkasan karya iku, sing isiné nembelas kitab lan 1851 pasal, rampung tanggal 15 September 1876 lan wiwit lumaku; karya iki dianggep wujud kapisan kodifikasi kukum Islam.", "159b40e5"]},
"OLAYLAR_EK7:1873-04-01:0":{"b": ["'Vatan yahut Silistre' dipentasaké, Namık Kemal dibuwang", "3861284c"], "d": ["Nalika sandiwara Namık Kemal sing téma tresna tanah wutah getih dipentasaké ing Téater Gedikpaşa, para pamirsa mbyak metu menyang dalan karo bengok 'Urip tanah air, urip Kemal'. Miturut artikel TDV 'Nâmık Kemal', pamaréntah sing wedi karo demonstrasi iki nutup koran İbret lan tanggal 6 April 1873 mbuwang Namık Kemal menyang Siprus (Famagusta) tanpa diadili.", "b713ac86"]},
"OLAYLAR_EK7:1876-06-04:0":{"b": ["Abdülaziz séda kanthi kahanan nyalawadi", "85816692"], "d": ["Abdülaziz, sing sawisé dilèngsèraké dipindhah miturut panjaluké dhéwé menyang Kraton Feriye (1 Juni 1876), tanggal 4 Juni ditemokaké ing kamaré kanthi urat tanganing pergelangan kapotong. Dhéwan dhokter sangalas wong, kalebu dhokter kedutaan, nyusun lapuran sing tembungé ora cetha; tanggal 6 Juni sédané diumumaké ing koran minangka bunuh diri. Nanging panalitèn sing dibukak Abdülhamid II duwé kesimpulan yèn sédané dudu bunuh diri nanging paténi, lan para terdakwa diadili ing 1881 ing Pengadilan Yıldız; prakara iki isih diperdebataké ing panulisan sajarah nganti saiki.", "a7b39d5c"]},
"OLAYLAR_EK7:1877-02-05:0":{"b": ["Dicopoté Midhat Pasya saka wazir agung lan pambuwangané", "b5247b06"], "d": ["Wazir Agung Midhat Pasya, arsitèk Kanun-i Esasi, nem minggu sawisé diumumaké, dicopot Abdülhamid II lan sajroné sewengi dibuwang menyang manca nagara. Miturut artikel Midhat Pasha ing Ensiklopedi Islam TDV, pencopotan iku digandhèngaké karo ora senengé sultan marang pasal-pasal ing undhang-undhang dhasar sing matesi wewenangé dhéwé. Pasya iku dhisik lunga menyang Napoli, banjur menyang pirang-pirang kutha ing Éropah.", "88f7d5e3"]},
"OLAYLAR_EK7:1902-01-15:0":{"b": ["Abdulaziz bin Saud ngrebut manèh Riyadh saka Rasyidiyah", "75eb8830"], "d": ["Abdulaziz, nom-noman saka wangsa Saud sing sepuluh taun sadurungé ngungsi menyang Kuwait, nyerbu Riyadh karo pasukan cilik lan ngrebut kutha kanthi matèni wakil gubernur Al Rasyid (Syammar). Miturut artikel Riyadh ing Ensiklopedi Islam TDV, saya ringkihé Rasyidiyah lan ora bisané ngirim bantuan menyang kutha nggampangaké kasilé serbuan iki; kedadéan iki dianggep wektu adegé Nagara Saudi Kapindho, sing sajroné telung puluh taun sabanjuré bakal dadi wiji Arab Saudi jaman saiki.", "7e0bf55b"]},
"OLAYLAR_EK7:1909-04-24:0":{"b": ["Mlebuné Wadyabala Tumindak menyang Istanbul", "41c8304c"], "d": ["Wadyabala Tumindak, sing budhal saka Salonika lan umumé isiné pasukan setya marang Panitya Persatuan lan Kemajuan, mlebu Istanbul kanggo numpes pambrontakan 31 Maret. Miturut artikel Hareket Ordusu ing Ensiklopedi Islam TDV, komandhané dicekel Mahmud Şevket Pasya, lan kepala stafé yaiku Kaptèn Mustafa Kemal. Sawisé bentrokan sedhéla, katentreman kutha dipulihaké.", "e47ad17d"]},
"OLAYLAR_EK7:1920-04-11:0":{"b": ["Dibubaraké Majelis Perwakilan Utsmaniyah pungkasan", "2b709269"], "d": ["Sawisé Istanbul resmi didhudhuki pasukan Sekutu lan akèh anggota dhéwan dicekel, Meclis-i Mebusan ora bisa nyambut gawé manèh lan resmi dibubaraké kanthi irada Mehmed VI. Miturut artikel Meclis-i Mebusan ing Ensiklopedi Islam TDV, pambubaran iki nglambangaké pungkasané kanyatan tradhisi parlemèn konstitusional Utsmaniyah. Ditutupé iki nguwataké kabutuhan ngumpulaké majelis nasional anyar ing Ankara.", "4caabf36"]},
"OLAYLAR_EK7:1920-04-23:0":{"b": ["Dibukaké Majelis Agung Nasional Turki", "6eab539d"], "d": ["Sawisé Meclis-i Mebusan ing Istanbul dibubaraké, para wakil rakyat nglumpuk ing Ankara lan mbukak Majelis Agung Nasional Turki, lan Mustafa Kemal Pasya dipilih dadi ketua majelis. Miturut artikel Majelis Agung Nasional Turki ing Ensiklopedi Islam TDV, majelis iku nduwé sipat luar biasa, nglumpukaké wewenang legislatif lan eksekutif ing awaké dhéwé. Pambukakan iki dadi titik owah-owahan nalika pusat pulitik lan kelembagaan perjuangan nasional pindhah menyang Ankara. Kanthi kedadéan iki 124 panggonan (tlatah Turki sing ora didhudhuki), kalebu Konya, Sivas, Kayseri, Eskişehir, Erzurum, Trebizond, Samsun, Diyarbakır, Van, Malatya, Denizli lan Isparta, mlebu pamaréntahan Majelis Agung Nasional Turki.", "47a80fa7"]},
"OLAYLAR_EK8:1460-01-01:0":{"b": ["Penaklukan bèntèng Izvornik (Zvornik)", "657c465a"], "d": ["Bèntèng Izvornik ing pinggir Kali Drina ditaklukaké Utsmaniyah ing 1460. Miturut Ensiklopedi Islam TDV, amarga panggonané trep saka sisih administrasi lan militèr, dhisik didadèkaké pusat kaza, ing 1480 didadèkaké pusat sanjak sing jenengé padha, lan ing 1491 dikuwataké nganggo tembok watu, lan kanthi enem mesjid, wolung tekke lan padusané dadi pusat administrasi lan dagang sing wigati.", "160e9a01"]},
"OLAYLAR_EK8:1468-01-01:0":{"b": ["Sédané Qasim Khan, jumenengé Daniyar Khan (Kekhanan Qasim)", "522fd0fd"], "d": ["Kanthi sédané pangadeg kekhanan, Qasim Khan, ing 873/1468, putrané, Daniyar, nggantèni; Daniyar mréntah nganti 1486.", "6217828f"]},
"OLAYLAR_EK8:1509-02-03:0":{"b": ["Perang Segara Diu — kaunggulan Portugis ing Samudra Hindia", "1778d347"], "d": ["Armada Malik Ayaz sing didhukung Mamluk, sing mréntah tlatah iku atas jeneng Kasultanan Gujarat, kalah abot ing lepas Diu ngadhepi armada gubernur jenderal Portugis Francisco de Almeida, sing nyoba ngedegaké pangkalan pasokan ing pesisir iku. Kekalahan iki mènèhi Portugis kaunggulan segara sing tetep ing Samudra Hindia lan matahaké kakuwatan segara Mamluk-Gujarat; iki dianggep wiwitan ora imbangé kakuwatan sing dadi latar mburi perjuangan Segara Abang-Samudra Hindia sing dijupuk alih Utsmaniyah sawisé 1517 (pertahanan Jeddah, pangepungan Diu 1538).", "88e4e561"]},
"OLAYLAR_EK8:1526-01-01:0":{"b": ["Pambrontakan Kalender Syah", "f60f6ca4"], "d": ["Amarga kangèlan keuangan ing Anatolia, ora seneng marang pranatan administrasi anyar lan pangaribawa propaganda Safawiyah, suku-suku Turkmen gedhé kaya Çiçekli, Akça Koyunlu, Masadlı lan Bozoklu bebarengan karo golongan sing kari saka pambrontakan Baba Zünnûn sadurungé nglumpuk ing sakiwa-tengené Kalender Syah lan tekan kakuwatan udakara telung puluh èwu wong. Para pambrontak dhisik ngalahaké Beylerbey Rum; nalika Wazir Agung Makbul İbrâhim Pasya nglumpukaké prajurit lan njanjèkaké hak-haké, dhukungan marang Kalender lumèr lan pambrontakan ditumpes ing sakiwa-tengené Elbistan; Kalender Syah lan Veli Dündar dipatèni ing Juni 1527.", "a12c9471"]},
"OLAYLAR_EK8:1554-08-22:0":{"b": ["Penaklukan Shahrizor — direbuté Bèntèng Zalm", "4320d9b8"], "d": ["Nalika ekspedisi Nakhchivan Sultan Sulaiman Sang Pembuat Undhang-undhang, Beylerbey Bagdad Osman Pasya diutus ngrebut tlatah Shahrizor; sawisé sédané, Baltacı Mehmed Pasya, sing dadi beylerbey Bagdad, ngepung Zalm, bèntèng pusat tlatah iku, lan ngrebuté tanggal 22 Agustus 1554 (23 Ramadan 961). Kanthi mangkono cekungan Shahrizor ing lèrèng kulon Zagros mlebu pamaréntahan Utsmaniyah lan sesambungan antarané Bagdad lan Kurdistan diamanaké; tlatah iku dhisik didadèkaké sanjak lan diwènèhaké marang Murad Bey. Ing 1563 Beylerbey Muzaffer Pasya mbangun Bèntèng Gülanber minangka pusat provinsi anyar; bèntèng iku bakal dibongkar ing 1623 kanthi dhawuh Syah Abbas lan dibangun manèh ing 1638 ing jaman Hüsrev Pasya.", "068e1ae8"]},
"OLAYLAR_EK8:1573-01-01:0":{"b": ["Panguwasa Kekhanan Qasim mlebu Kristen lan dicopot saka kekhanan", "a1a8eeb9"], "d": ["Panguwasa sing mimpin kekhanan njupuk jeneng 'Semen (Simeon)' lan dadi Kristen; wong Rusia, kanthi nimbang reaksi kawula Muslim, nyopot dhèwèké saka kekhanan. Ora suwé sawisé, wong iki diumumaké déning Ivan Sing Nggegirisi dadi panguwasa nominal ing Moskwa kanthi gelar 'pangéran agung tsar lan Rusia' (1575) — pepethukan paling nyolok antarané Kekhanan Qasim lan tahta Moskwa.", "123a7380"]},
"OLAYLAR_EK8:1577-01-01:0":{"b": ["Sanjak Fezzan digabungaké karo Tripoli — Murzuk lan simpang kafilah Sahara", "2e6554a4"], "d": ["Amarga tekanan beylerbeylik Tripoli, Fezzan, simpang kafilah ing Sahara, nampa dadi bawahan Utsmaniyah kanthi Murzuk minangka pusat. Miturut artikel Fezzan ing Ensiklopedi Islam TDV, wangsa Awlad Muhammad sing mréntah tlatah iku dibébasaké ing urusan njero kanthi syarat mbayar pajeg kanthi ajeg; Fezzan diatur minangka sanjak sing kaiket marang provinsi Tripoli sing direbut ing 1551. Kanthi mangkono dagang budhak, emas lan unta ing dalan Tripoli-Murzuk-Bornu mlebu kontrol Utsmaniyah. Pamaréntahan ora langsung iki ing 1711 bakal pindhah menyang Karamanli, lan ing 1842 menyang organisasi kaza langsung.", "dff1c8b1"]},
"OLAYLAR_EK8:1586-01-01:0":{"b": ["Nakhchivan lan Ordubad mlebu pamaréntahan Utsmaniyah", "24d939b3"], "d": ["Sawisé Erivan direbut lan didadèkaké pusat beylerbeylik ing 1583, pasukan sing mudhun mangidul-wétan sadawané lembah Aras ndadèkaké Nakhchivan lan Ordubad kaiket marang pamaréntahan Utsmaniyah; kutha loro iku dadi sanjak ing provinsi Erivan sing anyar diadegaké. Miturut artikel Nakhchivan ing Ensiklopedi Islam TDV, pamaréntahan Utsmaniyah sing tetep kanggo sepisanan diadegaké ing kutha iku nalika perang iki — ing ekspedisi Nakhchivan 1553 kutha iku direbut nanging mung dijarah banjur ditinggal. Kanthi mangkono dalan wadyabala antarané Erivan lan Tabriz kabukak, lan ing September taun sing padha Tabriz bisa dilebu. Syah Abbas bakal ngrebut manèh Nakhchivan ing 1603.", "270c0faa"]},
"OLAYLAR_EK8:1603-03-01:0":{"b": ["Pambrontakan Deli Hasan Pasya lan diadhemaké liwat beylerbeylik Bosnia", "144f3f2d"], "d": ["Sawisé sédané pimpinan Jelali Karayazıcı Abdülhalim ing 1602, seduluré, Deli Hasan, sing njupuk alih pimpinan gerakan, njupuk kauntungan saka bébasé obah sing diwènèhaké perang Austria sing isih lumaku marang golongan Jelali, nyerbu Kütahya lan mlaku nglawan Afyonkarahisar. Ing mangsa nalika nagara bebarengan ngadhepi front Austria lan Iran, prakara iki dirampungaké 'kanthi alus': Deli Hasan diwènèhi pangkat pasya lan beylerbeylik Bosnia, lan gerakan pambrontakan resmi dipungkasi ing 1603.", "22ea1f34"]},
"OLAYLAR_EK8:1609-01-01:0":{"b": ["Pasukan Rusia ngrebut kutha Qasim, Uraz Muhammad Khan", "b3f0bd34"], "d": ["Minangka gambaran Jaman Kekisruhan (Smuta) ing Rusia, pasukan Rusia ngepung lan ngrebut kutha Qasim lan nyabet pedhang marang akèh-akèhé warga. Uraz Muhammad, sing mimpin kekhanan, dadi sasaran amarga ndhukung Dmitry Palsu Kapindho; taun sabanjuré (1610) dhèwèké dhéwé dipatèni liwat komplotan.", "3583477d"]},
"OLAYLAR_EK8:1637-06-18:0":{"b": ["Ilangé Bèntèng Azak menyang Kazak Don", "ba068b2f"], "d": ["Kazak Don ngrebut Bèntèng Azak, sing dikepung wiwit 21 April 1637, rong sasi sabanjuré; bèntèng sing dadi gapura lor-wétan Segara Ireng lan kunci dagang Don iku kanggo sepisanan ucul saka tangan Utsmaniyah. Miturut artikel Azak ing Ensiklopedi Islam TDV, wong Kazak ngrebut bèntèng ing 1637, ing 1641 tahan ngadhepi pangepungan gedhé telung sasi sing dipimpin Deli Hüseyin Pasya, lan lagi ing 1642, nalika Khan Krim Mehmed Giray teka, ngosongaké bèntèng. Nagara ing wektu iku sibuk karo front Bagdad; ora bisané njaga bèntèng iku limang taun dadi retak kapisan ing sipat Segara Ireng minangka 'tlaga Utsmaniyah'.", "da9b9fd8"]},
"OLAYLAR_EK8:1657-11-15:0":{"b": ["Direbuté manèh Lemnos lan Samothrace", "c445553b"], "d": ["Sawisé Tenedos dibébasaké tanggal 31 Agustus 1657, Köprülü Mehmed Pasya ngarahaké armada mangalor lan ngrebut manèh Lemnos lan Samothrace sing wis nembelas sasi dicekel Venesia. Miturut artikel Lemnos ing Ensiklopedi Islam TDV, pulo iku tiba ing tangan Venesia ing Juli 1656 lan direbut manèh ing November 1657. Kanthi mangkono blokade Venesia ing cangkem Selat Dardanella pecah babar pisan lan dalan gandum Istanbul diamanaké manèh; iki asil paling nyata ing taun kapisan wazir agung sing teka nganggo wewenang luar biasa.", "9a57630d"]},
"OLAYLAR_EK8:1688-09-11:0":{"b": ["Ilangé Knin menyang Venesia — bèntèng tapel wates Dalmatia sing umuré 166 taun tiba", "252406b7"], "d": ["Ing perang pirang-pirang front sing dibukak sawisé kekalahan Wina 1683, pasukan Venesia maju menyang pedalaman Dalmatia. Knin, sing dikepung jenderal Dalmatia Girolamo Cornaro, sawisé pangepungan rolas dina diserahaké déning Beylerbey Mehmed Pasya. Knin minangka bèntèng kunci garis tapel wates Dalmatia, sing ditaklukaké Gazi Hüsrev Bey ing 1522 lan 166 taun ana ing tangan Utsmaniyah; ilangé umumé mbukak tlatah iku marang Venesia.", "d4aa761c"]},
"OLAYLAR_EK8:1779-04-01:0":{"b": ["Direbuté manèh Basra saka pendhudhukan Iran", "5b10c5c1"], "d": ["Basra, sing ing 1776 direbut Sadiq Khan, sedulur Karim Khan Zand, dikosongaké nalika rebutan tahta diwiwiti ing Iran sawisé sédané Karim Khan tanggal 2 Maret 1779; Sadiq Khan bali menyang Iran kanthi pratelan arep dadi sultan. Kutha iku sauntara wektu ana ing tangan suku Muntafiq banjur mlebu manèh ing pamaréntahan Utsmaniyah. Mutesellim lawas Süleyman Agha, sing bali saka Syiraz, njaluk jabatan gubernur Basra lan, kanthi jeneng Büyük Süleyman Pasya, dadi gubernur Basra, Bagdad lan Shahrizor. Dagang Teluk bali ing kontrol Utsmaniyah; ing taun-taun pendhudhukan sapérangan dagang wis ngalih menyang Kuwait, lan wiwit 1778 pos ara-ara samun uga dikirim saka Kuwait.", "2f14ff54"]},
"OLAYLAR_EK8:1793-01-01:0":{"b": ["Sédané Timur Syah, jumenengé Zaman Syah (Nagara Durrani)", "c3effdb2"], "d": ["Kanthi sédané Timur Syah, sing luwih saka rong puluh taun nguwataké nagara saka njero, sedulur telu sing dadi gubernur Kandahar, Herat lan Kabul rebutan tahta; gubernur Kabul, Zaman Syah, sing nyekel ibu kutha, dadi syah tanggal 20 Mei 1793. Krisis waris iki dadi wiwitan nyata proses pecahé wangsa.", "4b3d7d19"]},
"OLAYLAR_EK8:1819-11-01:0":{"b": ["ʻAi Noa — pungkasané sistem kapu tradhisional ing Hawaii", "0b10e1d8"], "d": ["Nem sasi sawisé sédané Kamehameha I, raja anyar Liholiho, kanthi dhukungan ibuné, Kaʻahumanu, sengaja nerak larangan wong lanang lan wadon mangan bebarengan (ʻaikapu). Tumindak sing disebut 'ʻAi Noa' (mangan bébas) iki resmi mungkasi sistem agama-kukum kapu tradhisional; candhi-candhi lawas (heiau) ing pulo-pulo iku ora suwé dirubuhaké. Iki retak agama-pulitik paling gedhé sadurungé tekané misionaris Kulon (1820).", "7f6d4463"]},
"OLAYLAR_EK8:1830-02-03:0":{"b": ["Protokol London — diakoni kamardikan Yunani", "4c7b4b72"], "d": ["Protokol sing ditapaktangani Inggris, Prancis lan Rusia ing London, ngluwihi otonomi sing dirancang Prajanjian Edirne, ngakoni Yunani minangka nagara MARDIKA. Katemtuan: semenanjung Morea, Attika lan Euboea bebarengan karo kapuloan Cyclades ditinggalaké marang nagara anyar; wates digambar ing garis Arta-Volos; diputusaké ganti rugi dibayar marang Nagara Utsmaniyah; wujud pamaréntahan nagara ditemtokaké minangka 'monarki mardika'. Iki nagara mardika KAPISAN sing pisah saka kakaisaran lan ngedegaké conto kukum kanggo kamardikan-kamardikan Balkan sabanjuré. Pulo-pulo Cyclades (Naxos, Tinos, Santorini, Paros, Milos, Syros, Mykonos lan liya-liyané) mlebu Yunani sing kamardikané diakoni liwat Protokol London.", "920bfab9"]},
"OLAYLAR_EK8:1835-01-01:0":{"b": ["Abdullah bin Rasyid ngrebut kaamiran Ha'il — adegé wangsa Syammar (Rasyidiyah)", "fb513b8a"], "d": ["Nalika pasukan Mehmed Ali Pasya ngrebut Diriyah ing 1818, tlatah Jabal Syammar metu saka kakuwasan Saudi lan kaamiran tetep ana ing tangané kulawarga Ibn Ali. Abdullah bin Rasyid, sing ndhukung diadegaké manèh kakuwasan Utsmaniyah, bebarengan karo seduluré, Ubaid, menang ing perjuangan nglawan kulawarga Ibn Ali ing 1835, ngrebut kaamiran Ha'il lan ngedegaké kakuwasan wangsa Rasyidiyah.", "631e33a9"]},
"OLAYLAR_EK8:1840-10-08:0":{"b": ["Undhang-undhang dhasar tinulis kapisan Hawaii diumumaké", "401a8a1d"], "d": ["Undhang-undhang dhasar tinulis jangkep kapisan karajan diumumaké; dokumèn sing matesi wewenang raja lan ngedegaké dhéwan perwakilan iki ngowahi Hawaii dadi monarki konstitusional.", "a32cdab2"]},
"OLAYLAR_EK8:1887-07-06:0":{"b": ["Undhang-undhang Dhasar Bayonet — wewenang Raja Kalākaua dikethoki", "4953363b"], "d": ["Golongan milisi bersenjata ngancam Raja Kalākaua lan meksa dhèwèké napaktangani undhang-undhang dhasar anyar sing ngethoki banget wewenang karajan; dokumèn iku dikenal minangka 'Undhang-undhang Dhasar Bayonet' (Bayonet Constitution) lan kanyatané nyemplungaké tahta ing kontrol golongan elit pendatang kulit putih.", "cc95eabb"]},
"OLAYLAR_EK8:1893-02-18:0":{"b": ["Sédané George Tupou I, jumenengé George Tupou II (Tonga)", "b56e2b32"], "d": ["Kanthi sédané raja pangadeg George Tupou I, canggahé, George Tupou II, munggah tahta; upacara jumenengan nganggo makutha dianakaké ing Nukuʻalofa tanggal 17 Maret 1893.", "01fe9fa1"]},
"OLAYLAR_EK8:1893-09-19:0":{"b": ["Selandia Anyar dadi nagara kapisan sing mréntah dhéwé sing mènèhi hak pilih marang wong wadon", "0d277cde"], "d": ["Kanthi Undhang-undhang Pemilihan anyar sing ditapaktangani Gubernur Lord Glasgow, Selandia Anyar dadi nagara kapisan ing donya sing mréntah dhéwé sing mènèhi wong wadon hak pilih ing pemilihan parlemèn.", "ba9b7f63"]},
"OLAYLAR_EK8:1894-07-04:0":{"b": ["Républik Hawaii diumumaké", "4346bd5d"], "d": ["Para komplotan sing nggulingaké Ratu Liliuokalani ing 1893 ngowahi pamaréntah sauntara dadi républik resmi; Sanford Dole diumumaké dadi présidhèn. Rezim antara iki lumaku nganti Amérika Sarékat nyaplok ing 1898.", "d1a76858"]},
"OLAYLAR_EK8:1901-06-11:0":{"b": ["Wates Selandia Anyar diambakaké nyakup Kapuloan Cook lan Niue", "d0370a33"], "d": ["Wates Selandia Anyar diambakaké supaya nyakup Kapuloan Cook (Rarotonga, Aitutaki lan pulo-pulo kidul, sarta Kapuloan Cook lor) lan Niue; pulo-pulo iku dadi wilayah sing kaiket marang Selandia Anyar.", "464148bd"]},
"OLAYLAR_EK8:1918-04-05:0":{"b": ["Sédané George Tupou II, jumenengé Sālote Tupou III (Tonga)", "a3084f3b"], "d": ["George Tupou II séda amarga tuberkulosis; putri umur 18 taun, Sālote, diumumaké dadi ratu ing dina sabanjuré, lan upacara jumenengan dianakaké tanggal 11 Oktober 1918.", "a63672b5"]},
"OLAYLAR_EK8:1920-08-10:0":{"b": ["Prajanjian Sèvres — naskah pambagèn kakaisaran", "64980d7b"], "d": ["Naskah sing ditapaktangani pamaréntah Utsmaniyah karo nagara-nagara Sekutu lan kanyatané mbubaraké kakaisaran. Katemtuan: Trakia Wétan lan tlatah Izmir kanggo Yunani; ing Anatolia Wétan dirancang Armenia mardika lan Kurdistan otonom; Suriah ditinggalaké marang Prancis, Irak lan Palestina marang Inggris minangka mandat; selat-selat dipasrahaké marang komisi internasional; wadyabala dikurangi dadi 50.700 wong, kapitulasi bali, keuangan dipasrahaké ing kontrol Sekutu. Majelis Agung Nasional ing Ankara ORA TAU NGAKONI prajanjian iku lan ngumumaké sing tapak tangan minangka pangkhianat tanah wutah getih; naskah iku ora lumaku, lan gantiné ing 1923 teka Lausanne. Iki sebabé ora ana tandhingané ing peta — Sèvres miturut kukum ora tau ditindakaké.", "c9b2648b"]},
"OLAYLAR_EK8:1920-09-02:0":{"b": ["Wadyabala Abang mlebu kutha Bukhara — amir pungkasan Alim Khan disingkiraké saka tahta", "f8f5bfcf"], "d": ["Wadyabala Abang mlebu kutha Bukhara tanggal 2 September 1920 lan amir Manghit pungkasan, Alim Khan, disingkiraké saka tahta. Amir mundur menyang sisih wétan nagara, ing Dushanbe, lan suwéné setengah taun saka kono mimpin perjuangan nglawan Soviet; Wadyabala Abang ngrebut Dushanbe tanggal 21 Fèbruari 1921, lan amir nyabrang luwih mangétan lan saka kono menyang Afghanistan. Kekhanan iku resmi dibubaraké tanggal 6 Oktober 1920 (deleng Républik Rakyat Soviet Bukhara).", "19580033"]},
"OLAYLAR_EK8:1920-10-08:0":{"b": ["Républik Rakyat Soviet Bukhara diumumaké", "ef579627"], "d": ["Sawisé Wadyabala Abang tanggal 28-31 Agustus 1920 nggulingaké Kaamiran Bukhara lan meksa Amir Alim Khan mlayu menyang Bukhara Wétan, Républik Rakyat Soviet Bukhara diumumaké dipimpin Faizullah Khojaev.", "690bfb2f"]},
"OLAYLAR_EK8:1921-08-14:0":{"b": ["Républik Rakyat Tannu-Tuva ngumumaké kamardikan", "8710ea3d"], "d": ["Kamardikan diumumaké ing sangisoré pimpinan Partai Revolusioner Rakyat Tuva; pasal kapisan undhang-undhang dhasar kapisan nyebut yèn nagara tumindak 'ing sesambungan internasional ing sangisoré pangayoman Rusia Soviet'. Kanthi kedadéan iki Kyzyl (Belotsarsk, Tannu-Tuva) pindhah menyang Républik Rakyat Tannu-Tuva.", "dc0ac64a"]},
"OLAYLAR_EK8:1921-09-01:0":{"b": ["Undhang-undhang dhasar anyar Républik Rakyat Soviet Bukhara disahaké", "fb17bf39"], "d": ["Béda karo undhang-undhang dhasar Rusia 1918, disahaké undhang-undhang dhasar anyar sing ngidini kepemilikan pribadi tanah lan produksi, lan mènèhi hak pilih uga marang sing dudu proletar (kejaba sanak amir sing digulingaké lan tuwan tanah gedhé).", "91bf1a32"]},
"OLAYLAR_EK8:1921-09-05:0":{"b": ["Owah dadi Républik Sosialis Soviet Khwarazm", "14a1d26f"], "d": ["Nagara iku ngganti jeneng lan statusé dadi Républik Sosialis Soviet Khwarazm; susunan administrasi lan kukum diatur manèh miturut sistem Soviet.", "e3e9b939"]},
"OLAYLAR_EK8:1922-03-03:0":{"b": ["Pamaréntah Tannu Tuva kanyatané wiwit njabat", "22ea1516"], "d": ["Pamaréntah sing dibentuk sawisé rapat partai kapisan ing Fèbruari 1922 kanyatané wiwit njabat.", "3b3c6c39"]},
"OLAYLAR_EK8:1923-10-12:0":{"b": ["Khural Agung kapisan Tannu Tuva nglumpuk", "80fe15f2"], "d": ["Khural Agung (Majelis Rakyat) kapisan nagara iku nglumpuk; iki rapat perwakilan gedhé kapisan ing proses nagara dadi lembaga sing mapan.", "e8cf06ac"]},
"OLAYLAR_EK8:1924-01-01:0":{"b": ["Pungkasané RSS Khwarazm lan Républik Rakyat Soviet Bukhara amarga pambagèn wates nasional — adegé RSS Uzbekistan lan Turkmenistan", "e8c8ab4f"], "d": ["Kanthi keputusan Soviet 'pambagèn wates nasional' (natsionalno-territorialnoe razmezhevanie), Républik Sosialis Soviet Khwarazm lan Républik Rakyat Soviet Bukhara dibubaraké; wilayahé dibagi antarané Républik Sosialis Soviet Uzbekistan lan Turkmenistan sing anyar diadegaké (sisih wétan Khiva menyang Uzbekistan, sisih kulon menyang Turkmenistan). Artikel TDV `harizm`: 'Ing 1924 pérangan wétan Kekhanan Khiva diwènèhaké marang Républik Sosialis Soviet Uzbekistan, déné sisih kulon marang Républik Sosialis Soviet Turkmenistan.' — mung nyebut taun.", "58053c38"]},
"OLAYLAR_EK9:1427-01-01:0":{"b": ["Alanya didol marang Sultan Mamluk Barsbay", "c8bd35f2"], "d": ["Alanya, sing ing 1293 direbut Karamanoğlu Mecdüddin Mahmud Bey, wis dadi kadipaten kapisah sing dipréntah sawijining cabang wong Karaman; Ibnu Battutah nyathet ing 1333 yèn pamaréntahan ana ing tangané Karamanoğlu Yusuf Bey. Ing 1427 Karaman bin Savcı Bey ngedol kutha iku marang Sultan Mamluk Barsbay kanthi rega limang èwu dhuwit emas, lan Alanya mlebu pamaréntahan Mamluk. Plabuhan kunci Segara Tengah iki kanthi mangkono dadi alangan sing dicekel Mamluk ing dalan Utsmaniyah sing mbukak mangidul; nalika Gedik Ahmed Pasya ngepung ing 1471, bey pungkasan, Kılıçarslan, masrahaké kutha.", "9be5efe7"]},
"OLAYLAR_EK9:1741-06-12:0":{"b": ["Tabarka direbut saka wong Genoa — pungkasané konsèsi karang Lomellini", "b1f33eb5"], "d": ["Sawisé prajanjian Charles V karo Bey Tunis ing 1544, kulawarga Lomellini saka Genoa manggon ing pulo Tabarka lan suwéné rong atus taun nyekel konsèsi karang; pulo iku tetep dadi pos dagang Kristen ing tengah Tunisia Utsmaniyah. Ali Pasya saka wangsa Husainiyah, nalika krungu upaya kulawarga iku arep ngedol pulo, ngirim pasukan lan ngrebut pulo iku tanggal 12 Juni 1741; udakara sèwu limang atus wong Kristen dipindhah menyang Tunis. Wiwit tanggal iku Tabarka mlebu pamaréntahan ocak Tunis.", "93c8bd7b"]},
"OLAYLAR_EK9:1798-07-21:0":{"b": ["Perang Piramida lan direbuté Kairo déning Prancis", "3ddd6b96"], "d": ["Napoleon mlaku mangidul saka Iskandariyah sadawané Nil lan tanggal 21 Juli 1798 ing Imbaba, ing sabrangé Giza, ngadhepi pasukan jaranan Mamluk duwèké Murad Bey. Prajurit mlaku Prancis sing baris pesagi matahaké serangan jaranan; wadyabala Mamluk buyar lan Kairo nyerah tanpa perlawanan rong dina sabanjuré. Murad Bey mundur menyang Mesir Dhuwur, Ibrahim Bey menyang Suriah. Wong Prancis ngedegaké diwan ing Kairo lan nyoba nglakokaké pamaréntahan liwat ulama; rong pambrontakan gedhé Kairo pecah ing Oktober 1798 lan Maret 1800.", "ad9a3113"]},
"OLAYLAR_EK9:1799-03-18:0":{"b": ["Pangepungan Akko déning Napoleon — ekspedisi Suriah dimandhegaké", "d2a947ad"], "d": ["Napoleon, sing kepéngin mbuyaraké pasukan sing disiapaké Utsmaniyah kanggo ngrebut manèh Mesir, mlaku menyang Suriah ing wiwitan 1799; dhèwèké ngrebut El Arish tanggal 18 Fèbruari lan Jaffa ing Maret, banjur ngepung Akko tanggal 18 Maret 1799. Pertahanan Cezzar Ahmed Pasya lan dhukungan saka segara laksamana Inggris Sidney Smith matahaké pangepungan sajroné rong sasi; amarga mriem pangepungan dicekel ing segara, tembok ora bisa dilangkahi. Napoleon mundur ing Mei, lan kekalahan iki dadi titik paling adoh pendhudhukan Prancis.", "288b9bd9"]},
"OLAYLAR_EK9:1832-11-22:0":{"b": ["Adegé nagara Emir Abdul Qadir — perlawanan ing Aljazair kulon dipusataké", "9e482383"], "d": ["Perlawanan sing buyar sawisé tibané Aljir nglumpuk ing sakiwa-tengené Abdul Qadir enom, putrané syekh Qadiriyah Muhyiddin; tanggal 22 November 1832, cedhak Mascara, para pimpinan suku baiat marang dhèwèké kanthi gelar 'amirul mukminin'. Susunan sing diadegaké dudu aliansi suku nanging nagara teratur: nduwé pabrik dhuwit, pabrik obat mimis, tatanan pajeg lan ibu kutha ing Tagdempt. Prancis resmi ngakoni kakuwasané liwat Prajanjian Tafna 1837. Abdul Qadir ora ngungsi marang Utsmaniyah nanging marang kasuzeranan sultan Maroko Abdurrahman; tegesé tanah iki wiwit 1832 dudu bawahan Utsmaniyah. Dhèwèké nyerah tanggal 23 Desember 1847, lan ing taun sing padha Nagara Utsmaniyah ngumumaké yèn hak-haké marang Aljazair wis rampung.", "ee2bb181"]},
"OLAYLAR_EK9:1837-10-13:0":{"b": ["Tibané Constantine — pungkasané beylik Aljazair wétan", "159fed36"], "d": ["Sawisé tibané Aljir ing 1830, beylerbeylik wétan ora buyar: bey pungkasan, Ahmed, nerusaké pamaréntahané dhéwé ing Constantine lan ngumumaké yèn dhèwèké tumindak atas jeneng Utsmaniyah. Ekspedisi kapisan Prancis ing 1836 rampung kanthi ambyar; ekspedisi kapindho ngepung kutha tanggal 6 Oktober 1837, komandhan Damrémont tiwas kena tembakan mriem tanggal 12 Oktober, lan tanggal 13 Oktober tembok dilangkahi lan kutha direbut dalan mbaka dalan. Ahmed Bey mundur menyang pagunungan lan lagi nyerah ing 1848. Tanggal iki dadi pungkasan nyata pamaréntahan Utsmaniyah-Turki sing umuré telung atus taun ing Aljazair wétan.", "41606785"]},
"OLAYLAR_EK9:1840-01-01:0":{"b": ["Penaklukan tlatah Taka lan adegé Kassala", "cc3e0631"], "d": ["Panguwasa Sudan, Ahmed Pasya Abu Widan, ing 1840 nggawa tlatah Taka antarané Kali Atbara lan Kali Gash menyang pamaréntahan Mesir lan ngedegaké kutha Kassala minangka markas militèr. Kutha iku dadi pusat mudiriyah sing ngontrol dalan kafilah antarané Sennar lan Suakin sarta sabuk wates Habsyi.", "b7898c36"]},
"OLAYLAR_EK9:1841-01-01:0":{"b": ["Pendhudhukan Muaskar (Mascara) déning Prancis — ilangé ibu kutha Abdul Qadir", "bd363c05"], "d": ["Nalika Bugeaud dadi gubernur ing 1841, strategi Prancis owah: ora manèh cekelan ing pesisir, nanging ndhudhuki kutha-kutha pedalaman siji mbaka siji. Barisan obah sing budhal saka Oran, Mostaganem lan Médéa ngrebut pusat-pusat nagara teratur duwèké Abdul Qadir; Mascara, ibu kutha sejati sing nduwé pabrik dhuwit, pabrik obat mimis lan lumbung gandum, sing paling wigati. Sawisé iku amir ora manèh ngedegaké pusat tetep, lan ngowahi wadyabalané dadi kémah ngumbara sing diarani 'smala'.", "b5e65ffc"]},
"OLAYLAR_EK9:1843-01-01:0":{"b": ["Pendhudhukan lembah Chelif lan Tenes — adegé Orléansville", "e1eeeb68"], "d": ["Supaya bisa nguber Abdul Qadir, ing April 1843 wong Prancis ngedegaké kutha anyar aran Orléansville ing tengah lembah Chelif; ing taun sing padha plabuhan pesisir Tenes uga didhudhuki. Kanthi mangkono koridor pedalaman antarané Aljir lan Oran mlebu kontrol Prancis lan perlawanan ing pagunungan Dahra kinupeng. Tanggal 16 Mei ing taun sing padha kémah ngumbara Abdul Qadir, 'smala', ditemokaké kanthi ora sengaja lan dibubaraké.", "67e95822"]},
"OLAYLAR_EK9:1843-06-12:0":{"b": ["Adegé kémah bèntèng Sidi Bel Abbès", "fb33ec29"], "d": ["Tanggal 12 Juni 1843 Bugeaud ndhawuhi Jenderal Bedeau ngedegaké kémah bèntèng kanthi kalèn lan tembok ing Sidi Bel Abbès; pambangunan diwiwiti tanggal 18 Juni lan ing November taun sing padha sawijining batalyon Legiun Manca manggon ing kono. Kémah iku dadi pangkalan tetep sing ngontrol ara-ara pedalaman antarané Oran lan Tlemcen.", "aab075d5"]},
"OLAYLAR_EK9:1844-01-01:0":{"b": ["Nedroma lan sabuk wates Maroko pindhah ing kontrol Prancis", "61d821f3"], "d": ["Sawisé Abdul Qadir mundur menyang Maroko ing 1843, Nedroma lan pesisir Traras ing lor-kulon Tlemcen mlebu kontrol Prancis. Perang Isly tanggal 14 Agustus 1844 ngalahaké babar pisan wadyabala Maroko, lan wates antarané nagara loro digambar liwat Konvènsi Lalla Maghnia tanggal 18 Maret 1845; Nedroma tetep ana ing sisih Aljazair garis iku.", "0456a776"]},
"OLAYLAR_EK9:1852-12-04:0":{"b": ["Tibané Laghouat — bukaké gapura Sahara", "b161b32c"], "d": ["Jenderal Pélissier kanthi pasukan nem èwu wong ngepung Laghouat tanggal 21 November 1852, lan tanggal 4 Desember kutha iku tiba amarga serangan getih. Laghouat minangka kutha oasis sing nguwasani dalan antarané Tell lan Sahara; tibané mbukak majuné Prancis menyang dalan-dalan kafilah ara-ara samun lan nyawisaké dalan supaya konfederasi Mzab sajroné setaun diwajibaké mbayar pajeg.", "049b3d0a"]},
"OLAYLAR_EK9:1872-01-01:0":{"b": ["Pancaploké tlatah Bogos (Keren) déning Mesir", "b2ab83ce"], "d": ["Werner Munzinger Pasya, gubernur provinsi 'Sudan Wétan lan Pesisir Segara Abang' sing diadegaké Khedive Ismail ing pesisir kulon Segara Abang, ing 1872 nggandhèngaké tlatah Bogos, sing dipanggoni wong Bilen, kanthi pusat Keren, menyang Mesir. Iki majuné Mesir sing paling suwé tahan menyang pinggir dhataran dhuwur Habsyi, lan miwiti padudon wates karo Abisinia sing lumaku rolas taun.", "e52afaf4"]},
"OLAYLAR_EK9:1874-11-02:0":{"b": ["Kasultanan Darfur dicaplok Mesir — Zubayr Pasya mlebu El Fasher", "f41268ed"], "d": ["Zubayr Rahma Pasya, sing saya kuwat amarga dagang gadhing lan budhak, tanggal 25 Oktober 1874 ing Manawashi mbuyaraké wadyabala Fur nganggo pasukan sing dipersenjatai bedhil Remington; Sultan Ibrahim tiwas ing perang iku. Zubayr mlebu El Fasher tanpa perang tanggal 2 November, lan pamaréntahan wangsa Keira sing lumaku wiwit 1603 kanyatané rampung. Darfur kanthi mangkono digabungaké karo provinsi Sudan duwèké Mesir wangsa Mehmed Ali; nanging perlawanan kulawarga Keira ing pagunungan lumaku nganti 1891.", "b9679678"]},
"OLAYLAR_EK9:1882-01-01:0":{"b": ["Pancaploké oasis Mzab (Ghardaia)", "9372959f"], "d": ["Kutha-kutha Ibadi ing Mzab wis sarujuk ing 1852 mbayar upeti marang Prancis nanging njaga pamaréntahan njeroné; telung puluh taun sabanjuré, ing 1882, tlatah iku langsung digabungaké karo wilayah Prancis lan Ghardaia diatur ing pamaréntahan militèr. Kanthi mangkono sabuk otonom pungkasan ing Sahara lor uga rampung miturut kukum.", "8ced1a9f"]},
"OLAYLAR_EK9:1882-07-11:0":{"b": ["Pengebomané Iskandariyah lan pendharatan Inggris", "18d57bf8"], "d": ["Nalika gerakan opsir sing dipimpin Urabi Pasya nguwasani khedive, Inggris melu campur kanthi dalih keamanan dalan Suez. Armada Laksamana Seymour ngebom baterei pesisir Iskandariyah tanggal 11-12 Juli 1882; sawisé kobongan lan jarahan ing kutha, pasukan Inggris ndharat tanggal 15 Juli. Nagara Utsmaniyah ora bisa nyegah operasi iki ing provinsi sing miturut kukum ana ing kadaulatané, lan uga ora mangsuli ajakan melu campur. Kanthi mangkono langkah kapisan pendhudhukan sing bakal lumaku telung puluh loro taun wis ditindakaké.", "d828a872"]},
"OLAYLAR_EK9:1882-09-13:0":{"b": ["Perang Tel el-Kebir — buyaré wadyabala Urabi", "8e38fecf"], "d": ["Wolseley ndharataké pasukané ing Ismailia liwat Terusan Suez, mlaku liwat ara-ara samun, lan nalika fajar tanggal 13 September 1882 nyerbu parit pertahanan Mesir ing Tel el-Kebir; perang rampung sajroné sajam. Urabi nyerah dina sabanjuré lan pasukan jaranan Inggris mlebu Kairo ing dina iku uga. Wiwit tanggal iki urusan keuangan, militèr lan manca Mesir kanyatané pindhah ing kontrol Inggris; déné kadaulatan Utsmaniyah miturut kukum lumaku nganti 1914.", "a399d51c"]},
"OLAYLAR_EK9:1883-06-08:0":{"b": ["Konvènsi La Marsa — rampungé protektorat Tunisia", "71338640"], "d": ["Prajanjian Bardo (Qasr al-Said) tanggal 12 Mei 1881 wis masrahaké urusan manca Tunisia marang Prancis nanging pamaréntahan njero ditinggal marang bey; rong taun sabanjuré, Konvènsi La Marsa sing ditapaktangani tanggal 8 Juni 1883 uga masrahaké réformasi keuangan lan administrasi ing kontrol Prancis lan ngrampungaké protektorat. Nagara Utsmaniyah terus ngaku nduwé kadaulatan marang Tunisia lan ora tau ngakoni pendhudhukan iku, nanging ora bisa njupuk langkah walesan sing nyata. Kanthi mangkono Tunisia, sing wiwit 1574 dadi ocak Utsmaniyah, resmi mlebu pangayoman Prancis.", "c04210c4"]},
"OLAYLAR_EK9:1883-11-05:0":{"b": ["Kekalahan Shaykan — disirnakaké wadyabala Hicks Pasya", "a0e08986"], "d": ["Hicks Pasya, opsir Inggris pensiunan sing mimpin pasukan Mesir udakara sepuluh èwu wong sing dikirim saka Kairo, nalika maju ing ara-ara samun Kordofan tanpa banyu lan tanpa pandhu, tanggal 5 November 1883 ing Shaykan kinupeng pasukan Mahdi lan wadyabalané meh disirnakaké kabèh. Kekalahan iki matahaké balung geger pamaréntahan Mesir ing Sudan: sajroné sesasi Darfur lan Bahr al-Ghazal nyerah, lan kabèh Kordofan pindhah menyang Mahdi. Dalan menyang tibané Khartoum diwiwiti saka kéné.", "c78a6d57"]},
"OLAYLAR_EK9:1883-12-23:0":{"b": ["Darfur pindhah menyang pasukan Mahdi — Slatin Pasya nyerah", "6d8992d4"], "d": ["Gubernur jenderal Darfur, Slatin Pasya, wiwit 1882 ngadhepi pambrontakan Mahdi suku Rizeigat; amarga mikir yèn kekalahan prajurité digandhèngaké karo agama Kristené, ing 1883 dhèwèké kanthi terbuka dadi Muslim lan njupuk jeneng Abdul Qadir. Sawisé wadyabala Hicks Pasya disirnakaké ing Kordofan ing November 1883, perlawanan ora ana tegesé manèh, lan dhèwèké nyerah marang Emir Madibbo tanggal 23 Desember 1883. Pos-pos Mesir cilik ing Darfur ora suwé nututi dalan sing padha; pamaréntahan Turki-Mesir sepuluh taun rampung. Kanthi kedadéan iki Jebel Marra (Darfur) pindhah menyang pamaréntahan nagara Mahdi.", "bd700253"]},
"OLAYLAR_EK9:1884-01-01:0":{"b": ["Zeila lan pesisir Somali pindhah menyang pamaréntahan Inggris", "1d649502"], "d": ["Nalika pambrontakan Mahdi ngambrukaké garnisun Mesir ing Sudan lan Segara Abang, Kairo kepeksa ngosongaké pos-pos adoh ing pesisir Habsyi. Pamaréntah Inggris ing Aden ndharataké pasukan ing Zeila lan Berbera ing 1884; taun sabanjuré prajanjian pangayoman ditapaktangani karo para pimpinan suku Somali lan Somaliland Inggris diadegaké. Zeila, sing wiwit 1559 kaiket marang provinsi Habeş, kanthi mangkono ucul.", "3c41ddf4"]},
"OLAYLAR_EK9:1884-01-15:0":{"b": ["Garnisun El Fasher nyerah marang pendhukung Mahdi", "68f0760d"], "d": ["Sanadyan Slatin wis nyerah tanggal 23 Desember 1883, garnisun Mesir ing bèntèng El Fasher isih nglawan. Garnisun sing kélangan sumur ing pangepungan pitung dina nyerah tanggal 15 Januari 1884; gaman diselehaké lan bèntèng pindhah menyang pendhukung Mahdi.", "18287ab0"]},
"OLAYLAR_EK9:1884-06-03:0":{"b": ["Prajanjian Hewett (Adwa) — Bogos ditinggalaké marang Abisinia", "0de1b701"], "d": ["Nalika pambrontakan Mahdi ngepung garnisun Mesir ing Sudan, Inggris, supaya olèh bantuan Abisinia, napaktangani prajanjian karo Yohannes IV ing Adwa tanggal 3 Juni 1884. Pasal kapindho prajanjian iku mbalèkaké Bogos marang Abisinia, lan minangka ijolé Abisinia mbukak dalan kanggo ngungsèkaké garnisun sing kinupeng liwat Massawa. Kanthi mangkono Keren metu saka rolas taun pamaréntahan Mesir; limang taun sabanjuré tlatah iku digabungaké karo Eritrea Italia.", "b7e73617"]},
"OLAYLAR_EK9:1896-09-23:0":{"b": ["Direbuté manèh Dongola — wiwitan ekspedisi sadawané Nil", "f63aa14f"], "d": ["Sawisé wong Italia kalah ing Adwa, Inggris ngirim wadyabala Mesir sing dipimpin Kitchener mlaku mangidul sadawané Nil. Nalika sepur maju ing ara-ara samun, prakara pasokan rampung, lan provinsi Dongola direbut manèh tanggal 23 September 1896. Pamaréntahan Mahdi sewelas taun rampung ing kéné; ekspedisi lumaku rong taun manèh nganti tekan Omdurman.", "ef465d34"]},
"OLAYLAR_EK9:1898-09-02:0":{"b": ["Perang Omdurman — ambruké nagara Mahdi", "28dff7b2"], "d": ["Wadyabala Inggris-Mesir Kitchener, sing dipersenjatai mriem lan bedhil mesin, tanggal 2 September 1898 ing ngarep Omdurman mbuyaraké pasukan Khalifah Abdullahi at-Ta'ayisyi sajroné sawetara jam. Dina sabanjuré Khartoum dilebu lan gendéra dikibaraké ing kraton panggonan Gordon dipatèni telulas taun sadurungé. Ibu kutha nagara Mahdi tiba; Khalifah dipatèni ing operasi panguberan ing pungkasan 1899. Kakuwasan nyata ganti tangan ing tanggal iki — 19 Januari 1899 iku prajanjian sing ngedegaké kerangka kukum pamaréntahan. Kanthi kekalahan nagara Mahdi iki, Darfur (El Fasher, Nyala, Geneina, Kutum lan liya-liyané) pindhah menyang Kasultanan Darfur sing diadegaké manèh déning Ali Dinar.", "ad27827a"]},
"OLAYLAR_EK9:1911-10-08:0":{"b": ["Pendharatan Italia ing Tobruk — pendhudhukan kapisan ing Tripoli", "44780018"], "d": ["Italia ngumumaké perang tanggal 29 September 1911, lan armadané tanggal 25-26 September ngeblokade pesisir. Operasi dharatan kapisan ditindakaké ing Tobruk tanggal 8 Oktober: garnisun Utsmaniyah sing cilik mundur menyang pedalaman lan plabuhan didhudhuki tanpa perang. Tobruk minangka plabuhan Utsmaniyah sing paling cedhak wates Mesir; tibané mbukak sayap wétan Cyrenaica lan nggampangaké pasukan Italia mlaku mangulon sadawané pesisir.", "fa489107"]},
"OLAYLAR_EK9:1911-10-09:0":{"b": ["Kutha Tripoli nyerah marang wong Italia", "785091ad"], "d": ["Tripoli nyerah tanggal 9 Oktober 1911 sawisé telung dina dibom. Pasukan Utsmaniyah ora mbélani kutha, nanging milih mundur menyang Aziziya lan Gharyan lan ngatur perlawanan ing pedalaman; perlawanan iki, sing diéloni Enver Bey lan Mustafa Kemal Bey, ngurung wong Italia ing sabuk pesisir nganti pungkasan perang. Tegesé, sanadyan kutha tiba, pedalaman vilayet tetep ana ing kontrol Utsmaniyah.", "7deeaf70"]},
"OLAYLAR_EK9:1911-10-16:0":{"b": ["Uculé Derna amarga pendharatan Italia", "f014c741"], "d": ["Sawisé Tobruk, gilirané Derna, plabuhan kapindho Cyrenaica; kutha iku didhudhuki tanggal 16 Oktober 1911. Dhataran dhuwur ing sakiwa-tengené Derna minangka tlatah panggonan tarékat Sanusiyah paling kuwat, lan para mujahid sing nglumpuk amarga ajakan jihad Syekh Ahmad Syarif ngepung wong Italia ing sakiwa-tengené plabuhan. Pendhudhukan mung winates ing kutha lan ora tau bisa sumebar menyang pedalaman.", "b6ada646"]},
"OLAYLAR_EK9:1911-10-21:0":{"b": ["Pendharatan Italia ing Benghazi — ilangé pusat sanjak Cyrenaica", "f9183c40"], "d": ["Pusat Cyrenaica, Benghazi, didhudhuki tanggal 21 Oktober 1911 liwat pendharatan kapapat lan paling wigati ing pesisir. Kanthi mangkono, telung minggu sawisé ngumumaké perang, Italia nyekel kabèh plabuhan gedhé vilayet Tripoli (Tripoli, Tobruk, Derna, Benghazi); nanging ora bisa mlebu pedalaman siji waé. Setaun perang sing isih kari kelebu ing gerak maju mlebu pedalaman saka papat panggonan pesisir iki sing ora ana asilé.", "6181e67f"]},
"OLAYLAR_EK9:1911-11-05:0":{"b": ["Dekrit pancaplokan sapihak Italia", "cfe3f9c2"], "d": ["Nalika perang isih lumaku, tanggal 5 November 1911 Italia ngetokaké dekrit lan ngumumaké yèn wis nyaplok Tripoli lan Cyrenaica. Nagara Utsmaniyah ora ngakoni iki lan perang lumaku setaun manèh; pancaplokan iku lagi sah miturut kukum liwat Prajanjian Ouchy tanggal 18 Oktober 1912. Mulané dekrit iku ora ngowahi werna Utsmaniyah ing peta — kepemilikan miturut kukum tetep ana ing Utsmaniyah nganti 1912, déné kontrol Italia dituduhaké minangka pendhudhukan kanthi arsir.", "23668758"]},
"OLAYLAR_EK:1300-01-01:0":{"b": ["Direbuté Köprühisar lan persiapan adegé Yenişehir", "39abff03"], "d": ["Kanthi ngrubuhaké bèntèng-bèntèng dalan liwat antarané Bursa lan Iznik, dipasang dhasar markas ngarep sing bakal ngepung kutha loro iku.", "72fa9808"]},
"OLAYLAR_EK:1301-01-01:0":{"b": ["Adegé Yenişehir", "d3275837"], "d": ["Pamukiman-garnisun Utsmaniyah kapisan sing tumata diadegaké kanggo mimpin pengepungan Bursa lan Iznik; Orhan Ghazi miyos ing kene.", "39c98a4b"]},
"OLAYLAR_EK:1302-08-01:0":{"b": ["Pengepungan kapisan Iznik lan penaklukan Marmaracık", "cdca2349"], "d": ["Iznik dikepung kanggo kaping pisan nanging ora bisa dirubuhaké (penaklukan pungkasan ing 1331); bèntèng Marmaracık sing cedhak direbut ing wektu iki.", "31c4c65f"]},
"OLAYLAR_EK:1305-06-01:0":{"b": ["Ekspedisi pasukan Katalan ing Anatolia", "4fd940d5"], "d": ["Kompi Katalan sing disewa Bizantium kanggo ngendheg majuné wong Turki oleh suksès sauntara nanging ora bisa langgeng; sawisé padha mundur, majuné kadipaten tapel wates saya cepet.", "89381e71"]},
"OLAYLAR_EK:1313-01-01:0":{"b": ["Köse Mihal mlebu Islam lan gabung karo Utsmaniyah", "ca0d86e1"], "d": ["Tekfur Harmankaya, Köse Mihal, mlebu Islam lan gabung karo Osman Ghazi bebarengan karo bèntèng lan wong-wongé; panjenengané dadi komandan Utsmaniyah kapisan sing asalé saka Bizantium.", "327b4cdc"]},
"OLAYLAR_EK:1320-01-01:0":{"b": ["Orhan Bey njupuk pamaréntahan sacara nyata", "6dadbefc"], "d": ["Amarga Osman Ghazi wis sepuh lan lara, pimpinan lan pangelolaan pengepungan Bursa lan ekspedisi sacara nyata pindhah menyang putrané, Orhan Bey (munggah tahtané sacara resmi ing taun 1326).", "280c6e0d"]},
"OLAYLAR_EK:1321-04-01:0":{"b": ["Direbuté Mudanya", "0a623368"], "d": ["Kanthi direbuté Mudanya, plabuhan Bursa, sesambungan kutha karo segara dipedhot; pengepungan Bursa mlebu tahap nyekik.", "c13020d5"]},
"OLAYLAR_EK:1324-01-01:0":{"b": ["Akyazı lan Pulo İmralı pindhah menyang tangané Utsmaniyah (tanggal ora ana ing sumber)", "380c60ce"], "d": ["Akyazı dadi sasaran serangan Utsmaniyah ing jaman Osman Bey (ing taun-taun sawisé ekspedisi 1305); taun direbuté sing mesthi ora dimangertèni. Ora ana sumber siji waé sing nyebut kapan Pulo İmralı direbut. Tapel wates taun 1324 ing peta mung pangisi sauntara.", "69782c1e"]},
"OLAYLAR_EK:1326-01-01:0":{"b": ["Akça Koca nguwasani Kandıra lan sakiwa-tengené", "341bb97e"], "d": ["Akça Koca, salah siji panguwasa tapel watesé Orhan Ghazi, nalika nyerang tlatah Izmit saka markasé ing kulon Tlaga Sapanca, udakara taun 1326 ngrebut Kandıra lan sakiwa-tengené. Izmit isih ana ing tangané Bizantium; kutha iku lagi bakal tiba ing taun 1337.", "ed042ad1"]},
"OLAYLAR_EK:1326-01-01:1":{"b": ["Gabungé Yalova lan Karamürsel", "133cb07a"], "d": ["Taun iki Yalova lan sakiwa-tengené ing pesisir kidul Teluk Izmit tiba ing tangané wong Turki; jalur pesisir diparingaké déning Orhan Bey minangka timar marang Karamürsel Gazi.", "592a86bc"]},
"OLAYLAR_EK:1328-01-01:0":{"b": ["Akça Koca ngrebut Aydos lan bètèng Samandıra", "ce4daa8a"], "d": ["Sawisé Kandıra direbut, Akça Koca, bebarengan karo Konuralp lan Gazi Abdurrahman, ngrebut bèntèng Aydos cedhak Kartal, banjur bèntèng Samandıra ing sisih loré; tlatah Samandıra diparingaké marang panjenengané minangka duwèké. Akça Koca séda cedhak Kandıra ing taun 1328; panguwasa tapel wates tlatah iku diparingaké marang Pangeran Murad.", "f2ef1bde"]},
"OLAYLAR_EK:1330-01-01:0":{"b": ["Persekutuan Utsmaniyah-Aydın-Saruhan", "9df6bb74"], "d": ["Telung kadipaten tumindak bebarengan nglawan Bizantium; armadané Umur Bey saka Aydın, kanthi serangané marang pesisir Trakia, ngentèkaké tenaga Bizantium ing front kapindho.", "32ca49ea"]},
"OLAYLAR_EK:1334-01-01:0":{"b": ["Penaklukan Gemlik (Kios)", "66fc4bcd"], "d": ["Kutha pesisir Gemlik (Kios) ing Teluk Gemlik, sing mbukak menyang Segara Marmara, pindhah menyang tangané Utsmaniyah. Nalika Bursa nyerah ing taun 1326, tekfur kutha iku dikirim menyang Gemlik bebarengan karo kulawargané; tegesé ing taun 1326 Gemlik isih ana ing tangané Bizantium. Ora ketemu tanggal kapisah kanggo Armutlu; Armutlu digandhèngaké karo ranté Gemlik.", "27ef02f4"]},
"OLAYLAR_EK:1346-06-01:0":{"b": ["Kramané Orhan Ghazi lan Theodora: persekutuan Bizantium", "9b67a590"], "d": ["Orhan Ghazi, sing nyengkuyung Kantakouzenos ing rebutan tahta Bizantium, krama karo putriné, Theodora; persekutuan iki ndadèkaké pasukan Utsmaniyah bisa kenal Rumelia kanthi cedhak.", "4f8f52d9"]},
"OLAYLAR_EK:1354-08-01:0":{"b": ["Direbuté Ankara", "49bf1f6d"], "d": ["Ankara sing dipimpin wong Ahi mlebu pamaréntahan Utsmaniyah; dalan menyang Anatolia Tengah kabukak. Panggonan liya sing digabungake ing tanggal sing padha: Sivrihisar, Çankırı.", "eec5d13e"]},
"OLAYLAR_EK:1357-01-01:0":{"b": ["Majuné ing Trakia ing jaman Suleyman Pasya: Malkara, İpsala lan Tekirdağ", "fb31cf02"], "d": ["Sawisé pancadan diadegaké ing Gallipoli, Suleyman Pasya metu ngalor saka semenanjung lan sethithik mbaka sethithik ngrebut dhataran antarané pesisir Marmara lan muarané Kali Maritsa. Kanthi mangkono Malkara, İpsala lan Rodosçuk (Tekirdağ) dadi koridor tanpa pedhot sing nyambungaké Gallipoli karo lembah Maritsa. Tanpa koridor iki ora bisa mlaku menyang Edirne; majuné, sing mandheg amarga sédané pangeran dumadakan ing 1357, bakal diterusaké Lala Şahin lan Hacı İlbey.", "721cac95"]},
"OLAYLAR_EK:1357-08-01:0":{"b": ["Pangeran Halil diculik", "b52ac3d7"], "d": ["Halil, putra enomé Orhan Ghazi, diculik bajak laut saka Foça (Phocaea); krisis tebusan nggawé repot sesambungan Utsmaniyah-Bizantium pirang-pirang taun.", "812e3cb6"]},
"OLAYLAR_EK:1360-01-01:0":{"b": ["Dipedhoté dalan pitulungan Edirne: bèntèng Çorlu, Lüleburgaz, Babaeski lan Keşan", "8e8ad485"], "d": ["Pangeran Murad, sing miwiti manèh gerakan penaklukan sawisé Halil dislametaké, ngirim para penyerang (akıncı) nganti ngarep Istanbul supaya Edirne kapisah saka pitulungan sing bisa teka saka njaba. Bèntèng Çorlu, Lüleburgaz lan Babaeski ing dalan Istanbul-Edirne lan Keşan ing simpang dalan Trakia Kidul direbut. Penyerahan Edirne teka sawisé bunderan pengepungan iki rampung.", "fb171002"]},
"OLAYLAR_EK:1361-01-01:0":{"b": ["Direbuté Dimetoka — bukaé lembah Maritsa", "b59aee83"], "d": ["Dimetoka (Didymoteicho), bèntèng kunci lembah Maritsa, direbut; kanthi mangkono dalan menyang penaklukan Edirne kabukak. Sadurungé koridor sing mulur ngalor saka Gallipoli rampung, ora bisa mlaku menyang Edirne, mula bèntèng iki ing urutan penaklukan Rumelia ana sadurungé Edirne. Kutha iku sauntara dadi markas Rumelia para sultan. Pasukan sing ngrebut Dimetoka banjur ngontrol kabeh tlatah Maritsa Tengah bebarengan karo bèntèng cilik kaya Kuleli Burgaz (Pythion).", "88f995b6"]},
"OLAYLAR_EK:1366-08-01:0":{"b": ["Kelangan Gallipoli (Perang Salib Savoy)", "00e7e415"], "d": ["Armada Amadeo saka Savoy, sedulur sepupuné kaisar Bizantium, ngrebut Gallipoli lan masrahaké marang Bizantium; pancadan Utsmaniyah ing Rumelia sajrone sepuluh taun diprentah saka sabrangé selat. Pamukiman liya sing ucul ing tanggal sing padha: Çimpe.", "b0c24ccd"]},
"OLAYLAR_EK:1371-09-26:0":{"b": ["Perang Çirmen — kontrol lembah Maritsa", "cd738d8d"], "d": ["Wadyabalané para bey Serbia dibubaraké ing serangan wengi; para bey lokal Serbia lan Bulgaria ing Makedonia lan Rhodope siji mbaka siji wiwit mbayar upeti marang Utsmaniyah — dudu penaklukan langsung, nanging wiwitan gelombang dadi bawahan. Ing riwayat Utsmaniyah perang iki uga dicritakaké kanthi jeneng 'Sırpsındığı' lan taun 1364, minangka serangan wengi Hacı İlbey marang wadyabala Salib sing teka kanggo ngrebut manèh Edirne; TDV nyatakaké yen tanggal iku salah lan crita loro iku babagan perang sing padha.", "7b2779cd"]},
"OLAYLAR_EK:1372-06-01:0":{"b": ["Penaklukan Plovdiv lan Stara Zagora", "e780c9ae"], "d": ["Plovdiv, ing sisih ndhuwur lembah Maritsa, lan Stara Zagora ing sisih loré direbut; Ketsaran Bulgaria dadi nagara sing mbayar upeti. Dalan Tatar Pazardzhik lan Ihtiman antarané Plovdiv lan Sofia tetep ana ing tangané para bey lokal sing dadi bawahan sawisé Çirmen. Pamukiman liya sing ucul ing tanggal sing padha: Haskovo, Klokotnitsa.", "019bac28"]},
"OLAYLAR_EK:1373-05-01:0":{"b": ["Bizantium bawahan: Yohanes V ing wadyabala Murad I (asilé kamenangan Çirmen 1371)", "13ffe568"], "d": ["Miturut TDV, sawisé kamenangan Çirmen (Maritsa) ing 26 September 1371, Kekaisaran Bizantium wis ngakoni kakuwasaan Utsmaniyah, lan kanthi nampa mbayar upeti lan ngabdi ing wadyabala Utsmaniyah, tiba dadi nagara bawahan. Kaisar Yohanes V, kanthi kuwajiban iki, ing 1373 mèlu wadyabalané Murad I; ing wektu iku putrané, Andronikos IV, sing ditinggal ing Istanbul, bebarengan karo Pangeran Savcı Bey ing Bursa mbrontak marang bapak-bapaké.", "3fe5b636"]},
"OLAYLAR_EK:1376-09-01:0":{"b": ["Gallipoli direbut manèh", "5f96c0a5"], "d": ["Andronikos IV, sing oleh dhukungan Utsmaniyah ing rebutan tahta Bizantium, minangka imbalané mbalèkaké Gallipoli; jembatan antarané Rumelia lan Anatolia diadegaké manèh. Panggonan liya sing digabungake ing tanggal sing padha: Çimpe.", "fc79cd5d"]},
"OLAYLAR_EK:1381-01-01:0":{"b": ["Mas kawin Germiyan: gabungé Kütahya", "d6a6fe61"], "d": ["Nalika Devletşah Hatun, putriné Süleyman Syah saka Germiyan, krama karo Bayezid Yildirim, Kütahya, Simav, Tavşanlı lan Eğrigöz pindhah menyang Utsmaniyah minangka mas kawin — conto klasik ékspansi tanpa perang. Panggonan liya sing digabungake ing tanggal sing padha: Afyon.", "3321bbba"]},
"OLAYLAR_EK:1381-06-01:0":{"b": ["Dituku provinsi Hamid: gabungé Isparta", "4a1b6047"], "d": ["Hamidoğlu Hüseyin Bey ngedol sapérangan kadipatené (Akşehir-Beyşehir-Isparta) marang Murad I kanthi dhuwit kontan; sisa provinsi Hamid bakal digabungaké déning Yildirim ing 1391. Pamukiman liya sing ucul ing tanggal sing padha: İshaklı.", "3930685b"]},
"OLAYLAR_EK:1383-09-19:0":{"b": ["Penaklukan Serres", "d4d28b60"], "d": ["Serres, kunci Makedonia Wétan, direbut; Thessaloniki mlebu ing bunderan pengepungan. Jalur Kyustendil-Petrich-Nevrokop-Drama antarané Sofia lan Serres ing tanggal iki durung digabungaké langsung; sacara gilir, ing antarané taun 1370-an nganti 1383 dadi bawahan, sawisé 1383 pindhah menyang pamaréntahan langsung. Pamukiman liya sing ucul ing tanggal sing padha: Gevgelija, Kilkis (Avrathisar).", "69be987a"]},
"OLAYLAR_EK:1385-09-01:0":{"b": ["Penaklukan Sofia", "96d5f01f"], "d": ["Dalan liwat sisih kulon pagunungan Balkan dikontrol; amarga ing tanggal iki Serres wis dicekel wiwit 1383, tanah Trakia lan Makedonia dadi siji wutuh tanpa pedhot.", "f358b568"]},
"OLAYLAR_EK:1386-01-01:0":{"b": ["Penaklukan Niš", "77f5d632"], "d": ["Kanthi direbuté Niš, kunci lembah Morava, Despotat Serbia kaancam langsung.", "15f52aaf"]},
"OLAYLAR_EK:1387-04-09:0":{"b": ["Penyerahan kapisan Thessaloniki", "96010ee9"], "d": ["Sawisé blokade dawa kutha iku nyerah (ing 1403 bakal dibalèkaké marang Bizantium lan ing 1430 ditaklukaké sacara pungkasan). Panggonan liya sing digabungake ing tanggal sing padha: Kavala. Pamukiman liya sing ucul ing tanggal sing padha: Langadas, Eleftheroupoli (Praviște).", "834119a2"]},
"OLAYLAR_EK:1387-06-08:0":{"b": ["Ahidname Utsmaniyah-Genoa — nganyaraké prajanjèn 1352", "be11d17a"], "d": ["Karo utusan Genoa saka Pera, persetujuan dagang 1352 sing saka jaman Orhan Ghazi dianyaraké; pajeg antarané rong nagara, carané ngladèni tawanan lan dagang bébas ditetepaké manèh. Iki dianggep ahidname paseduluran lan dagang kapisan sing resmi dimangertèni antarané Utsmaniyah lan wong Genoa — dudu persekutuan militèr, nanging prajanjèn sing sakabehé babagan dagang.", "46b0f65b"]},
"OLAYLAR_EK:1388-01-01:0":{"b": ["Ekspedisi Bulgaria Çandarlı Ali Pasya: direbuté Shumen lan Ruse", "2781c3a9"], "d": ["Bèntèng-bèntèng Ketsaran Bulgaria ing sadawané Kali Donau ditampa penyerahané ing siji ekspedisi; aja dikacoaké karo kekalahan ing Bileća ing Bosnia ing taun sing padha — iki suksès bebarengan ing front sing béda. Tarnovo lan Vidin dadi pusat Bulgaria pungkasan sing isih dicekel.", "d6eaf4cd"]},
"OLAYLAR_EK:1388-08-27:0":{"b": ["Kekalahan Bileća", "89ba0a64"], "d": ["Pasukan penyerang sing maju menyang Bosnia dicegat ing Bileća lan ditumpes; alangan gedhé kapisan ing Balkan iki nyemangati persekutuan sing banjur tekan Kosovo.", "9960a7a5"]},
"OLAYLAR_EK:1390-01-01:0":{"b": ["Panggabungan kadipaten Anatolia Kulon: Saruhan, Aydın, Menteşe", "dcc33b71"], "d": ["Telung kadipaten digabungaké ing siji ekspedisi: pusat wong Saruhan, Manisa; pusat wong Aydın, Aydın (kalebu bèntèng ndhuwur Izmir, nanging plabuhan/bèntèng ngisor isih ing tangané Ksatria Santo Yohanes — nganti 1402); pusat wong Menteşe, Muğla-Milas, kalebu jalur pesisir Datça-Bodrum-Marmaris-Fethiye. Pesisir Aegea kanggo kaping pisan manunggal ing siji tangan. Panggonan liya sing digabungake ing tanggal sing padha: Söke.", "7f3094f2"]},
"OLAYLAR_EK:1392-01-01:0":{"b": ["Panggabungan provinsi Teke: gabungé Antalya", "fdbeee5c"], "d": ["Provinsi Teke ing pesisir Segara Tengah digabungaké menyang wilayah Utsmaniyah. Wong Teke iku cabang sing misah saka wong Hamid: Feleküddin Dündar Bey masrahaké Antalya, sing ditaklukaké, marang adhiné Yunus Bey, lan udakara taun 1321 lair kadipaten kapisah. Mula saka iku Antalya lan sakiwa-tengené ing peta sawisé 1321 dituduhaké ora nganggo warnané wong Hamid, nanging warnané wong Teke. Kadipaten iku diadegaké manèh sawisé Perang Ankara lan lagi disingkiraké sacara pungkasan ing 1423.", "09a83d97"]},
"OLAYLAR_EK:1392-01-06:0":{"b": ["Penaklukan Skopje", "9e5a1af5"], "d": ["Pusat Makedonia Vardar direbut; Skopje dadi salah siji pusat tapel wates utama Rumelia.", "8722b1dd"]},
"OLAYLAR_EK:1392-11-01:0":{"b": ["Panggabungan Kastamonu", "876330ba"], "d": ["Cabang Kastamonu saka wangsa Candaroğlu disingkiraké; cabang Sinop lumaku terus minangka bawahan. Panggonan liya sing digabungake ing tanggal sing padha: Bartın, Safranbolu, Akçakoca, Devrek, Eflani, Karadeniz Ereğli, Tosya.", "c1158ca8"]},
"OLAYLAR_EK:1393-06-17:0":{"b": ["Tibané Tarnovo — panggabungan Bulgaria", "ff666977"], "d": ["Ibu kutha Ketsaran Bulgaria tiba; Bulgaria mlebu pamaréntahan Utsmaniyah langsung. Panggonan liya sing digabungake ing tanggal sing padha: Pleven, Lovech, Gabrovo.", "c2c12ea0"]},
"OLAYLAR_EK:1393-06-17:1":{"b": ["Bèntèng Lovech pindhah menyang Utsmaniyah", "a55e87a0"], "d": ["Lovech, salah siji bèntèngé tsar Bulgaria Ivan Shishman, ing ekspedisi 1393 nalika Tarnovo tiba digabungaké menyang wilayah Utsmaniyah bebarengan karo provinsi-provinsi liyané Shishman. Sumber ora ngomong kanthi mesthi: penaklukan ing taun iki 'diperkirakaké'.", "9430a123"]},
"OLAYLAR_EK:1393-09-01:0":{"b": ["Gabungé Dobruja", "478e36f2"], "d": ["Tanah Dobruja sing tekan delta Donau digabungaké. Panggonan liya sing digabungake ing tanggal sing padha: Silistra, Constanța, Babadag, Balchik, Hârșova, Tulcea, Mangalia, Isaccea, Tutrakan, Măcin, Küçük Kaynarca.", "84901de2"]},
"OLAYLAR_EK:1394-01-01:0":{"b": ["Mudhun menyang Tesalia", "8bec60dd"], "d": ["Dhataran Tesalia sing pusaté ing Yenişehir (Larissa) dijupuk ing pamaréntahan Utsmaniyah. Panggonan liya sing digabungake ing tanggal sing padha: Tırhala, İzdin (Lamia).", "d9f2128c"]},
"OLAYLAR_EK:1394-10-10:0":{"b": ["Perang Rovine — ekspedisi Wallachia", "343ae7a9"], "d": ["Sawisé perang getih sing asilé isih dadi pasulayan nglawan Mircea, voivoda Wallachia, Wallachia sarujuk mbayar upeti marang Utsmaniyah; tatanan bawahan ing sisih lor Donau diadegaké.", "dd69200f"]},
"OLAYLAR_EK:1395-01-01:0":{"b": ["Penaklukan Nikopolis", "b9791717"], "d": ["Sawisé perang Rovine 1395 nglawan wong Wallachia, Bayezid Yildirim ngrebut bèntèng Nikopolis ing pinggir Kali Donau; sawetara kronik Bulgaria anonim nyebut yen penaklukan kedadéan ing 3 Juni 1395. Tanggal penaklukan ora padha ing sumber-sumber: artikel Perang Nikopolis ing TDV İslâm Ansiklopedisi nulis yen Bayezid ngrebut Silistra lan Nikopolis ing ekspedisi Donau taun 1394. Bèntèng iku bakal dikepung ing Perang Salib sing misuwur taun 1396, nanging ora bakal tiba. Panggonan liya sing digabungake ing tanggal sing padha: Ohrid.", "bc450a9f"]},
"OLAYLAR_EK:1395-06-03:0":{"b": ["Bèntèng Nikopolis pindhah menyang Utsmaniyah", "327012c9"], "d": ["Sawisé serangan Rovine, Bayezid Yildirim ngrebut Nikopolis; tsar Bulgaria Ivan Shishman, sing lungguh ing kono minangka bawahan Utsmaniyah, disingkiraké. Ing atlas, Nikopolis kacathet pindhah saka Ketsaran Bulgaria menyang Utsmaniyah wiwit dina iki.", "6e7d5207"]},
"OLAYLAR_EK:1395-08-01:0":{"b": ["Pambangunan Anadolu Hisarı", "aa259b00"], "d": ["Kanggo nyengkuyung blokade Istanbul, Güzelcehisar (Anadolu Hisarı) dibangun ing sisih Anatolia Selat Bosporus — langkah tetep kapisan kanggo ngontrol selat.", "a1b2f889"]},
"OLAYLAR_EK:1396-10-01:0":{"b": ["Panggabungan Vidin", "ee1ae44b"], "d": ["Sawisé kamenangan Nikopolis, Vidin, kapangéranan Bulgaria pungkasan, uga digabungaké.", "28f4258d"]},
"OLAYLAR_EK:1397-07-01:0":{"b": ["Panggabungan kapisan Karaman", "3cf07876"], "d": ["Kanthi kamenangan Akçay, tanah wong Karaman kanggo kaping pisan digabungaké menyang Utsmaniyah (bakal diadegaké manèh ing Mangsa Interregnum).", "788bdca3"]},
"OLAYLAR_EK:1398-07-01:0":{"b": ["Gabungé pesisir Canik: Samsun", "af9c40fa"], "d": ["Ing kekosongan sing kedadéan amarga Kadi Burhaneddin ditawan déning Karayülük Osman Bey saka Aq Qoyunlu, Bayezid Yildirim dhisik nggandhèngaké tlatah Canik ing pesisir Segara Ireng karo pamaréntahan Utsmaniyah. Kanthi mangkono Samsun lan sakiwa-tengené dadi plabuhan Segara Ireng kapisan kagungané wangsa iku. Jalur Sivas-Tokat-Kayseri ing pedalaman bakal digabungaké rong minggu sabanjuré, nalika Nagara Kadi Burhaneddin sejatiné bubar.", "4b2f9a80"]},
"OLAYLAR_EK:1399-09-01:0":{"b": ["Direbuté Malatya", "7cb6ae16"], "d": ["Malatya ing tapel wates Mamluk direbut — salah siji langkah sing nambah tegang sesambungan karo Timur.", "3b7ba002"]},
"OLAYLAR_EK:1400-01-01:0":{"b": ["Timur ngrebut Malatya lan nilaraké marang Karayülük Osman — nalika Timur mundur, wong Dulkadir ngrebut manèh", "ad2ce7d8"], "d": ["Bayezid Yildirim bali menyang Bursa kanthi nilaraké Malatya, sing direbut ing 1399, marang Nasreddin Mehmed saka Dulkadir. Timur, sing mlebu Anatolia ing 1400, ngrebut dhisik Sivas lan Elbistan, banjur Malatya; kutha lan sakiwa-tengené dijarah, lan pamaréntahané dipasrahaké marang Karayülük Osman sing ana ing sandhingé Timur. Nalika Timur ninggalaké tlatah iku, wong Dulkadir nguwasani manèh Malatya; kanthi mangkono kakuwasaan Utsmaniyah rampung sadurungé Perang Ankara.", "5889cce9"]},
"OLAYLAR_EK:1403-06-01:0":{"b": ["Prajanjèn Suleyman Celebi – Bizantium: Thessaloniki dibalèkaké", "cc503cc2"], "d": ["Suleyman Celebi, sing ing Mangsa Interregnum mréntah Rumelia, kanthi sarujuk karo Bizantium lan nagara-nagara Latin masrahaké Thessaloniki lan pesisir Segara Ireng nganti Mesembria marang Bizantium (TDV fetret-devri: Prajanjèn Gallipoli, Februari 1403) — ing peta İğneada, Rezve lan Ahtapolu pindhah menyang Bizantium; ing peta Thessaloniki ing tanggal iki metu saka Utsmaniyah.", "ac791637"]},
"OLAYLAR_EK:1416-05-29:0":{"b": ["Kekalahan laut Gallipoli (Venesia)", "b71d4d68"], "d": ["Armada Venesia ngalahaké armada Utsmaniyah kanthi abot ing ngarep Gallipoli; kedadéan iki nuduhaké watesé pelayaran Utsmaniyah ing mangsa wiwitan.", "7166c255"]},
"OLAYLAR_EK:1421-08-15:0":{"b": ["Pambrontakan Düzmece Mustafa", "0ec43138"], "d": ["Mustafa Celebi, sing ngaku putrané Yildirim, kanthi dhukungan Bizantium ngumumaké kasultanan ing Rumelia; Murad II madhemaké pambrontakan ing 1422 lan ndhawuhaké saingané diukum pati.", "9bae8d0d"]},
"OLAYLAR_EK:1422-06-10:0":{"b": ["Pengepungan Istanbul déning Murad II", "4b9d9fba"], "d": ["Minangka walesan marang dhukungan Bizantium kanggo Düzmece Mustafa, Murad II ngepung Istanbul; pengepungan dicabut nalika sedulure, Küçük Mustafa, dibrontakaké ing Anatolia.", "bc254acf"]},
"OLAYLAR_EK:1423-09-14:0":{"b": ["Pangalihan Thessaloniki marang Venesia", "bfa6c4a0"], "d": ["Gubernur Bizantium, sing ditekan Utsmaniyah, masrahaké kutha iku marang Venesia; rebutan Utsmaniyah-Venesia sing bakal lumaku pitung taun diwiwiti.", "da60fe5f"]},
"OLAYLAR_EK:1425-06-01:0":{"b": ["Panggabungan manèh kadipaten Anatolia Kulon: Menteşe lan Aydın", "aca30a48"], "d": ["Rong kadipaten Aegea sing diadegaké manèh ing Mangsa Interregnum digabungaké sacara pungkasan menyang wilayah Utsmaniyah ing jaman Murad II. Miturut artikel TDV bab Menteşeoğulları, Murad II ngrebut provinsi Menteşe ing 827 (1424) lan ngunjara sedulur loro sing mimpin kadipaten iku. Miturut artikel bab Aydınoğulları, Hamza Bey, Beylerbey Anatolia, ndhawuhaké nyekel Cüneyd Bey, sing mbalik ora manut manèh, lan ngukum pati bebarengan karo kulawargané (829/1425-26), lan provinsi Aydın pindhah menyang Utsmaniyah. Ksatria Santo Yohanes, sing nyekel bèntèng plabuhan Izmir wiwit 1344, wis kelangan iku menyang Timur ing 1402, lan tlatah iku bali menyang kontrol wong Aydın; kanthi panggabungan iki tlatah iku uga gabung menyang Utsmaniyah. Provinsi Teke (Antalya) dudu bab artikel iki: wong Teke wis disingkiraké kapisah ing 1423. Déné Germiyan bakal gabung liwat wasiyat ing 1429.", "92fa8d97"]},
"OLAYLAR_EK:1429-01-01:0":{"b": ["Panggabungan Germiyan liwat wasiyat", "9eb86b77"], "d": ["Yakub II, bey Germiyan sing séda tanpa putra, ninggalaké nagarané marang Utsmaniyah liwat wasiyat — conto panggabungan tanpa perang sing mlebu buku pelajaran. Panggonan liya sing digabungake ing tanggal sing padha: Karahisâr-ı Sâhib (Afyon).", "9173c7b2"]},
"OLAYLAR_EK:1430-03-29:0":{"b": ["Penaklukan pungkasan Thessaloniki", "bc021768"], "d": ["Kutha sing diprentah Venesia direbut kanthi serangan; plabuhan gedhé kapindho Rumelia sacara pungkasan dadi duwèké Utsmaniyah. Panggonan liya sing digabungake ing tanggal sing padha: Kesendire (Kassandra).", "8853e257"]},
"OLAYLAR_EK:1430-10-09:0":{"b": ["Penyerahan Ioannina", "ee45cb52"], "d": ["Ioannina, pusat Epirus, nyerah liwat prajanjèn.", "1aad46c0"]},
"OLAYLAR_EK:1439-08-27:0":{"b": ["Direbuté Smederevo kaping pisan", "c11ca17d"], "d": ["Kanthi pengepungan telung sasi, ibu kutha Despotat Serbia direbut lan Serbia kanggo kaping pisan digabungaké (bakal dibalèkaké liwat Prajanjèn Edirne-Szeged 1444).", "3dc4dfe5"]},
"OLAYLAR_EK:1440-04-01:0":{"b": ["Pengepungan Beograd (gagal)", "3e05f425"], "d": ["Pengepungan gedhé Beograd kapisan sing lumaku enem sasi ora ana asilé; bèntèng iku wolung puluh taun tetep dadi kunci ing ngarep majuné Utsmaniyah.", "2a88be8a"]},
"OLAYLAR_EK:1443-11-24:0":{"b": ["Bubrah Zlatica — 'Ekspedisi Dawa'", "97df1466"], "d": ["Wadyabala sing digawa Hunyadi mlebu Balkan ing tengah mangsa adhem ngliwati Niš lan Sofia nganti tekan Zlatica; pertahanan Utsmaniyah angel banget bisa tahan. Swasana bubrah iki nggawa tentrem Edirne-Szeged menyang meja.", "cf103982"]},
"OLAYLAR_EK:1444-06-12:0":{"b": ["Prajanjèn Edirne-Szeged", "0aa4e0de"], "d": ["Tentrem sepuluh taun: Despotat Serbia dibalèkaké, Donau ditampa dadi tapel wates. Dirusaké prajanjèn sajrone sawetara sasi amarga hasutan kapausan njalari bilai Varna.", "46b3ced6"]},
"OLAYLAR_EK:1444-08-15:0":{"b": ["Smederevo lan bèntèng-bèntèng Serbia dibalèkaké marang Serbia", "cda3cf9e"], "d": ["Katetepan Prajanjèn Edirne-Szeged ditindakaké: ing 15 Agustus 1444 Murad II mbalèkaké Smederevo marang Đurađ Branković bebarengan karo patlikur bèntèng wigatiné lan tanah Serbia liyané sing didhudhuki (TDV semendire); Niš (TDV nis), Alacahisar (TDV alacahisar), Şehirköy (TDV sehirkoy) lan Pristina (TDV pristine) uga dipasrahaké marang wong Serbia. Vidin, amarga dudu tanah Serbia, ora klebu sing dibalèkaké — iki asalé kelangan wilayah lor-kulon sing katon ing peta sakiwa-tengené kamenangan Varna; sawetara sasi sabanjuré, kanthi bubrahé Varna, prajanjèn iku wis ora ana dayané.", "19c68a1f"]},
"OLAYLAR_EK:1452-08-31:0":{"b": ["Rumeli Hisarı rampung — 'sing Medhot Selat' (Boğazkesen)", "480e8a76"], "d": ["Kanthi bèntèng sing, miturut sumber-sumber, rampung ing pambangunan sing cepet banget, lumaku patang nganti limang sasi, kontrol Bosporus pindhah kabeh menyang Utsmaniyah; dalan pitulungan saka Segara Ireng menyang Istanbul katutup. Iki dianggep langkah nyata kapisan pengepungan.", "1d84cd36"]},
"OLAYLAR_EK:1453-04-06:0":{"b": ["Pengepungan Istanbul diwiwiti", "8af50742"], "d": ["Wadyabala manggon ing ngarep témbok; ing pengepungan sing bakal lumaku 54 dina, mriyem raseksa kanggo kaping pisan digunakaké kanthi sistematis marang témbok ibu kutha.", "6d71da31"]},
"OLAYLAR_EK:1453-04-22:0":{"b": ["Kapal diudhunaké liwat dharatan menyang Tanduk Emas", "4f2ba07c"], "d": ["Kira-kira 70 kapal saka armada sing ora bisa mlebu Tanduk Emas sing ditutup ranté, ditarik nganggo luncuran sing diolesi lenga ngliwati gumuk Galata lan sewengi diudhunaké menyang Tanduk Emas; pertahanan dipérang dadi rong front.", "2eb65d41"]},
"OLAYLAR_EK:1456-06-04:0":{"b": ["Penaklukan Athena", "4f0f1bb2"], "d": ["Kadipaten Athena rampung; gendéra Utsmaniyah dikibaraké ing Akropolis. Panggonan liya sing digabungake ing tanggal sing padha: İstefe (Thebes), Livadeia.", "a912625d"]},
"OLAYLAR_EK:1459-06-20:0":{"b": ["Panggabungan Serbia (tibané Smederevo)", "75fd0a62"], "d": ["Smederevo, ibu kutha Despotat Serbia, nyerah; Serbia dadi sanjak Utsmaniyah.", "29bd2888"]},
"OLAYLAR_EK:1460-05-29:0":{"b": ["Penaklukan Morea", "7d5a3c18"], "d": ["Despotat Morea disingkiraké; semenanjung iku (kejaba bèntèng-bèntèng Venesia) mlebu pamaréntahan Utsmaniyah.", "14aba74c"]},
"OLAYLAR_EK:1461-06-01:0":{"b": ["Gabungé Sinop", "e03c2739"], "d": ["Panguwasa Candaroğlu ing Sinop nyerah tanpa perang; dalan kanggo ekspedisi Trebizond kabukak. Panggonan liya sing digabungake ing tanggal sing padha: Kastamonu, Bartın, Safranbolu. Artikel TDV bab Candaroğulları uga nyebut Bolu, Eflani lan Tosya ing antarané tanah kadipaten Candaroğlu sing digabungaké ing 1461; ing atlas telung panggonan iku uga ditulis pindhah saka Candaroğlu menyang Utsmaniyah ing dina iki. Pamukiman liya sing ucul ing tanggal sing padha: Karadeniz Ereğli, Devrek, Akçakoca (tanah Candaroğlu).", "9ead5a1c"]},
"OLAYLAR_EK:1463-06-01:0":{"b": ["Ambruké Krajan Bosnia — ekspedisi Bosnia Sang Penakluk", "5362e3f2"], "d": ["Nalika raja Bosnia pungkasan, Stjepan Tomašević (1461-1463), kanthi ngandelaké dhukungan Kulon nolak mbayar upeti, panjenengané dianggep wis ora dadi panguwasa bawahan manèh, lan wadyabala sing dipimpin Sang Penakluk, Sultan Mehmed, nyingkiraké Krajan Bosnia ing siji ekspedisi. Raja dicekel lan diukum pati, krajan ilang lan sanjak Bosnia diadegaké ing tlatah iku. Nanging ambruké krajan ora padha karo penaklukan Bosnia. Pamaréntahan Utsmaniyah ing dhataran wis ana limalas taun — Hodidjed lan dhataran Saray direbut ing 1448, lan wilayah tapel wates Isa Bey diadegaké ing tengah krajan. Penaklukan uga ora rampung ing 1463: Foča direbut ing 1465, Livno ing 1469, Kadipaten Hercegovina ing 1483, banat Srebrenik ing 1512, lan Jajce sarta Banja Luka ing lor lagi bisa direbut ing 1528 sawisé Mohács — wong Hungaria wis ngadegaké banat ing Bosnia lor sing tahan sewidak lima taun sawisé 1463. Panggonan sing ganti tangan langsung ing tanggal iki yaiku Travnik; déné Jajce ing tanggal iki ora pindhah menyang Utsmaniyah, nanging menyang Hungaria.", "5ac16344"]},
"OLAYLAR_EK:1468-01-01:0":{"b": ["Panggabungan pungkasan Karaman", "f1dcecaa"], "d": ["Tanah pusat wong Karaman digabungaké sacara pungkasan; pasulayan njero lumaku terus nganti taun 1470-an. Panggonan liya sing digabungake ing tanggal sing padha: Niğde, Mostar, Beyşehir.", "da6cfd4c"]},
"OLAYLAR_EK:1470-07-12:0":{"b": ["Penaklukan Negroponte", "5c97daf3"], "d": ["Negroponte (Eğriboz), pangkalan utama Venesia ing Segara Aegea, tiba.", "189cc474"]},
"OLAYLAR_EK:1471-01-01:0":{"b": ["Panggabungan Alanya, Anamur lan Silifke (İçel)", "a0b9d461"], "d": ["Jalur pesisir İçel sing manut marang wong Karaman (kabeh pesisir Segara Tengah antarané Antalya lan Mersin) digabungaké liwat ekspedisi laut Gedik Ahmed Pasya; Alanya wigati amarga galangan kapal stratégisé sing saka jaman Seljuk.", "8302df58"]},
"OLAYLAR_EK:1478-01-15:0":{"b": ["Panggabungan Novgorod menyang Moskwa", "bed87170"], "d": ["Adipati Agung Ivan III nyopot lonceng lambang majelis rakyat (veche) ing Novgorod, ngganti pejabat lokal karo gubernuré dhéwé lan sejatiné nggandhèngaké kutha iku karo Moskwa; Novgorod ora dadi republik mardika manèh. Tanah Novgorod mulur saka Segara Baltik nganti Segara Putih lan Pagunungan Ural. Ing atlas, Novgorod kacathet pindhah saka Republik Novgorod menyang Moskwa wiwit dina iki.", "65b660e7"]},
"OLAYLAR_EK:1479-01-25:0":{"b": ["Prajanjèn Istanbul — Albania lan Shkodër", "b09652f7"], "d": ["Perang Utsmaniyah-Venesia 16 taun rampung; Shkodër lan pesisir Albania tetep ing Utsmaniyah. Panggonan liya sing digabungake ing tanggal sing padha: Limnos, Samos, Bozbaba (Agios Efstratios).", "bc2aebf2"]},
"OLAYLAR_EK:1480-08-11:0":{"b": ["Pandharatan Otranto", "7916b89d"], "d": ["Pasukan Utsmaniyah sing ndharat ing pesisir Apulia (Puglia) ngepung lan ngrebut bèntèng Otranto; amarga kutha dilebeti kanthi perang, sapérangan pimpinan sing nglawan diukum pati lan sapérangan ditawan. Tradhisi greja ngéling-éling sing mati minangka 'Syuhada Otranto', kira-kira 800 wong; TDV ngubungaké digedhèkaké cacah iki karo propaganda greja. Mung bèntèng ing pucuk semenanjung Salento lan sakiwa-tengené sing ciyut sing dicekel; tanah Krajan Napoli sing kari ing jalur Taranto-Brindisi-Lecce ora ucul — pancadan iki sing mbukak menyang Italia bakal lumaku setaun.", "0e1004b8"]},
"OLAYLAR_EK:1481-09-10:0":{"b": ["Dikosongaké Otranto", "37371bb0"], "d": ["Garnisun Otranto, sing ora duwé pangarep-arep bantuan anyar sawisé sédané Sultan Mehmed Sang Penakluk (3 Mei 1481), ngadhepi pengepungan Alfonso, putra mahkota Napoli, ngosongaké bèntèng kanthi prajanjèn; kanthi mangkono siji-sijiné pancadan Utsmaniyah ing Italia ucul sawisé setaun.", "961ef9c3"]},
"OLAYLAR_EK:1500-08-09:0":{"b": ["Penaklukan Modon lan Koron", "38b608c4"], "d": ["Modon lan Koron, 'mripat loro' Venesia ing Morea, direbut.", "a11c09d0"]},
"OLAYLAR_EK:1501-08-17:0":{"b": ["Penaklukan Durrës", "1f231b98"], "d": ["Ing perang Utsmaniyah-Venesia 1499-1503, pasukan sing dipimpin Mehmed Bey ngrebut Durrës (Draç), plabuhan Albania gedhé pungkasan Venesia ing Adriatik. Sawisé Shkodër (1479) lan Vlorë (1417), kanthi penaklukan iki jalur pesisir Albania mlebu ing kontrol Utsmaniyah kabeh.", "ad635bca"]},
"OLAYLAR_EK:1515-09-15:0":{"b": ["Gabungé Anatolia Wétan", "e0cb8f8f"], "d": ["Sawisé Chaldiran, Diyarbakır lan sakiwa-tengené digabungaké; kadipaten-kadipaten Kurdi digandhèngaké karo Utsmaniyah liwat Idris Bitlisi.", "025d3ddc"]},
"OLAYLAR_EK:1526-07-27:0":{"b": ["Penaklukan Bèntèng Varadin (Petrovaradin)", "abf392a5"], "d": ["Wadyabala sing budhal ekspedisi Mohács nyabrang saka Beograd menyang tanah Hungaria; dhisik kampung njaba Varadin direbut, banjur sawisé pengepungan patbelas dina bèntèng uga tiba. Sang Pembuat Undhang-undhang ndhawuhaké supaya désa-désa ing dalan aja diobong, amarga saiki dianggep tanah Utsmaniyah.", "60a4ae4e"]},
"OLAYLAR_EK:1526-09-01:0":{"b": ["Penyerahan Buda sawisé Mohács — raja loro kanggo tahta Hungaria", "9d3568a0"], "d": ["Kunci kutha diaturaké marang sultan ing 11 September 1526 menyang wadyabala Utsmaniyah sing mlaku menyang Buda sawisé kamenangan Mohács; nanging Sang Pembuat Undhang-undhang ora nyekel Buda lan narik mundur wadyabalané. Ing Hungaria, sing ora duwé raja, para bangsawan milih raja loro sing béda: János Szapolyai ing 10 November 1526, lan Ferdinand I saka Habsburg ing 17 Desember 1526. Ferdinand ngrebut Buda ing Agustus 1527. Szapolyai bakal manggon ing Buda minangka raja ing pangayoman Utsmaniyah liwat ekspedisi 1529 (deleng artikel 1529), lan pamaréntahan Utsmaniyah langsung bakal diadegaké ing 1541.", "d68817d3"]},
"OLAYLAR_EK:1526-11-10:0":{"b": ["János Szapolyai kapilih dadi raja Hungaria — Utsmaniyah ngakoni krajané kanthi syarat dadi bawahan", "32bc6baf"], "d": ["Kanggo tahta Hungaria sing kosong amarga sédané raja ing Mohács, sapérangan bangsawan milih János Szapolyai, voivoda Transylvania; Szapolyai dimahkotai ing Székesfehérvár. Utsmaniyah, sing ngosongaké Buda, ngakoni krajan Szapolyai kanthi syarat manut marang awaké dhéwé supaya tlatah iku tetep dadi panyangga. Ing peta, panggonan sing manut marang Szapolyai wiwit tanggal iki katon minangka bawahan Utsmaniyah.", "1d697cbd"]},
"OLAYLAR_EK:1526-12-17:0":{"b": ["Ferdinand I diproklamasikaké raja Hungaria — Hungaria Kulon lan Lor menyang mahkota Habsburg", "b3910a2f"], "d": ["Adipati Agung Habsburg Ferdinand, adhedhasar kraman sedulur wadoné karo Louis II, ngaku duwé hak ing tahta Hungaria lan diproklamasikaké raja déning sapérangan bangsawan. Kanthi mangkono Hungaria dipérang antarané raja loro; sisih kulon lan lor ngakoni Ferdinand. Para bangsawan Kroasia milih panjenengané kapisah ing awal 1527.", "1484af4c"]},
"OLAYLAR_EK:1530-01-01:0":{"b": ["Rebutané raja loro: Esztergom ing pangayoman Habsburg, Szeged melu Szapolyai", "da92dee5"], "d": ["Esztergom, sing wiwit 1526 ganti tangan antarané raja loro, mlebu pangayoman Habsburg sawisé uskup agung pindhah ngalor karo arsip lan kasé. Wiwit taun iku nganti 1541, Szeged tetep ing kedaulatané Szapolyai.", "4317e319"]},
"OLAYLAR_EK:1532-01-01:0":{"b": ["Wong Pécs pindhah menyang pihak Szapolyai", "3fc4e7f2"], "d": ["Pécs, sing ing 1528 oleh hak istiméwa saka Ferdinand, ora suwe sabanjuré pindhah menyang pihak Szapolyai; Raja János manggon sauntara ing kutha iku ing 1533. Kanthi tibané Buda ing 1541, kutha iku bali manèh menyang pihak Ferdinand.", "af03d9f3"]},
"OLAYLAR_EK:1551-08-15:0":{"b": ["Penaklukan Tripoli", "8c659986"], "d": ["Tripoli direbut saka para Ksatria Santo Yohanes; pesisir tengah Afrika Lor dadi duwèké Utsmaniyah. Panggonan liya sing digabungake ing tanggal sing padha: Misrata.", "f3a5310d"]},
"OLAYLAR_EK:1552-07-27:0":{"b": ["Penaklukan Temeşvar", "e9fd4995"], "d": ["Tlatah Banat direbut lan Beylerbeylik Temeşvar diadegaké.", "1b99085d"]},
"OLAYLAR_EK:1574-08-25:0":{"b": ["Penaklukan pungkasan Tunis", "7bbd11bc"], "d": ["Tunis, sing ana ing kontrol Spanyol-Hafsiyah, mlebu pamaréntahan Utsmaniyah sacara pungkasan; jalur Afrika Lor rampung. Panggonan liya sing digabungake ing tanggal sing padha: Kairouan, Gabès, Sfax.", "a92c818a"]},
"OLAYLAR_EK:1600-10-20:0":{"b": ["Penaklukan Kanije", "0c7b6aa3"], "d": ["Kanije direbut ing Perang Dawa; taun candhaké pertahanan Tiryaki Hasan Pasya dadi crita kepahlawanan.", "12042d94"]},
"OLAYLAR_EK:1663-04-13:0":{"b": ["Ekspedisi Uyvar diwiwiti — Fazil Ahmed Pasya mlaku saka Edirne nglawan Austria", "306a86db"], "d": ["Amarga Austria nyerang Transylvania lan ngrebut bèntèng Székelyhíd lan Kolozsvár, Istanbul mutusaké ekspedisi nglawan Habsburg. Wazir Agung Köprülüzade Fazil Ahmed Pasya budhal saka Edirne ing 13 April 1663. Ing Beograd teka panyuwunan tentrem saka Austria, nanging ing rembugan kaping pindho ing Osijek syarat-syarat Utsmaniyah ditolak. Ing musyawarah ing Buda tujuané uga ditetepaké Uyvar.", "f77c2f04"]},
"OLAYLAR_EK:1663-09-24:0":{"b": ["Penaklukan Uyvar", "ce289470"], "d": ["Uyvar (Nové Zámky), bèntèng kunci Hungaria Lor, direbut; paribasan 'kuwat kaya wong Turki ing ngarep Uyvar' mlebu basa-basa Éropah. Sawisé Uyvar, Nitra lan Léva uga nyerah sawisé perlawanan cendhak; loro-loroné direbut manèh déning De Souches ing musim semi 1664.", "80ef48fc"]},
"OLAYLAR_EK:1715-07-01:0":{"b": ["Morea direbut manèh", "9b6460f1"], "d": ["Morea, sing ing Karlowitz dipasrahaké marang Venesia, direbut manèh ing siji ekspedisi. Panggonan liya sing digabungake ing tanggal sing padha: Patras (Balyabadra), İnebahtı.", "56dc13ce"]},
"OLAYLAR_EK:1717-08-18:0":{"b": ["Kelangan Beograd kaping pindho — pengepungan Pangeran Eugene", "6a194354"], "d": ["Sawisé bubrah Varadin lan kelangan Temeşvar, Pangeran Eugene ngepung Beograd; nalika wadyabala pitulung sing teka nylametaké kutha uga dibubaraké, bèntèng nyerah. Kutha sing sawisé Karlowitz direbut manèh ing 1690 kanthi mangkono ucul manèh lan garis pertahanan Donau ambruk. Beograd lagi bisa direbut manèh rong puluh loro taun sabanjuré, liwat Prajanjèn Beograd 1739. Pamukiman liya sing ucul ing tanggal sing padha: Smederevo. Atlas uga nulis tlatah Hisarcık (Grocka) lan Yagodina (Jagodina) ing dina iki menyang Habsburg (dina tlatah; dina tingkat panggonan ora ana ing sumber, perkiraan sing wis diumumaké); déné Mehadia pindhah menyang Habsburg ing 27 Agustus 1717 (Bánlaky 0019/1715).", "83c63cd6"]},
"OLAYLAR_EK:1788-12-17:0":{"b": ["Tibané Özi", "90a67a6c"], "d": ["Özi (Ochakov), bèntèng kunci ing sisih lor Segara Ireng, tiba ing tangané Rusia liwat serangan getih; pendhudhuk kutha dipatèni nganggo pedhang.", "9d37026c"]},
"OLAYLAR_EK:1812-05-28:0":{"b": ["Prajanjèn Bukares — kelangan Bessarabia", "932da4d6"], "d": ["Liwat prajanjèn sing mungkasi perang Rusia 1806-1812, tlatah ing wétan Kali Prut (Bessarabia) dipasrahaké marang Rusia. Pamukiman liya sing ucul ing tanggal sing padha: Akkerman, Kiliya, Khotyn, Bender, Izmail. Atlas uga nganggep Chișinău, Bălți, Cahul lan Orhei ing njero Bessarabia pindhah saka Moldavia (bawahan Utsmaniyah) menyang Rusia ing dina sing padha. Soroca uga pindhah menyang Rusia ing dina sing padha.", "b5921c60"]},
"OLAYLAR_EK:1829-09-14:0":{"b": ["Prajanjèn Edirne", "b3a8fe4c"], "d": ["Ing pungkasané perang nalika wadyabala Rusia mlebu Edirne, delta Donau ilang; otonomi/kamardikan Yunani sejatiné ditampa. Pamukiman liya sing ucul ing tanggal sing padha: Brăila, Anapa, Akhaltsikhe. Senajan prajanjèn mbalèkaké tanah, pendhudhukan ora langsung rampung: Wallachia-Moldavia lan Silistra tetep ing pamaréntahan Rusia minangka tanggungan nganti ganti rugi perang dibayar — iki sebabé panggonan-panggonan iku ing peta isih katon didhudhuki sawisé 1829. Pengaku Utsmaniyah bab Sirkasia (Maykop) lan pesisir Sirkasia (Sochi, Tuapse) uga rampung kanthi prajanjèn iki; pesisir iku banjur pindhah menyang Rusia (Sochi lan Tuapse 1838).", "5666619b"]},
"OLAYLAR_EK:1830-10-17:0":{"b": ["Maklumat otonomi kanggo Serbia — pangéran turun-temurun lan syarat garnisun", "6a5d901d"], "d": ["Hatt-i humayun sing diwetokaké miturut katetepan Prajanjèn Edirne bab Serbia ngakoni Miloš Obrenović minangka knez (pangéran) turun-temurun lan ndadèkaké Serbia kapangéranan otonom sing bébas ing urusan njero lan manut marang Utsmaniyah ing urusan njaba. Katetepané: jabatan knez bakal turun saka bapak menyang anak, pajeg taunan tetep dibayar, majelis Serbia bakal ngadegaké pamaréntahan njeroné dhéwé, greja bakal otonom; minangka imbalané, garnisun Utsmaniyah bakal tetep ing bèntèng Beograd, Smederevo, Šabac, Soko lan Ušće (Fethülislâm). Susunan rangkep iki lumaku nganti garnisun ditarik ing 1867. Ing peta kutha Beograd gabung menyang Serbia otonom ing tanggal iki; bèntèng Kalemegdan nganti 1867 dituduhaké isih ana garnisun Utsmaniyah.", "b71abc85"]},
"OLAYLAR_EK:1878-06-04:0":{"b": ["Siprus dipasrahaké marang pamaréntahan Inggris", "423da3ee"], "d": ["Minangka imbalané persekutuan nglawan ancaman Rusia, pamaréntahan Siprus dialihaké marang Inggris; sacara kukum tetep dadi tanah Utsmaniyah. Pamukiman liya sing ucul ing tanggal sing padha: Nikosia, Famagusta, Kyrenia, Limassol, Larnaca (Tuzla), Paphos, Morphou, Akrotiri, Episkopi, Dhekelia; tegesé kabeh pulo.", "d1abea1c"]},
"OLAYLAR_EK:1881-07-02:0":{"b": ["Tesalia dipasrahaké marang Yunani", "ac614d24"], "d": ["Miturut keputusan Kongres Berlin, Tesalia lan tlatah sakiwa-tengené Arta dialihaké marang Yunani. Pamukiman liya sing ucul ing tanggal sing padha: Arta, Larissa, Trikala, Lamia. Kanthi pangalihan iki Volos, Kalambaka lan Karditsa (Tesalia) pindhah menyang Yunani.", "9fc28546"]},
"OLAYLAR_EK:1885-09-18:0":{"b": ["Rumelia Wétan gabung menyang Bulgaria", "ee43f137"], "d": ["Provinsi otonom Rumelia Wétan digandhèngaké karo Bulgaria liwat kudéta; Bab-i Ali nampa kasunyatan sing wis kedadéan. Kanthi manunggalé iki kabeh Rumelia Wétan (Stara Zagora, Pazardzhik, Sliven, Haskovo, Burgas, Aytos, Elhovo) pindhah menyang Kapangéranan Bulgaria.", "7fe3cc42"]},
"OLAYLAR_EK:1897-05-17:0":{"b": ["Perang Domokos", "9c6f29a5"], "d": ["Ing Perang Utsmaniyah-Yunani 1897, wadyabala menang kanthi mesthi ing Domokos; amarga tekanan diplomasi, wilayah sing diolèhaké tetep winates.", "aff8be0b"]},
"OLAYLAR_EK:1898-12-22:0":{"b": ["Otonomi kanggo Kréta", "2e764881"], "d": ["Senajan Perang Utsmaniyah-Yunani rampung kanthi kamenangan Utsmaniyah, Inggris, Rusia, Prancis lan Italia ing 18 Desember 1897 ngumumaké otonomi Kréta; pulo iku bakal dadi provinsi nétral lan otonom ing sangisoré kakuwasaan Utsmaniyah. Sawisé 6 November 1898 gendéra Turki ora dikibaraké manèh ing Kandia lan Kisamos; kanthi Pangéran George, putrané raja Yunani, wiwit tugas minangka komisaris luar biasa ing 22 Desember 1898, Kréta sejatiné metu saka pamaréntahan Utsmaniyah (sacara resmi misah ing 1913). Pamukiman liya sing ucul ing tanggal sing padha: Kandia (Kréta), Chania (Hanya).", "bc35b2a6"]},
"OLAYLAR_EK:1908-10-05:0":{"b": ["Kamardikan Bulgaria lan panggabungan Bosnia", "393feaa4"], "d": ["Ing kekisruhan Konstitusi, Bulgaria ngumumaké kamardikan, lan Austria-Hungaria nggabungaké Bosnia-Hercegovina. Kanthi pengumuman iki kabeh tanah Kapangéranan Bulgaria (Varna, Shumen, Ruse, Burgas, Sliven lan liya-liyané) dadi Krajan Bulgaria sing mardika.", "b7f0bb26"]},
"OLAYLAR_EK:1913-07-21:0":{"b": ["Edirne direbut manèh", "536e5599"], "d": ["Ing Perang Balkan II, wadyabala nyabrang Kali Maritsa lan ngrebut manèh Edirne tanpa perang. Panggonan liya sing digabungake ing tanggal sing padha: Kırklareli, Tekirdağ.", "e5420880"]},
"OLAYLAR_EK:1916-04-29:0":{"b": ["Kamenangan Kut al-Amara", "98b972bc"], "d": ["Komandan divisi Inggris sing dikepung ing Kut nyerah bebarengan karo 13 èwu prajurité — salah siji kamenangan Utsmaniyah paling gedhé ing Perang Donya I.", "20105888"]},
"OLAYLAR_EK:1917-03-11:0":{"b": ["Kelangan Baghdad", "2c18a816"], "d": ["Baghdad Utsmaniyah, sawisé 383 taun, pindhah menyang wadyabala Inggris. Pamukiman liya sing ucul ing tanggal sing padha: Karbala, Kızılrubat.", "880969bf"]},
"OLAYLAR_EK:1917-12-09:0":{"b": ["Kelangan Yerusalem", "94067617"], "d": ["Yerusalem sing wis 401 taun dadi duwèké Utsmaniyah dipasrahaké tanpa bisa dibéla.", "f2738a38"]},
"OLAYLAR_EK:1918-10-01:0":{"b": ["Kelangan Damaskus", "ed177b68"], "d": ["Kanthi ambruké front Palestina, Damaskus dikosongaké; pamaréntahan Utsmaniyah patang abad ing Suriah rampung. Pamukiman liya sing ucul ing tanggal sing padha: Hama, Homs.", "ff6aea3f"]},
"OLAYLAR_EK:1919-01-10:0":{"b": ["Penyerahan Madinah", "76b505f6"], "d": ["Pitung puluh loro dina sawisé gencatan senjata, perlawanané Fahreddin Pasya, 'Macan Ara-ara Samun', rampung amarga karsané sultan; pasukan Utsmaniyah pungkasan ing Hijaz nyelehaké gegaman.", "06b180d9"]},
"OLAYLAR_EK:1919-05-15:0":{"b": ["Pendhudhukan Izmir", "e32e5e77"], "d": ["Wadyabala Yunani ndharat ing Izmir; perlawanan sing diwiwiti karo pelor kapisan nyumet sumbu Perjuangan Nasional. Déné Aydın didhudhuki ing 27 Mei 1919 (artikel kapisah).", "4cc27e6b"]},
"OLAYLAR_EK:1920-03-16:0":{"b": ["Pendhudhukan resmi Istanbul", "a8e98ada"], "d": ["Pasukan Entente ndhudhuki Istanbul sacara resmi, Meclis-i Meb'usan dibubaraké; para wakil rakyat tumuju Ankara.", "09ed005b"]},
"OLAYLAR_ILIRYA0072:1779-01-01:0":{"b": ["Pasukan Saudi-Wahabi ngrebut kaamiran Ha'il — pamaréntahan ana ing tangané kulawarga Ibn Ali saka klan Abde", "2d29ceb9"], "d": ["Nalika pasukan Nagara Saudi Kapisan ngrebut kaamiran Ha'il, pamaréntahan kutha ana ing tangané kulawarga Ibn Ali saka klan Abde, suku Shammar. Kulawarga iki mréntah Ha'il nganti 1835, nalika Abdullah bin Rasyid ngrebut kaamiran; wangsa Rasyidiyah lagi diadegaké ing tanggal iku. Ing atlas, Ha'il nganti saiki katon tanpa pamilik nganti 1836, kamangka sumber nyebut jenengé amir kutha iku ing 1820.", "bc2aa4ea"]},
"OLAYLAR_ILIRYA0072:1806-01-01:0":{"b": ["Pulo-pulo Kvarner pindhah menyang Karajan Italia duwèké Napoleon, lan Teluk Kotor menyang pamaréntahan Rusia", "c5e411c8"], "d": ["Sawisé Prajanjian Pressburg, pulo-pulo Kvarner — béda karo Dalmatia — ora digabungaké langsung menyang Prancis, nanging menyang Karajan Italia duwèké Napoleon; lagi ing 1809 pulo-pulo iku mlebu Provinsi-Provinsi Iliria. Ing Teluk Kotor, pamaréntahan Austria rampung lan antarané 1806-1807 pamaréntahan Rusia diadegaké; teluk iku lagi pindhah menyang Prancis ing 1807. Bédan loro iki ora bisa dicukupi mung kanthi siji jendhéla 'Prancis' ing atlas.", "ec06d97d"]},
"OLAYLAR_ILIRYA0072:1806-02-01:0":{"b": ["Dalmatia pindhah menyang pamaréntahan Prancis — lumakuné Prajanjian Pressburg (Bratislava)", "00bfe4f6"], "d": ["Prajanjian Pressburg (Bratislava/Pressburg) tanggal 26 Desember 1805 meksa Austria nglepas Istria, Dalmatia lan kabèh pulo Adriatik. Prancis kanyatané nampa pamaréntahan ing Fèbruari 1806; Zadar tetep dadi pusat proveditor jenderal, lan antarané 1806-1810 jabatan iku dicekel Vicenzo Dandolo saka Venesia. Dalmatia gabung karo Provinsi-Provinsi Iliria sawisé Prajanjian Schönbrunn 1809. Pamaréntahan Austria kapisan sing lumaku wiwit 1797 kanthi mangkono rampung — ing atlas, mangsa iki nganti saiki katon minangka Austria tanpa pedhot.", "b8a55f1c"]},
"OLAYLAR_ILIRYA0072:1813-01-01:0":{"b": ["Austria ngrebut manèh Provinsi-Provinsi Iliria lan Dalmatia — pungkasané pamaréntahan Napoleon", "1b2ac942"], "d": ["Ing pungkasan 1813 pasukan Habsburg ngrebut manèh wilayah ing sisih kidul Kali Sava, lan organisasi tapel wates lawas diadegaké manèh; wadyabala Austria mlebu Istria ing Oktober 1813. Wiwit tanggal iku Karlovac dadi bagéan Karajan Iliria Austria. Mangsa pamaréntahan Prancis ing Dalmatia uga ditutup ing 1813. Yèn wilayah iku duwèké Austria disahaké kanthi resmi liwat keputusan Perdamaian Paris 1814 lan Kongres Wina 1815. Kanthi operasi iki Villach, Tarvis, Gorizia, Gradisca lan Pula (Provinsi-Provinsi Iliria) bali menyang Austria ing pungkasan 1813.", "bf1e49a8"]},
"OLAYLAR_MISIR1801:1801-05-14:0":{"b": ["Direbuté Damietta saka wong Prancis — bèntèng Lesbe diosongaké", "06b1e7b0"], "d": ["Sawijining pasukan saka tentarané wazir agung, dipimpin Ibrahim Pasya, dikirim menyang Damietta. Ésuké tanggal 14 Mèi, nalika serangan marang bèntèng Lesbe sing njaga Damietta wis disiyapaké, katon yèn bèntèng wis diosongaké wong Prancis lan garnisuné mundur; bèntèng cilik loro sing gumantung marang kono uga direbut. Damietta, sawisé Rosetta sing tiba ing April, dadi kutha muara Nil kapindho sing ucul saka kendhali Prancis.", "2eb4936c"]},
"OLAYLAR_MISIR1801:1801-06-27:0":{"b": ["Pamasrahan Kairo saka wong Prancis — nungkulé Belliard", "7a11bb5e"], "d": ["Nalika operasi bebarengan wadyabala Utsmaniyah lan Inggris menyang Mesir, komandan wadyabala Prancis ing Kairo, Jenderal Belliard, nandhatangani layang nungkul. Bebarengan karo Kairo, Suez sing direbut wong Prancis ing November 1798 uga ucul saka kendhali Prancis. Panutupé pendhudhukan bakal rampung rong sasi sabanjuré ing Iskandariyah, déné pangosongan saka nagara bakal lumaku nganti Oktober.", "e8dac3f4"]},
"OLAYLAR_MISIR1801:1801-08-31:0":{"b": ["Pamasrahan Iskandariyah saka wong Prancis — nungkulé Menou", "cd50663c"], "d": ["Panglima Agung Tentara Wétan, Jenderal Menou, tanggal 17 Agustus dikepung ing Iskandariyah; tanggal 21 Agustus wong Inggris ngrebut bèntèng Marabout cedhak kutha, lan tanggal 31 Agustus Menou nandhatangani layang nungkulé tentara. Baliné pasukan Prancis menyang Prancis diwiwiti tanggal 2 September. Kanthi mangkono pendhudhukan sing diwiwiti kanthi ndharat ing Iskandariyah ing Juni 1798 rampung ing kutha papan wiwitané.", "22e807c1"]},
"OLAYLAR_ORTADOGU_0919:1801-01-01:0":{"b": ["Suku-suku sakiwa-tengené Thaif mlebu pengaruh Wahabi — Turabah lan Khurma pedhot saka Kasyarifan Makkah", "d3b644be"], "d": ["Suku-suku sakiwa-tengené Thaif sing gumantung marang Syarif Makkah Ghalib ing 1801 mlebu pengaruh Wahabi; amir Diriyah masrahaké wong-wong iku marang pamaréntahané syekh badui Utsman al-Mudhayifi, ipéné lan uga mungsuhé Syarif. Oasis Turabah lan Khurma ing sisih wétan uga ing sabuk iki pindhah menyang pihak Saudi. Iki dadi pambuka anggoné wong Wahabi ngrebut Thaif ing Februari 1803 banjur Makkah.", "4fe448d3"]},
"OLAYLAR_ORTADOGU_0919:1816-01-01:0":{"b": ["Garnisun Mesir mundur saka Turabah, Bisyah lan Ranyah ing Hijaz kidul", "72b87aa1"], "d": ["Ing sasi-sasi sawisé Tusun Pasya gawé tentrem karo wong Wahabi lan bali menyang Kairo ing November 1815, ana kerusuhan ing Hijaz kidul; garnisuné Kavalalı Mehmed Ali Pasya kepeksa mundur saka Bisyah, Ranyah lan Turabah. Anggoné Ibrahim Pasya mangkat saka Kairo ing Agustus 1816 kanggo ekspedisi anyar dumadi sawisé pangunduran iki. Sapa sing mréntah Turabah nganti tibané Diriyah (1818) ora ditulis ing sumber.", "90e76189"]},
"OLAYLAR_ORTADOGU_0919:1819-08-13:0":{"b": ["Garnisun Mesir mundur saka Sulaimiyah ing Kharj lan tekan Manfuhah — Najd kidul tanpa pangarsa", "2743f70d"], "d": ["Pos Mesir sing dipasang Ibrahim Pasya ing Sulaimiyah ing Kharj sawisé rubuhé Diriyah, sadurungé mangkat miturut prentah mundur saka Pasya, ndhawuhi matèni syekh papat saka Dilam ing sawijining pésta lan banjur dikepung wong badui. Garnisun sing diluwari tekan Manfuhah tanggal 13 Agustus 1819 lan mlaku menyang Qasim diwiwiti. Ing Najd kidul ora ana manèh panguwasa puser; usahané kulawarga Saud ora ngasilaké apa-apa nganti 1824.", "fc53fbd1"]},
"OLAYLAR_P0043A:1456-01-01:0":{"b": ["Pirot bali menyang kakuwasan Utsmaniyah — sédané Đurađ Branković", "e37156d1"], "d": ["Pirot, sing ing 1443 direbut tentara Salib lan sawisé Prajanjèn Edirne-Szeged 1444 ditinggalaké Murad II marang wong Serbia, ing 1456 kanthi sédané Despot Serbia Đurađ Branković bali menyang kakuwasan Utsmaniyah. Ing taun sing padha lan amarga sebab sing padha, Niš uga mlebu kanthi pungkasan ing pamaréntahan Utsmaniyah; kanthi mangkono garis lembah Nišava sing mbukak dalan menyang Sofia dadi wutuh. Suwéné prajanjian ditandhatangani sepuluh taun, lan sawisé Varna (1444) sarta Kosovo II (1448), umuré Kadespotan mung suwéné uripé Branković.", "4b6ec617"]},
"OLAYLAR_P0043B:1514-03-20:0":{"b": ["Yavuz Sultan Selim mangkat saka Edirne kanggo Ekspedisi Chaldiran", "1f7921f7"], "d": ["Yavuz Sultan Selim, sing ninggalaké putrané, Pangéran Suleyman ing Manisa, minangka wakil ing Istanbul, mangkat saka Edirne kanggo ekspedisi nglawan Nagara Safawiyah. Tentara bakal ngliwati Anatolia lumantar garis Sivas-Erzincan-Erzurum lan ing pungkasan Agustus ngadhepi wadyabalané Syah Ismail ing Chaldiran.", "430f5ccc"]},
"OLAYLAR_P0043KIRIM:1526-01-01:0":{"b": ["Kizikermen (Gazi Kerman) lan pinggir tengen Dnieper mlebu kendhali langsung Utsmaniyah", "56a28224"], "d": ["Bèntèng Kizikermen lan pinggir tengen Dnieper, sing wiwit tengah abad kaping-15 dicekel Kakhanan Krimea, ing tanggal iki mlebu kendhali langsung Nagara Utsmaniyah; bèntèng iku owah dadi pos ngarep Utsmaniyah ing pucuk lor ara-ara. Béda karo tanah Kakhanan Krimea ing sakiwa-tengené Bakhchysarai lan Or Qapi, pamaréntahan Kizikermen langsung ana ing Utsmaniyah.", "a0eaba40"]},
"OLAYLAR_P0043KIRIM:1776-12-03:0":{"b": ["Prozorovsky ngenggoni Or Qapi — wadyabala Rusia tetep ing Perekop nganti aneksasi", "afdfe804"], "d": ["Nalika Jenderal Prozorovsky, sing mlaku kanggo munggahaké Şahin Giray ing dhampar Krimea, tekan garis Perekop, Devlet Giray, kaimakam lan wong Tatar wis mundur saka kutha; Prozorovsky ngenggoni bèntèng Or lan garis Perekop tanpa perang. Wong Rusia manggon ing Or Qapi lan tetep ing kono nganti aneksasi Krimea 1783.", "2c53b49b"]},
"OLAYLAR_P0043KIRIM:1791-07-26:0":{"b": ["Anapa dienggoni wong Rusia (pengepungan kaping telu)", "e6a7d6d5"], "d": ["Bèntèng Anapa, sing dibangun ing 1781 ing sangisoré pamaréntahan Ferah Ali Pasya, sasuwéné perang dikepung wong Rusia ping telu; ing pungkasan pengepungan kaping telu dienggoni tanggal 26 Juli 1791. Pendhudhukan iku sauntara — amarga liwat Prajanjèn Jassy (1792) wates lawas ing Kaukasus ditampa, bèntèng dibalèkaké marang Nagara Utsmaniyah.", "6f3b16fa"]},
"OLAYLAR_P0043KIRIM:1828-06-24:0":{"b": ["Osman Pasya masrahaké Anapa marang wong Rusia", "3ccbdd1d"], "d": ["Ing tahap wiwitan Perang Utsmaniyah-Rusia 1828-29 Anapa dikepung, lan wadyabala Utsmaniyah ing bèntèng sing dipimpin Osman Pasya tanggal 24 Juni 1828 nungkul marang wong Rusia. Sapisan iki nungkulé langgeng: liwat Prajanjèn Adrianopel sing ditandhatangani setaun sabanjuré (14 September 1829), Anapa lan Kaukasus resmi metu saka kakuwasan Utsmaniyah.", "d49b4078"]},
"OLAYLAR_P0044:1556-01-01:0":{"b": ["Turgut Reis dadi beylerbeyi Tripolitania — eyalet diambakaké ngétan menyang Tobruk lan Derna", "160fa43c"], "d": ["Sawisé panaklukan Tripoli ing 1551, Turgut Reis ing Jumadil Awal 963 (Maret 1556) teka ing Tripoli kanthi gelar beylerbeyi. Sasuwéné sangang taun dadi gubernur, dhèwèké ngupaya mbangun lan mbètèngi eyalet, nggawa pamaréntahan Utsmaniyah ngidul nganti Fezzan, lan ngambakaké wates ngétan kanthi ngrebut Tobruk lan Derna ing pesisir Barqah. Kanthi mangkono eyalet Tripolitania nyakup sabuk pesisir sing mbentang nganti wates Mesir.", "44cf4583"]},
"OLAYLAR_P0044:1556-01-01:1":{"b": ["Katsaran Moskow ngrebut Astrakhan — Volga Ngisor mlebu kendhali Rusia", "d02abd83"], "d": ["Katsaran Moskow, kanthi uga ngrebut Astrakhan ing 1556, miturut tembungé TDV nindakaké 'langkah sing bakal nuwuhaké akibat wigati banget ing tembé'; kanthi pendhudhukan Kakhanan Astrakhan, Volga Ngisor mlebu kendhali Rusia. Khan Krimea Devlet Giray sanajan péngin nyegah pendhudhukan iki, ora kasil. Wong Utsmaniyah nanggapi kedadéan iki liwat ekspedisi Astrakhan ing 1569; nanging amarga ora kasil ngendhalèni tlatah Volga Ngisor, padha masrahaké perjuangan nglawan Katsaran Moskow marang khan Krimea.", "7e08ba29"]},
"OLAYLAR_P0044:1556-07-16:0":{"b": ["Panaklukan Kostajnica lan Novi — rong bèntèng garis Una", "2093e452"], "d": ["Ing mangsa panas 1556 Kostajnica, sing dikepung Malkoç Bey, dipertahanaké kapitan Pankracije Lusthaller karo prajurit luwih saka 60; bèntèng dipasrahaké mung sadina sawisé pengepungan diwiwiti, tanggal 16 Juli, lan Lusthaller dituduh ngedol bèntèng. Ora suwé sabanjuré Novi uga direbut lan diobong; kanthi mangkono rong bèntèng paling wigati ing Una sapisan gebrag tiba ing tangané Utsmaniyah. Ing taun sing padha ing Wina diadegaké Dhéwan Perang Kraton (Hofkriegsrat) sing bakal ngatur pertahanan wates saka puser.", "b985cbdf"]},
"OLAYLAR_P0044:1574-01-01:0":{"b": ["Maku pindhah menyang Utsmaniyah — Mahmudi İvaz Bey ditugasi mbangun bèntèng", "5932ad38"], "d": ["Ing taun 1574 Nagara Utsmaniyah nugasi İvaz Bey, pangarsa suku Kurdi Mahmudi, supaya ngrebut Maku saka wong Iran lan mbangun bèntèng ing kono. Bèntèng ing pucuk wétan eyalet Van iki nduwé papan wigati ing prastawa-prastawa sing dumadi ing tlatah iku nalika jaman Utsmaniyah.", "bd663d7c"]},
"OLAYLAR_P0044:1840-01-01:0":{"b": ["Dhuwit kertas Utsmaniyah kapisan (kaime) diterbitaké", "d2e5e192"], "d": ["Ing taun-taun kapisan Tanzimat, nalika nggolèki asil kanggo keuangan, miturut usulé Arif Hikmet Bey, sing banjur bakal dadi syekhul Islam, ditampa panganggoné kaime, yaiku wujud sing dikembangaké saka sistem esham. Kaime kapisan, cacahé 160.000 lira (32.000 kantong), amarga butuh dhuwit kesusu, tanpa ngentèni dicithak, ditulis tangan lan diterbitaké nalika jaman Menteri Keuangan Saib Pasya, kamungkinan ing Juni 1840. Kertas-kertas sing kekuwatané kaya dhuwit kontan iki wektu edharé wolung taun, bungané 12,5% saben taun; ora ana jaminané, mung bungané sing dijamin saka asil béa Istanbul. Rakyat ora nampa kanthi becik dhuwit sing durung dikulinani iki, lan kaime tulisan tangan ora suwé dadi sasarané tukang malsu dhuwit.", "1f5f905c"]},
"OLAYLAR_P0047:1511-08-10:0":{"b": ["Malaka direbut wong Portugis", "e1556746"], "d": ["Malaka, sing diadegaké ing taun 1390-an, wis dadi pelabuhan paling ramé ing tlatah iku kanggo dagang segara antarané Cina, India lan Kulon sarta puser Kasultanan Malaka, lan uga puser utama sumebaré Islam menyang pulo-pulo sakiwa-tengené. Wong Portugis Afonso de Albuquerque tanggal 10 Agustus 1511 ngrebut kutha; kutha dijarah, masjid, pasaréan wangsa lan gedhong watu liyané dirubuhaké supaya watuné dienggo mbangun bèntèng. Malaka ing pamaréntahan Portugis ora bisa njaga kaunggulan dagangé sing lawas; para sudagar muslim madhep menyang pelabuhan Kasultanan Aceh ing Sumatra. Amarga serangané wong Portugis sing manggon ing Malaya marang Aceh, sultan Aceh Alauddin Riayat Syah ing 1565 njaluk pitulung marang Sultan Suleyman Sang Pembuat Undhang-undhang.", "bfb60150"]},
"OLAYLAR_P0048:1592-01-01:0":{"b": ["Panguwasa Luristan Shahverdi nyatakaké kasetyan marang Syah Abbas", "85791f94"], "d": ["Panguwasa Luristan Shahverdi, sing ing 1589 manut marang Utsmaniyah lan dadi bawahané beylerbeyi Baghdad, miturut caritané sejarawan Safawiyah Iskandar Beg Munshi ing taun 1000 (1591-92) kepeksa nyatakaké kasetyané marang makutha Safawiyah. Sumber sing padha nulis yèn ing taun-taun iki dhèwèké mrana-mrené antarané pihak loro, ngganggu gubernur-gubernur Hamadan lan nggrebeg Borujerd, lan ing taun 1002 (1593-94) Syah Abbas ngenggoni Khorramabad lan ngangkat gubernur ing kutha iku. Ensiklopedia Islam TDV malah nyèlèhaké gabungé Luristan, sing liwat Prajanjèn Istanbul 1590 digandhèngaké menyang pamaréntahan Utsmaniyah, kanthi wutuh menyang Safawiyah ing taun 1603. Tradhisi loro iku menèhi tanggal sing béda; artikel iki nuduhaké pranyatan kasetyan miturut tradhisi Safawiyah, artikel 1603 nuduhaké ilang sing pungkasan. Liwat artikel iki ing peta ora ana owah-owahan sing nduwé: Luristan nganti 1603 katon ing pihak Utsmaniyah.", "d15b2c77"]},
"OLAYLAR_P0048:1603-01-01:0":{"b": ["Pindhahé Luristan kanthi pungkasan menyang Safawiyah", "4c5cf67b"], "d": ["Luristan, sing liwat Prajanjèn Istanbul (Ferhad Pasya) 1590 digandhèngaké menyang pamaréntahan Utsmaniyah, ing 1603 digandhèngaké kanthi wutuh menyang Safawiyah déning Syah Abbas I. Déné sejarawan Safawiyah Iskandar Beg Munshi nulis yèn Khorramabad wis dienggoni Syah Abbas sadurungé, ing taun 1002 (1593-94), lan diangkat gubernur Safawiyah ing kutha iku; bédané antarané tradhisi loro iki durung rampung. Ing taun sing padha bèntèng Utsmaniyah Nahavand ing sisih loré Luristan uga tiba ing tangané Syah Abbas; gubernur Hamadan Hasan Khan ngratakaké bèntèng karo lemah.", "3e110da7"]},
"OLAYLAR_P0049:1303-09-01:0":{"b": ["Kompeni Katalan mlebu ngabdi marang Bizantium — wiwitan ekspedisi Anatolia", "6623e7db"], "d": ["Kakaisaran Bizantium, sing kélangan tanah ing Anatolia kulon ngadhepi kabèylikan-kabèylikan Turki, nyéwa pasukan Katalan watara 6.500 wong sing dipimpin Roger de Flor minangka prajurit bayaran. Miturut artikel TDV Bizans, pasukan iku ing 1303 teka mbiyantu kakaisaran lan setaun sabanjuré ngluwari Alaşehir sing dikepung Wangsa Germiyan. Nanging ora suwé kompeni iku wiwit njarah papan-papan sing diliwati; Bizantium nyabrangaké menyang Thrace lan ing 1305 ndhawuhi matèni Roger de Flor.", "87b98a94"]},
"OLAYLAR_P0049:1538-11-27:0":{"b": ["Panguwasa Hadramaut lan Shihr ngakoni panguwasa Utsmaniyah — ing dalan mulihé ekspedisi India Hadım Suleyman Pasya", "b5cb9363"], "d": ["Hadım Suleyman Pasya, sing bali saka pangepungan Diu, mampir ing Pelabuhan Shihr ing tanggal 27 November 1538; sawisé panguwasa Hadramaut lan Shihr nampa panguwasa Utsmaniyah, dhèwèké nerusaké lelungan menyang Aden. Hadramaut ditata minangka sanjak sing kalebu Yaman, nanging pamaréntahan ing tlatah iku tetep dicekel para pangarsa kabilah Katsiri. Status bawahan iki lumaku nganti Utsmaniyah mundur saka Yaman ing taun 1635.", "cff04bbb"]},
"OLAYLAR_P0049:1555-05-29:0":{"b": ["Kadipatèn Samegrelo (Dadiani) ditinggalaké ing wilayah pengaruh Utsmaniyah", "ea54e8ea"], "d": ["Liwat katemtuan Prajanjèn Amasya sing mbagi Géorgia, kadipatèn Dadiani (Mingrelia lan Svaneti) ing Géorgia Kulon, bebarengan karo Imereti lan Guria, ditinggalaké ing wilayah pengaruh Utsmaniyah. Ing peta, puser Samegrelo, Zugdidi, wiwit dina iki katon minangka kadipatèn sing gumantung marang Utsmaniyah; déné pranyatan manut sing nyata bakal teka ing 1578.", "1724aa10"]},
"OLAYLAR_P0049:1578-08-09:0":{"b": ["Kaatabegan Akhaltsikhe mlebu pamaréntahan Utsmaniyah — Altunkale, Khertvisi lan Akhalkalaki", "024bb326"], "d": ["Sanalika sawisé Lala Mustafa Pasya ngalahaké wadyabala ngarep Safawiyah ing Çıldır, tanah-tanah ing tangané para atabeg Géorgia uga pindhah menyang pamaréntahan Utsmaniyah. Dedis Imedi sing nyekel Altunkale sakiwa-tengené, bebarengan karo para putrané, nyatakaké manut; sanjakbey Ardahan ngrebut Çıldır lan Tümük, pasukan Utsmaniyah liyané ngrebut Khertvisi lan Akhalkalaki. Manuchar lan sedulure diparingi sanjak siji-siji, sisané nagara kaatabegan digandhèngaké menyang pamaréntahan langsung. Sawisé iku Akhaltsikhe bakal dadi puser eyalet Çıldır sing anyar diadegaké; Manuchar, sing teka ing Istanbul, mlebu Islam lan nampa jeneng Mustafa, tanggal 1 Juli 1579 bakal dadi pangarsa eyalet iki.", "23731679"]},
"OLAYLAR_P0049:1579-07-26:0":{"b": ["Kılıç Ali Pasya mbangun Bèntèng Faş (Poti) — pangkalan Utsmaniyah ing muara Rioni", "f729ba95"], "d": ["Kapudan pasya Kılıç Ali Pasya mbangun Bèntèng Faş ing tanggal 26 Juli 1579, ing panggonan kali Rioni (Phasis) mili menyang Segara Ireng.", "13606f9d"]},
"OLAYLAR_P0049:1587-01-01:0":{"b": ["Eyalet Gori diadegaké — pamaréntahan langsung Utsmaniyah ing sisih kulon Kartli", "9a7c8bc5"], "d": ["Ing taun 1578 para bangsawan Géorgia ing tlatah Gori lan Mukhrani wis tundhuk marang Utsmaniyah. Ing taun 1587 eyalet Gori diadegaké ing sisih kulon Kartli lan tlatah iku langsung diwengku pamaréntahan Utsmaniyah. Bèntèng Gori, sing ucul nalika pambrontakané Simon wong Géorgia, direbut manèh ing taun 1601; pamaréntahan Utsmaniyah rampung ing taun 1603 amarga ekspedisi Syah Abbas.", "7ee17c2b"]},
"OLAYLAR_P0049:1595-01-01:0":{"b": ["Panggrebegané Mihai Sang Wani marang bèntèng-bèntèng Donau — Ruse diobong, Brăila direbut, Silistra dijarah", "d0b83f6a"], "d": ["Voivoda Wallachia Mihai Sang Wani, sing melu Liga Suci, ing mangsa adhem 1594-95 nyerang bèntèng lan kutha pinggir Donau sing langsung ana ing pamaréntahan Utsmaniyah. Miturut artikel TDV Rusçuk, ing Februari 1595, sanajan ora bisa ngrebut bèntèng, dhèwèké ngrebut lan ngobong kutha. Miturut artikel İbrâil, dhèwèké ngrebut Brăila ing pinggir kiwa Donau lan kutha iku tetep ing tangané nganti 1601; artikel Murad III uga nulis yèn tentara Wallachia ngobong bèntèng Brăila lan maju nganti Silistra. Miturut cathetan tahrir sing disebut ing artikel Silistre, tentara Wallachia ing mangsa semi 1595 nyabrang Donau lan njarah Silistra; bèntèng kutha dirubuhaké lan suwé ora bisa dienggo. Ing mangsa panas sing padha Koca Sinan Pasya bakal mangkat ekspedisi nglawan Wallachia.", "c115852f"]},
"OLAYLAR_P0049:1603-01-01:0":{"b": ["Syah Abbas ngrebut manèh Tbilisi — pungkasané pamaréntahan Utsmaniyah ing Kartli lan Kakheti", "a6995ea8"], "d": ["Ing taun 1603 Syah Abbas I ngrebut manèh Tbilisi saka Utsmaniyah lan nglairaké Kartli minangka kakhanan; ing Kakheti uga diadegaké pamaréntahan Safawiyah. Mangkono rampunglah pamaréntahan Utsmaniyah ing Géorgia Wétan sing diwiwiti kanthi ekspedisi Lala Mustafa Pasya ing taun 1578; Tbilisi lagi bakal bali menyang tangané Utsmaniyah ing taun 1723.", "e37dcbfc"]},
"OLAYLAR_P0049:1640-01-01:0":{"b": ["Bèntèng Faş (Poti) dirubuhaké déning pasukan Imereti, Guria lan Mingrelia", "3c3d4ed7"], "d": ["Ing taun 1640 Bèntèng Faş diratakaké karo lemah déning pasukan Imereti sing uga diréwangi para pangéran Guria lan Mingrelia. Anané Utsmaniyah ing muara Rioni pedhot nganti bèntèng iku diadegaké manèh ing taun 1724.", "2bb31f58"]},
"OLAYLAR_P0049:1711-04-09:0":{"b": ["Ekspedisi Prut diwiwiti — ing Perang Utsmaniyah-Rusia 1710-1711 tentara metu saka Istanbul", "3161364b"], "d": ["Serangané Rusia marang tanah Utsmaniyah, anggoné Tsar Pyotr ora manut katemtuan Prajanjèn Istanbul 1700, lan pangajaké Khan Krimea Devlet Giray nuntun Ahmed III ngumumaké perang marang Rusia. Miturut artikel TDV Ahmed III, perang iki, sing banjur disebut Ekspedisi Prut, nyatané diwiwiti kanthi mangkaté tentara Utsmaniyah saka Istanbul tanggal 9 April 1711. Tentara sing dipimpin Baltacı Mehmed Pasya nyawiji karo wadyabala Krimea lan maju menyang Kali Prut; ekspedisi bakal rampung ing Juli kanthi kejepité tentara Rusia ing pinggir Prut.", "49618c54"]},
"OLAYLAR_P0049:1724-03-01:0":{"b": ["Pambangunan manèh Bèntèng Faş (Poti) diwiwiti", "0afbc4b0"], "d": ["Miturut putusan sing dijupuk ing tanggal 23 Désember 1723, pambangunan manèh Bèntèng Faş sing wis rubuh diwiwiti ing Maret 1724; pambangunané rampung ing taun 1729.", "e9e6b3d8"]},
"OLAYLAR_P0049:1724-05-06:0":{"b": ["Tlatah Khoy, Kapan lan Karadagh bali menyang pamaréntahan Utsmaniyah", "c52c94d1"], "d": ["Nalika ekspedisi Iran sing diwiwiti ing taun 1723, Khoy bebarengan karo tlatah Kapan lan Karadagh bali menyang pamaréntahan Utsmaniyah ing tanggal 6 Mèi 1724 lan kacathet ing cacah-jiwa tahrir Utsmaniyah ing taun 1728. Atlas iki nganggep Kotur, sing dumunung 40 km ing kidul-kuloné Khoy, uga pindhah saka Safawiyah menyang Utsmaniyah ing dina iku (rantai diwarisaké saka Khoy: Uluerler 2015, Turkish Studies 10/5, kc. 6; sumber ora ngemot dina sing mligi kanggo Kotur — kira-kira sing diterangaké kanthi mbukak).", "eb5141eb"]},
"OLAYLAR_P0049:1733-08-17:0":{"b": ["Nadir mlebu Shamakhi — punjeré Shirvan ucul saka Utsmaniyah", "778a4988"], "d": ["Shamakhi, sing miturut Prajanjèn Istanbul tanggal 24 Juni 1724 dadi bagéan Utsmaniyah bebarengan karo pérangan tengah Shirvan, dilebokaké Nadir ing tanggal 17 Agustus 1733. Sawisé iku pamaréntahan Utsmaniyah ing Kaukasus cepet ambyar; Ganja lan Tbilisi ucul ing taun 1735.", "4ab61a36"]},
"OLAYLAR_P0049:1787-07-27:0":{"b": ["Ultimatum marang duta Rusia — langkah pungkasan menyang Perang Utsmaniyah-Rusia 1787-1792", "cb389693"], "d": ["Ketegangan sing lumaku sawisé aneksasi Krimea menyang Rusia ing 1783 pedhot nalika kaweruhan yèn konsulat Rusia ing Iskandariyah ngojok-ojoki para bey Mamluk ing Mesir nglawan Utsmaniyah. Miturut artikel TDV Abdülhamid I, Reisülküttab Suleyman Feyzi Efendi tanggal 27 Juli 1787 menèhaké ultimatum pitung pasal marang duta Rusia ing Istanbul. Tanpa ngentèni wangsulané Rusia, putusan perang dijupuk lan sajroné sawetara minggu diumumaké; ancasé perang yaiku njupuk manèh Krimea.", "04debfa8"]},
"OLAYLAR_P0049:1809-11-27:0":{"b": ["Pasukan Rusia ngrebut Bèntèng Faş (Poti) — muara Rioni ucul", "c1241b5a"], "d": ["Nalika perang Utsmaniyah-Rusia 1806-1812, serangan Rusia ing Mèi 1809 gagal; nanging bèntèng iku dipasrahaké marang Rusia ing tanggal 27 November 1809.", "84e0aac2"]},
"OLAYLAR_P0049:1812-12-19:0":{"b": ["Miturut Prajanjèn Bukares, Bèntèng Faş (Poti) dibalèkaké marang Utsmaniyah", "6a3a8a0a"], "d": ["Miturut Prajanjèn Bukares 1812, Bèntèng Faş dipasrahaké marang Nagara Utsmaniyah ing tanggal 19 Désember 1812.", "d59bceb8"]},
"OLAYLAR_P0049:1828-06-26:0":{"b": ["Bèntèng Faş (Poti) kanggo kaping pindho tiba ing tangan Rusia — tetep dadi duwèké Rusia miturut Prajanjèn Edirne", "682d58f0"], "d": ["Ing wiwitan perang Utsmaniyah-Rusia 1828-1829, Bèntèng Faş dipasrahaké marang Rusia ing tanggal 26 Juni 1828. Liwat Prajanjèn Edirne tanggal 14 September 1829, Poti uga dipasrahaké marang Rusia bebarengan karo Akhaltsikhe, Akhalkalaki lan Anapa.", "364c160c"]},
"OLAYLAR_P0049:1915-07-25:0":{"b": ["Inggris ngenggoni Nasiriyah — front Efrat", "669b979e"], "d": ["Pasukan Inggris sing maju saka Basrah nurut Kali Efrat ngalahaké pasukan Utsmaniyah ing tanggal 24 Juli 1915 lan ésuké ngenggoni Nasiriyah. Basrah wis tiba ing November 1914; déné Nasiriyah isih ana ing tangan Utsmaniyah watara wolung sasi manèh.", "bd125229"]},
"OLAYLAR_P0049:1919-04-29:0":{"b": ["Pendhudhukan Italia ing Antalya", "328331da"], "d": ["Sawisé Gencatan Gaman Mudros, nalika nagara-nagara Sekutu manggon ing wilayah pendhudhukan ing Anatolia, Italia madhep menyang Anatolia kidul-kulon. Miturut artikel TDV Antalya, kutha lan sakiwa-tengené, kanthi adhedhasar katemtuan gencatan gaman, tanggal 29 April 1919 dienggoni wong Italia. Pendhudhukan iku bakal lumaku watara rong taun.", "41127caf"]},
"OLAYLAR_P0049:1920-02-11:0":{"b": ["Kamardikan Maraş — wong Prancis ngosongaké kutha", "a57d884e"], "d": ["Maraş, sing dienggoni wong Inggris tanggal 22 Februari 1919, liwat kasepakatan antarané nagara loro tanggal 29 Oktober 1919 dipasrahaké marang wong Prancis. Tumindaké wong Armenia ing njero pasukan Prancis lan diudhunaké gendéra Turki ing bèntèng ndadèkaké rakyat mbrontak; ing kutha ditata Perhimpunan Bela Hak lan Pasukan Nasional (Kuvâ-yi Milliye). Miturut artikel TDV Kahramanmaraş, ing pungkasan bentrokan wong Prancis tanggal 11 Februari 1920 ngosongaké kutha lan wiwit mundur menyang arah İslahiye, lan Maraş mardika tanggal 11-12 Februari. Ing 1925 kutha iku diparingi medhali Kamardikan.", "d3bff1ef"]},
"OLAYLAR_P0049:1920-04-11:0":{"b": ["Kamardikan Urfa — garnisun Prancis ninggalaké kutha", "c889488c"], "d": ["Ing Urfa, sing ing Maret 1919 dienggoni wong Inggris lan watara pitung sasi sabanjuré wong Prancis, rakyat tanggal 7 Februari 1920 mbrontak nglawan wadyabala pendhudhuk. Miturut artikel TDV Şanlıurfa, sawisé perang sing suwéné rong sasi, wong Prancis tanggal 10 April 1920 sarujuk ngosongaké Urfa kanthi syarat-syarat kasepakatan lan sadina sabanjuré metu saka kutha.", "88526a6f"]},
"OLAYLAR_P0049:1920-09-28:0":{"b": ["Operasi Garis Ngarep Wétan diwiwiti — Kâzım Karabekir nyerang Armenia", "151678df"], "d": ["Amarga Prajanjèn Sèvres ninggalaké Erzurum, Trabzon, Van, Bitlis lan Bingöl marang Armenia lan serangan Armenia ing tlatah iku mundhak, pamaréntah TBMM tanggal 20 September 1920 nglilani operasi. Miturut artikel TDV Kâzım Karabekir, Komandan Garis Ngarep Wétan Karabekir, kanthi prentah nyerang marang pasukané sing nyekel celah-celah gunung Soğanlı, miwiti operasi wétan tanggal 28 September. Sarıkamış, Göle lan Kağızman direbut; operasi bakal terus nganti diluwariné Kars sasasi sabanjuré.", "add8f41a"]},
"OLAYLAR_P0049:1920-10-30:0":{"b": ["Kamardikan Kars — Garis Ngarep Wétan mlebu Kars", "4e578071"], "d": ["Miturut artikel TDV Kars, Kâzım Karabekir Pasya tanggal 30 Oktober 1920 mlebu Kars, lan kutha diluwari saka pamaréntahan Armenia, sing kendhaliné ditinggal wong Inggris ing 1919. Artikel Karabekir negesaké yèn iki kamardikan kapindho Kars: kutha iku kapisan dijupuk saka wong Armenia ing April 1918. Garis Ngarep Wétan maju lan tanggal 7 November ngrebut Gyumri; perang rampung kanthi Prajanjèn Gyumri tanggal 3 Desember 1920.", "1841f6d3"]},
"OLAYLAR_P0049:1920-11-07:0":{"b": ["Direbuté Gyumri — Garis Ngarep Wétan maju menyang pedalaman Armenia", "cfddf791"], "d": ["Pasukané Kâzım Karabekir Pasya, sing nerusaké operasi sawisé diluwariné Kars, tanggal 7 November 1920 ngrebut Gyumri. Rembugan karo wong Armenia, sing sarujuk gencatan gaman, dianakaké ing Gyumri, lan perang rampung kanthi Prajanjèn Gyumri sing ditandhatangani tanggal 3 Desember 1920.", "4c34b9ce"]},
"OLAYLAR_P0049:1920-11-12:0":{"b": ["Direbute Iğdır", "6e952d2e"], "d": ["Limang dina sawisé ngrebut Gyumri, Front Wétan uga ngrebut Iğdır ing tanggal 12 November 1920. Iğdır dipasrahaké marang Turki liwat Prajanjèn Gyumri tanggal 3 Désember 1920.", "f96469bd"]},
"OLAYLAR_P0049:1921-02-09:0":{"b": ["Pungkasané pertahanan Antep — sawisé nglawan sepuluh sasi, kutha iku dipasrahaké marang Prancis", "e080af8b"], "d": ["Antep, sing dilebokaké wong Inggris ing tanggal 17 Désember 1918, wis dipasrahaké marang Prancis ing tanggal 5 November 1919; perlawanan kapisan ing garis Antep-Kilis dipimpin déning Şahin Bey. Miturut artikel Gaziantep ing TDV, warga kutha nglawan pasukan Prancis wiwit 1 April 1920 nganti 7 Fèbruari 1921; nalika perlawanan wis jebol, pasukan pertahanan mundur lan ing tanggal 9 Fèbruari Prancis nguwasani kutha. Telung dina sadurungé, ing tanggal 6 Fèbruari 1921, Majelis Agung Nasional (TBMM) wis maringi gelar gazi marang kutha sing tahan sepuluh sasi ngadhepi pendhudhukan iku. Sawisé Prajanjèn Ankara, Antep bakal dikosongaké ing tanggal 25 Désember 1921.", "086ee824"]},
"OLAYLAR_P0049:1921-02-23:0":{"b": ["Pambébasan Ardahan lan Artvin", "b9e50d5e"], "d": ["Sawisé Prajanjèn Gyumri, Front Wétan ngarah menyang pérangan Telung Sanjak (elviye-i selâse) sing isih ana ing tangané Géorgia. Miturut artikel Ardahan ing TDV, ing pungkasané perjuangan nglawan gerombolan Géorgia lan Arménia, ing tanggal 23 Fèbruari 1921 sanjak Ardahan uga dibébasaké bebarengan karo Artvin. Artikel Kâzım Karabekir nulis yèn kanthi gebrakan iki wilayah Telung Sanjak dijupuk manèh, kajaba kaza Çürüksu, Ajaria lan Batumi.", "1ee51ba4"]},
"OLAYLAR_P0049:1921-03-16:0":{"b": ["Prajanjèn Moskwa — TBMM lan Rusia Soviet netepaké tapel wates wétan", "78d46573"], "d": ["Ing tanggal 16 Maret 1921 Prajanjèn Moskwa ditandhatangani antarané pamaréntah TBMM lan Rusia Soviet. Miturut artikel Kars ing TDV, minangka asil aturan tapel wates saka prajanjèn iki lan Prajanjèn Kars tanggal 13 Oktober 1921, Kars tetep ana ing sajroning tapel wates nagara Turki sing anyar. Déné miturut artikel Akhaltsikhe, liwat prajanjèn iki Akhaltsikhe digandhèngaké karo vilayet Tbilisi ing Républik Sosialis Soviet Géorgia. Tapel wates wétan bakal dadi pesthi pitung sasi sabanjuré liwat Prajanjèn Kars sing ditandhatangani karo républik-républik Kaukasus Kidul. Liwat prajanjèn iki Batumi lan Ajaria (Khulo, Sarpi, Murvaneti, Makhalakauri) dipasrahaké marang Géorgia Soviet.", "7951b57b"]},
"OLAYLAR_P0049:1921-06-01:0":{"b": ["Wong Italia wiwit ngosongaké Antalya", "f7a4eaa7"], "d": ["Miturut artikel Antalya ing TDV, pendhudhukan Italia sing lumaku wiwit 29 April 1919 rampung nalika wong Italia wiwit ngosongaké kutha ing tanggal 1 Juni 1921. Mangkono Antalya lan sakiwa-tengené uwal saka pendhudhukan tanpa ngentèni asil militèr Perjuangan Nasional.", "ffd82d73"]},
"OLAYLAR_P0050:1527-01-01:0":{"b": ["Dhéwan Cetin — sawisé Mohács, para bangsawan Kroasia milih Ferdinand Habsburg dadi raja Kroasia", "55fc9d7e"], "d": ["Nalika tahta kothong amarga sédané raja Hungaria-Kroasia Lajos II ing Mohács, para bangsawan Kroasia nglumpuk ing Cetin ing tanggal 31 Désember 1526 lan ing dina taun anyar nglairaké adipati agung Austria Ferdinand dadi raja. Miturut tembungé TDV, wong Kroasia nindakaké pamilihan iki tanpa gumantung marang para bangsawan Hungaria; layang pamilihané adhedhasar alesan supaya ora pisah saka nagara Kristen ing ngadhepi serangan Utsmaniyah. Mangkono bèntèng-bèntèng Kroasia sing cedhak karo Bosnia Utsmaniyah kaiket ing makutha wangsa Habsburg; miturut TDV, nalika Habsburg wiwit nata tlatah tapel wates Kroasia ing taun 1530-an, punjer utama garis iki yaiku Bihac.", "5e7c69d8"]},
"OLAYLAR_P0050:1527-01-01:1":{"b": ["Pamaréntahan Utsmaniyah sing sedhéla ing Bihac — sawisé Mohács lan tibané Jajce", "fd4118fe"], "d": ["Sawisé kamenangan Mohács, Utsmaniyah ngrebut Jajce, punjeré tlatah panyangga Hungaria ing Bosnia, lan Banja Luka. Miturut artikel Bihac ing TDV, ing taun sawisé Mohács, sawisé Bèntèng Jajce direbut, Bihac sedhéla bali ana ing pamaréntahan Utsmaniyah. Sumber ora nyebutaké kapan lan kepriyé bèntèng iku ucul; TDV mung mratélakaké yèn ing taun 1530-an, nalika nata tlatah tapel wates Kroasia, Habsburg ndadèkaké Bihac sing ana ing tangan wong Kristen minangka punjer utama. Panaklukan Bihac sing langgeng bakal kelakon ing taun 1592 liwat ekspedisi Beylerbey Bosnia Hasan Pasya.", "3421f09a"]},
"OLAYLAR_P0050:1814-01-28:0":{"b": ["Pungkasané pamaréntahan Prancis ing Dubrovnik — pasukan Austria mlebu kutha mantan pambayar upeti Utsmaniyah iku", "38d42444"], "d": ["Miturut TDV, Prancis mungkasi Républik Dubrovnik, sing wiwit 1365 ana ing pangayoman Utsmaniyah, kanthi ngrebut kuthané ing tanggal 27 Mèi 1806. Ing mangsa adhem 1813-1814 warga kutha mbrontak nglawan Prancis; jéndral mayor Austria Milutinović, sing teka ing Gruž tanggal 3 Januari 1814 nggawa rong batalyon Kroasia, ngepung garnisun; sawisé dibom patang dina, garnisun Prancis ngirim utusan marang jéndral. Ing wayah esuk tanggal 28 Januari, pasukan Austria lan Inggris mlaku saka Gruž menyang kutha; ing tanggal 31 Januari pamaréntahan sauntara Austria wiwit lumaku ing tlatah iku. Panggabungan kutha iku menyang wilayah Austria dipesthèkaké ing Kongres Wina 1815.", "bb94e4af"]},
"OLAYLAR_P0050:1882-03-06:0":{"b": ["Pamakluman Karajan Serbia — kapangéranan mantan bawahan Utsmaniyah dadi karajan", "7d90e712"], "d": ["Kapangéranan Serbia, sing éntuk kamardikan ing taun 1878 lan ing taun sing padha uga ngrebut Niš sing ana ing tangan Utsmaniyah, diowahi dadi karajan ing jaman Milan Obrenović. Liwat pasal kapisan undhang-undhang sing diwetokaké ing Beograd, kapangéranan iku diwara-warakaké dadi Karajan Serbia lan Pangéran Milan dadi raja kanthi asma Milan I; undhang-undhang iku diterbitaké ing dina sing padha ing koran resmi Srpske novine. Mangkono Serbia, sing nganti 1878 dadi kapangéranan bawahan Utsmaniyah, ngadeg ing Balkan kanthi gelar karajan. Kanthi pamakluman iki kabèh wilayah Kapangéranan Serbia (Beograd, Niš, Jagodina, Vranje, Leskovac, Prokuplje, Pirot lan liya-liyané) dadi Karajan Serbia.", "a2849d70"]},
"OLAYLAR_P0050:1920-07-01:0":{"b": ["Pamaréntahan mandat sipil Inggris diadegaké ing Palestina — pungkasané pamaréntahan militèr ing wilayah sing dijupuk saka Utsmaniyah", "c0d7b76a"], "d": ["Kanthi direbuté Gaza lan banjur Yerusalem déning Jéndral Allenby ing taun 1917, panguwasa Utsmaniyah sing wis patang atus taun ing Palestina rampung, lan Yerusalem ana ing pamaréntahan militèr Inggris antarané 1917-1920. Konferensi San Remo 1920 maringaké mandat Palestina marang Inggris; wiwit Juli 1920 Inggris ngedegaké pamaréntahan mandat sipil ing tlatah iku lan wiwit mréntah nagara iku liwat komisaris agung. Pangarsa pamaréntahan sipil yaiku komisaris agung Herbert Samuel. Pambrontakan Arab lan padudon Yahudi-Arab sing diwiwiti ing taun sing padha bakal ninggal tilas ing sadawané jaman mandat. Kanthi kadadéan iki Tiberias (Palestina) pindhah menyang pamaréntahan mandat sipil Inggris.", "bc1ec892"]},
"OLAYLAR_P0050:1922-03-15:0":{"b": ["Karajan Mesir diwara-warakaké — Sultan Ahmad Fuad nampa gelar raja", "c6ad08d1"], "d": ["Ing tanggal 18 Désember 1914 Inggris kanthi sepihak mbusak hak kadaulatan Nagara Utsmaniyah tumrap Mesir lan njupuk nagara iku ing pangayomané. Amarga rembugan antarané Inggris lan Mesir sawisé perang ora ana asilé, ing tanggal 28 Fèbruari 1922 Inggris, manèh liwat pratélan sepihak, nglairaké Mesir dadi nagara mardika. Sultan Ahmad Fuad nampa gelar raja (malik) ing tanggal 15 Maret 1922 lan monarki diwara-warakaké ing Mesir. TDV nganggep kamardikan iki mung wujud lair; undhang-undhang dhasar tatanan karajan bakal wiwit lumaku ing tanggal 19 April 1923.", "f9b00023"]},
"OLAYLAR_P0051:1480-01-01:0":{"b": ["Bèntèng Hacıbey (Kochubey) ucul saka tangan Lituania", "382b51e3"], "d": ["Pelabuhan Kochubey ing pesisir lor-kulon Segara Ireng dikuwataké ing wiwitan abad kaping 15 déning adipati agung Lituania Vytautas. Ing taun 1480 bèntèng iku ucul saka tangan Lituania lan olèh jeneng Hacıbey. Ing pungkasan abad kaping 15 pesisir iku mlebu ing pangawasan Kakhanan Krimea sing dadi bawahan Utsmaniyah; déné panggabungan tlatah iku langsung menyang tatanan pamaréntahan Utsmaniyah kelakon ing taun 1538.", "cea3442c"]},
"OLAYLAR_P0051:1570-01-01:0":{"b": ["Layang gramota Ivan IV marang wong Kazak Don — cathetan kapisan sing bisa dipercaya bab Wadya Kazak Don", "16c0732e"], "d": ["Katrangan bab anané wong Kazak ing Kali Don diwiwiti saka tengah abad kaping 16. Miturut ènsiklopédhi militèr Rusia, senioritas Wadya Kazak Don diétung wiwit 1570: ing taun iku Tsar Ivan IV ngirim layang gramota marang wong Kazak sing manggon ing Donets Lor, njaluk supaya mbiyantu Ivan Novosiltsev sing diutus dadi duta marang sultan Utsmaniyah liwat Azov, lan janji bakal maringi ganjaran. Iki cathetan kapisan sing bisa dipercaya bab pangabdiné wong Kazak Don marang nagara Moskwa. Punjer utama wong Kazak wiwitané Razdory Ndhuwur, banjur Cherkassk.", "3ce37828"]},
"OLAYLAR_P0051:1585-01-01:0":{"b": ["Moskwa ngedegaké garnisun ngarep ing Voronezh kanggo ngadhepi stepa", "89c941fe"], "d": ["Ing pungkasan abad kaping 16, tlatah sing saiki Sloboda Ukraina lan lembah ndhuwur Kali Don minangka stepa alas sing sepi, sing diliwati wong Tatar nalika nyerang Moskwa. Pamaréntah Moskwa ngedegaké sawetara garnisun ngarep ing stepa iku; Voronezh, salah sijiné, diadegaké ing taun 1585. Ing puluhan taun sabanjuré, bèntèng iku bebarengan karo Belgorod lan Kursk dadi sawetara mata rantai kapisan ing garis pertahanan kidul Moskwa.", "ceb11b6b"]},
"OLAYLAR_P0051:1596-01-01:0":{"b": ["Moskwa ngedegaké Belgorod, Oskol lan Kursk minangka garnisun ngarep ing stepa", "4ff3e225"], "d": ["Pamaréntah Moskwa mindhah tapel wates kidulé luwih maju kanggo ngadhepi serangan Krimea, lan ing taun 1596 ngedegaké Belgorod, Oskol lan Kursk minangka panggonan garnisun ing stepa alas. Wiwit tanggal iku Belgorod dadi kutha bèntèng lan dadi punjeré garis pertahanan Belgorod dawané 300 kilomèter sing bakal mbentang ing abad sabanjuré.", "50cb899c"]},
"OLAYLAR_P0052:1884-01-01:0":{"b": ["Sanjak Siirt dipindhah saka Diyarbekir menyang vilayet Bitlis — kaza Eruh lan désa Şırnak uga digandhèngaké karo Bitlis", "3922d040"], "d": ["Nalika sawisé Tanzimat sistem eyalet diganti dadi sistem vilayet, sanjak Siirt sing isih kagandhèng karo vilayet Diyarbekir dipindhah menyang vilayet Bitlis ing taun 1884. Miturut artikel Şırnak ing TDV, lemah panggonané Şırnak saiki kanthi mangkono uga mlebu kaza Eruh sing kalebu sanjak Siirt ing vilayet Bitlis. Nalika iku Şırnak désa cilik ing kaza Eruh; jenengé katon ing cathetan nyedhaki pungkasan abad kaping XIX, déné dadiné punjer kaza lagi ing taun-taun wiwitan Républik. Wilayah iki gabung karo Utsmaniyah ing taun 1514 sawisé Ekspedisi Chaldiran lan diprentah ing sajroning sanjak Siirt, eyalet Diyarbekir.", "1539b089"]},
"OLAYLAR_P0053:1624-01-01:0":{"b": ["Mosul lan Kirkuk tiba ing tangan Safawiyah — sawisé tibané Baghdad", "86e176c8"], "d": ["Syah Abbas, sing nguwasani Baghdad ing pungkasan prastawa sing diwiwiti saka pambrontakané Bekir Subaşı, ngirim panglimané Qarachaqay Khan lan pasukané menyang Mosul lan Kirkuk. Gubernur Mosul Çerkez Ahmed Pasya mung bisa mbélani kutha sawetara dina; kaya Kirkuk, Mosul uga mlebu ing panguwasa Iran lan Qasim Khan didadèkaké gubernur. Nalika Sipahi Küçük Ahmed, sing mimpin pasukan ngarepé Hâfız Ahmed Pasya, katon ing ngarep Mosul, Qasim Khan ninggal kutha lan mundur menyang Baghdad, nanging amarga gerakan walesané Syah Abbas, ing taun 1624 Mosul tiba manèh ing tangan Safawiyah.", "81474bd6"]},
"OLAYLAR_P0053:1625-01-01:0":{"b": ["Mosul dibébasaké saka Safawiyah — ekspedisi Baghdad Hâfız Ahmed Pasya", "1f9ca4a1"], "d": ["Murad IV ngirim wadyabala ing sangisoré Wazir Agung Hâfız Ahmed Pasya menyang Baghdad. Nalika wadyabala ana ing sakiwa-tengené Diyarbekir, pasukan ngarepé Beylerbey Karaman Çerkez Hasan ngoyak para pendhukung Iran sing nglumpuk ing Altınköprü nganti tekan Kirkuk lan nguwasani tlatah iku kalebu Kirkuk; wektu iki uga Safawiyah ora bisa nyekel Mosul suwé. Ing wiwitan September Hâfız Ahmed Pasya tekan Mosul dhisik, banjur Kirkuk, lan ing tanggal 13 November 1625 ngepung Baghdad; pangepungan ora ana asilé lan Baghdad tetep ing tangan Safawiyah. Déné artikel Kirkuk ing TDV nyambungaké direbuté manèh kutha iku saka Safawiyah karo taun 1630 lan Hüsrev Pasya.", "ad32f3ae"]},
"OLAYLAR_P0053:1630-03-16:0":{"b": ["Hüsrev Pasya ngedegaké manèh Bèntèng Gülanber ing Shahrizor — beylerbeylik Shahrizor", "9511853c"], "d": ["Wazir Agung Hüsrev Pasya, sing budhal ing ekspedisi Baghdad, sawisé suwé kandheg ing Mosul amarga udan deres, banjur tumuju Shahrizor. Pambangunan manèh Bèntèng Gülanber, sing nalika panyerbuan Syah Abbas dirubuhaké miturut dhawuhé, diwiwiti; Shahrizor didadèkaké manèh punjer beylerbeylik lan Arnavud Mustafa Pasya ditinggal ing bèntèng minangka beylerbey. Hüsrev Pasya nundhukaké kabilah-kabilah ing tlatah iku, ngrebut Bèntèng Mihriban, lan ing tanggal 5 Mèi 1630 ing cedhak bèntèng iku nyebabaké karugèn abot marang wadyabala Safawiyah.", "ff2c7cea"]},
"OLAYLAR_P0055:1369-01-01:0":{"b": ["Timurtaş Bey ngrebut Elhovo lan Yambol ing lembah Tundzha", "2c2aebea"], "d": ["Nalika gerakan Murad I nglawan Bulgaria lan Bizantium, Kara Timurtaş Bey dikirim menyang lembah Tundzha; dhèwèké ngrebut Kızılcaağaç Yenicesi (Elhovo) lan Yambol banjur bali menyang Edirne nggawa rampasan perang akèh.", "e2ca7962"]},
"OLAYLAR_P0055:1371-09-26:0":{"b": ["Kapangéranan Dejanović (Kostadin-ili) dadi vasal Utsmaniyah", "54b8dd6c"], "d": ["Nalika nagara Serbia pecah amarga kalah ing Maritsa (Chirmen), sadulur Jovan lan Konstantin Dejanović ngedegaké kapangérananè dhéwé sing punjeré ing Velbujd (sabanjuré jenengé Kyustendil) lan nyakup tlatah Štip, Strumica, Dojran lan Veles. Sawisé Jovan ora suwé banjur séda, Konstantin ngakoni panguwasa Murad I lan dadi vasal Utsmaniyah; kanthi iketan iki kapangéranan urip setengah mardika. Nalika Konstantin gugur ing barisané Bayezid Yildirim ing Rovine taun 1395, nagarané mlebu pamaréntahan Utsmaniyah tanpa perang lan dadi sanjak kanthi jeneng Kostadin-ili.", "25fd68b1"]},
"OLAYLAR_P0055:1412-01-01:0":{"b": ["Despot Serbia Stefan Lazarević ngrebut Pirot", "87e1ecb3"], "d": ["Nalika Mangsa Interregnum, wektu perjuangan antarané Musa Celebi sing nguwasani Rumelia lan sadulure Mehmed Celebi isih lumaku, Despot Serbia Stefan Lazarević ngrebut bèntèng Pirot ing dalan antarané Niš lan Sofia lan nahan serangané Musa Celebi. Ing taun sabanjuré, sawisé sédané Musa, Mehmed Celebi sacara resmi masrahaké bèntèng iku marang vasalé, Stefan; Utsmaniyah lagi ngrebut manèh Pirot ing taun 1428 sawisé sédané Lazarević.", "f50a8066"]},
"OLAYLAR_P0055:1538-01-01:0":{"b": ["Herceg Novi (Castelnuovo) direbut Andrea Doria", "a8276ff1"], "d": ["Andrea Doria, panglima armada sekutu sing gabung nglawan Utsmaniyah, ngrebut bèntèng Herceg Novi (Castelnuovo) ing pesisir Adriatik, sisih kidul Dalmatia. Ing taun sing padha wong Venesia ing Dalmatia uga njupuk sawetara kutha cilik sing ana ing tangan Utsmaniyah, lan pasukan Utsmaniyah males kanthi bèntèng liya. Bèntèng iku direbut manèh setaun sabanjuré; amarga kadaulatan Utsmaniyah sacara hukum tetep lumaku, mangsa sela iki dituduhaké ing peta nganggo lapisan pendhudhukan sing diarsir.", "a9462728"]},
"OLAYLAR_P0055:1539-08-10:0":{"b": ["Herceg Novi (Castelnuovo) direbut manèh déning Barbaros Hayreddin Pasya", "1e5b49ae"], "d": ["Sawisé kamenangan Preveza, Utsmaniyah sing uga unggul ing Segara Tengah pérangan tengah tumuju bèntèng Nova (Castelnuovo) ing pesisir Adriatik sing setaun sadurungé direbut Andrea Doria. Ing pungkasan gerakan sing ditindakaké bebarengan déning Barbaros Hayreddin Pasya lan Bey Bosnia Gazi Hüsrev Bey, bèntèng direbut manèh lan pendhudhukan rampung.", "29e2c28b"]},
"OLAYLAR_P0055:1798-12-25:0":{"b": ["Ekspedisi Desaix ing Mesir Ndhuwur — divisi Prancis tekan Minya, Asyut lan Girga", "8ff8e4fe"], "d": ["Nalika Napoleon lenggah ing Kairo, divisiné Jéndral Desaix ngoyak pasukan Mamluk lan maju mangidul ing lembah Nil: tekan Minya ing tanggal 21 Désember 1798, Asyut ing dina Natal, lan Girga ing tanggal 29 Désember. Kanthi laku iki, sing tekan Aswan ing Fèbruari 1799, lembah antarané Kairo lan Aswan mlebu pangawasan Prancis.", "96ddd684"]},
"OLAYLAR_P0055:1799-02-18:0":{"b": ["Napoleon ngenggoni Arish — wiwitané ekspedisi Suriah", "69dc52ce"], "d": ["Wadyabala Prancis sing wis ngenggoni Mesir ngrebut Arish ing pesisir Sinai nalika mlaku menyang Suriah.", "8feb359c"]},
"OLAYLAR_P0055:1799-12-28:0":{"b": ["Arish direbut manèh saka Prancis", "c25e48a7"], "d": ["Arish, sing dienggoni Napoleon ing Fèbruari 1799, direbut manèh ing pungkasan Désember taun sing padha déning wadyabalané Wazir Agung Yusuf Ziya Pasya.", "3bde687a"]},
"OLAYLAR_P0056:1739-08-28:0":{"b": ["Kekalahan Stavuchany lan pasrahé Khotin marang Rusia (Perang Utsmaniyah-Rusia 1736-1739)", "657d82d2"], "d": ["Ing ekspedisi 1739, wadyabala utama Rusia ing sangisoré Marsekal Münnich liwat lemah Polandia mlebu Moldavia, lan ing Stavuchany cedhak Khotin ngalahaké wadyabala Serasker Veli Pasya kanthi abot. Ora suwé sawisé perang iku bèntèng Khotin pasrah marang Rusia lan pasukan Rusia mlebu Jassy ing wiwitan September. Nanging amarga Austria gawé tentrem dhéwé, perang rampung liwat Prajanjèn Beograd sing ditandhatangani ing sasi sing padha.", "2e7457b9"]},
"OLAYLAR_P0056:1769-01-01:0":{"b": ["Wadyabala Rusia nyabrang Dniester lan mlebu Moldavia (Perang Utsmaniyah-Rusia 1768-1774)", "938bd834"], "d": ["Watara nem sasi sawisé pamakluman perang, wadyabala utama Rusia ing sangisoré Pangéran Golitsyn nglumpuk ing Podolia. Sawisé panyuwuné metropolitan Moldavia Dositei supaya Moldavia dilebokaké ing pangayoman Rusia, Golitsyn nyabrang Dniester lan sadurungé mlaku menyang Jassy nyoba ngrebut Khotin. Upaya kapisan iki gagal, lan wadyabala bali menyang Podolia amarga kangèlan bahan pangan; Khotin lagi tiba ing September 1769.", "df52a8ec"]},
"OLAYLAR_P0056:1788-01-01:0":{"b": ["Wadyabala Ukraina Rusia nyabrang Dniester ing Mogilev lan mlebu Moldavia (Perang Utsmaniyah-Rusia 1787-1792)", "822c7361"], "d": ["Ing perang sing diwiwiti kanthi pamakluman perang Utsmaniyah ing taun 1787, Rusia mbentuk rong wadyabala: wadyabalané Potemkin ngepung Özi, déné wadyabala Ukrainané Rumyantsev, antarané Dniester lan Bug, kudu ngancam Bender lan njaga sesambungan karo Austria. Rumyantsev misahaké siji pérangan kanggo ngréwangi wong Austria sing ngepung Khotin, lan karo pasukan utamané nyabrang Dniester ing Mogilev banjur mlebu Moldavia. Mangkono diwiwiti pérangan Moldavia saka gerakan Rusia sing bakal mbentang tekan Izmail lan Donau.", "7c701213"]},
"OLAYLAR_P0056:1806-11-23:0":{"b": ["Wadyabala Rusia nyabrang Dniester tanpa pamakluman perang lan wiwit ngenggoni Kapangéranan Loro (Wallachia lan Moldavia) (Perang Utsmaniyah-Rusia 1806-1812)", "2094a4d9"], "d": ["Ing Oktober 1806 Jéndral Michelson didhawuhi ngenggoni Moldavia lan Wallachia; perang durung diwara-warakaké sacara resmi. Pasukan Rusia wiwit nyabrang Dniester lan para komandan bèntèng Khotin, Bender, Akkerman lan Kilia masrahaké bèntèngé tanpa perang. Mung pangayom Izmail sing ora tundhuk marang pambujuké Rusia. Pamakluman perang Bab-i Ali teka sawisé pendhudhukan iki.", "c770c2b4"]},
"OLAYLAR_P0056:1806-11-30:0":{"b": ["Akkerman direbut wong Rusia (1806)", "25aed8d6"], "d": ["Seminggu sawisé wadyabala Rusia nyabrang Dniester tanpa pamakluman perang, Akkerman direbut pasukané Pangéran Cantacuzino; wong Tatar ing kutha iku lunga ninggal kutha. Liwat Prajanjèn Bukares 1812, Akkerman bebarengan karo Bessarabia dipasrahaké marang Rusia.", "1e7e3f9e"]},
"OLAYLAR_P0056:1806-12-25:0":{"b": ["Miloradovich mlebu Bukares — pendhudhukan Rusia ing Wallachia", "62e4a8e1"], "d": ["Nalika wadyabala Rusia mlebu Moldavia, pangayom Rusçuk Mustafa Pasya ngirim sawijining pasukan menyang Bukares lan pasukan iku nyekel kutha. Detasemèn Jéndral Miloradovich nundhung wong-wong iku saka kutha; pasukan Utsmaniyah mundur menyang Giurgiu. Wiwit tanggal iku nganti Prajanjèn Bukares 1812, Bukares tetep dienggoni Rusia.", "217aa20b"]},
"OLAYLAR_P0056:1810-06-10:0":{"b": ["Silistra pasrah marang Rusia", "d687d04b"], "d": ["Silistra, sing tahan ngadhepi pangepungan Bagration ing mangsa gugur 1809, dikepung manèh ing ekspedisi 1810 miturut dhawuhé panglima agung Kamensky. Pagawéan pangepungan sing diwiwiti ing pungkasan Mèi lumaku sawetara dina, lan bèntèng pasrah kanthi sarat garnisuné kena metu kanthi bébas. Ing dina-dina iku uga Bazargic direbut kanthi serbuan lan Razgrad tiba. Rusia nyekel Silistra setaun; ing mangsa semi 1811 Kutuzov ngledhakaké témbok-témboké lan ninggal bèntèng.", "56cdb224"]},
"OLAYLAR_P0056:1810-10-01:0":{"b": ["Nikopolis lan Turnu pasrah marang Rusia tanpa nglawan", "e297a862"], "d": ["Sawisé Rusçuk lan Giurgiu pasrah, panglima agung Kamensky mlaku mangulon nurut kali kanggo ngrebut bèntèng-bèntèng Donau nganti tekan tapel wates Serbia. Nikopolis lan Turnu ing pinggir sabrangé pasrah tanpa nglawan; detasemèn Rusia ngrebut Pleven, Lovech lan Sevlievo lan ngrubuhaké bèntèng pertahanané. Rusia nyekel Nikopolis nem sasi lan ing April 1811 ninggal bèntèng sawisé diledhakaké.", "f77715d7"]},
"OLAYLAR_P0056:1811-07-04:0":{"b": ["Perang Rusçuk lan Kutuzov ngrusak Rusçuk banjur mundur menyang pinggir kiwa Donau", "6af4bf85"], "d": ["Ing wiwitan Juni, wazir agung sing metu saka Shumen nyerang wadyabala Rusia ing ngarep Rusçuk, kalah, lan mundur menyang posisi pertahanané sing dikuwataké ing sisih kidul. Sanajan menang ing perang iki, Kutuzov nganggep mbebayani yèn tetep ana ing Rusçuk; dhèwèké dhawuh ngrubuhaké bèntèng pertahanan lan nyabrangaké kabèh pasukané menyang pinggir kiwa Donau. Wazir agung ngrebut manèh Rusçuk sing wis dikosongaké. Mangkono cekelané Rusia ing kutha sing ditampa pasrahé déning Kamensky ing tanggal 26 September 1810 sawisé pangepungan getih-getihan lumaku sangang sasi. Miturut cathetan TDV, sadurungé lunga Kutuzov dhawuh ngledhakaké bèntèng pertahanan ing sakiwa-tengené kutha lan bèntèng abad pertengahan; ing kobongan sing kedadéan, rolas saka telung puluh wolu mesjid sing ana ing kutha ing taun 1810 lan loro saka wolung langgar rubuh babar pisan. Ing mangsa gugur taun sing padha, panyabrangan Donau déning wadyabala Utsmaniyah bakal dipungkasi karo pangepungan Slobozia.", "3b247b6b"]},
"OLAYLAR_P0056:1828-05-07:0":{"b": ["Korps Infantri VI Rusia nyabrang Prut lan mlebu Kapangéranan Loro (Perang Utsmaniyah-Rusia 1828-1829)", "9d9aaaad"], "d": ["Sawisé Rusia nglairaké perang, wadyabalané Marsekal Wittgenstein wiwit obah. Korps Infantri VI nyabrang Prut lan mlebu Moldavia lan Wallachia; pasukan ngarepé ing sangisoré Jéndral Geismar tumuju Wallachia Cilik. Sawetara dina sabanjuré Korps VII ngepung Brăila; déné Korps III cecawis nyabrang Donau antarané Izmail lan Reni. Kapangéranan Loro bakal tetep dienggoni Rusia nganti 1834.", "cba5d549"]},
"OLAYLAR_P0056:1829-06-30:0":{"b": ["Silistra pasrah marang Diebitsch — pendhudhukan Rusia sing lumaku nganti 1836", "55e28ab1"], "d": ["Ing wiwitan ekspedisi 1829, panglima agung Rusia sing anyar, Diebitsch, milih Silistra dadi sasaran kapisan. Garnisun nglawan kanthi kenceng pagawéan pangepungan sing dipimpin Jéndral Schilder; Diebitsch ninggal sapérangan pasukané ing pangepungan lan mlaku menyang buriné wazir agung. Pangepungan lumaku terus lan bèntèng pasrah. Sawisé perang rampung, Rusia isih nyekel Silistra nganti 1836.", "4c1a9e8e"]},
"OLAYLAR_P0056:1836-01-01:0":{"b": ["Rusia ngosongaké Silistra", "4fe2afaf"], "d": ["Sawisé Prajanjèn Edirne 1829, Rusia ora ngosongaké Silistra lan nyekel bèntèng iku nganti 1836. Sawisé prajurit Rusia mundur, gubernur Selim Pasya ngyasa mesjid gedhé kubah siji ing satengahé kutha sing separo wis rubuh.", "39444f60"]},
"OLAYLAR_P0056:1853-07-03:0":{"b": ["Wadyabala Rusia nyabrang Prut lan wiwit ngenggoni Kapangéranan Loro (Wallachia-Moldavia) — dalan tumuju Perang Krimea", "77862041"], "d": ["Nalika ing padudon bab panggonan suci ing Yerusalem panjaluké Menshikov ditolak Bab-i Ali, Tsar Nikolai I dhawuh ngenggoni kapangéranan Donau sing kagandhèng karo Utsmaniyah 'minangka tanggungan nganti Turki nyembadani panjaluk kita sing adil'. Pasukan ngarepé wadyabala ing sangisoré Pangéran Gorchakov nyabrang Prut lan rolas dina sabanjuré mlebu Bukares; ing buriné, pasukan utama sumebar ing kapangéranan-kapangéranan iku ing telung barisan. Pendhudhukan tanpa pamakluman perang iki nuwuhaké krisis diplomatik ing Éropah lan ing Oktober 1853 njalari Utsmaniyah nglairaké perang; Rusia lagi ngosongaké kapangéranan iku ing mangsa panas 1854 amarga dipeksa Austria.", "04443242"]},
"OLAYLAR_P0057:1442-01-16:0":{"b": ["Kaum Musya'sya' manggon ing Hawiza — pamaréntahan Musya'sya' ing Khuzistan diwiwiti", "674d0173"], "d": ["Muhammad bin Falah, sing njedhul kanthi ngaku dadi Mahdi, sawisé olèh panggonan ing antarané kabilah-kabilah Ma'adi, ing taun sabanjuré kasil manggon ing Hawiza sing ana ing pangawasané wangsa Timurid. Kutha iku dadi punjeré wangsa Musya'sya' sing bakal mréntah ing Khuzistan.", "53937c8f"]},
"OLAYLAR_P0057:1508-05-02:0":{"b": ["Syah Ismail nggandhèngaké Hawiza — kaum Musya'sya' dadi gubernur bawahan Safawiyah", "7e245f4d"], "d": ["Syah Ismail dhawuh matèni sawetara anggota wangsa Musya'sya' sing didakwa zindik, lan nggandhèngaké tlatah Hawiza langsung karo pamaréntahané. Sawisé iku para pangarsa Musya'sya' nerusaké anané minangka gubernur bawahan Safawiyah.", "ee776160"]},
"OLAYLAR_P0057:1534-01-01:0":{"b": ["Bèntèng Pasinler, Şüregel lan Oltu direbut saka Safawiyah — antarané Erzurum lan Kars", "68f297aa"], "d": ["Nalika Ekspedisi Irak Loro (Irakeyn) Sultan Sulaiman Sang Pembuat Undhang-undhang, bèntèng Pasinler, Şüregel lan Oltu antarané Erzurum lan Kars direbut saka Safawiyah.", "06909003"]},
"OLAYLAR_P0057:1557-04-02:0":{"b": ["Özdemir Pasya ngrebut pelabuhan Massawa", "4cc1d4ad"], "d": ["Özdemir Pasya, beylerbey Eyalet Habeş, sawisé ngrebut kapuloan Dahlak banjur ngrebut kutha Massawa ing pesisir sabrang ing tanggal 2 April 1557; sawisé iku Arkiko uga mlebu pamaréntahan Utsmaniyah. Mangkono pelabuhan utama Abisinia sing mbukak menyang Segara Abang tiba ing tangané Utsmaniyah.", "7c5e89f0"]},
"OLAYLAR_P0057:1793-01-31:0":{"b": ["Kakontan Nice digabungaké karo Prancis", "a140cab2"], "d": ["Sawisé Savoy gabung ing November 1792, Konvènsi Nasional Prancis ing tanggal 31 Januari 1793 ngesahaké panggabungan Kakontan Nice, duwèké Karajan Sardinia, karo Prancis; tlatah iku dadi departemèn Alpes-Maritimes. Sawisé Napoleon kalah, Nice bali menyang Sardinia liwat Prajanjèn Paris Kapisan tanggal 30 Mèi 1814.", "b313c90b"]},
"OLAYLAR_P0057:1917-01-09:0":{"b": ["Pertempuran Rafah — pasukan jaranan Inggris-Anzac ngrebut posisi Magruntein lan Rafah", "5053c8ef"], "d": ["Divisi Jaranan Anzac, Brigade Korps Unta Kakaisaran lan sawijining brigade yeomanry Inggris saka Pasukan Ekspedisi Mesir sing wis nyabrang Sinai nyerang posisi Utsmaniyah sing dicekel nganggo kubu-kubu ing Magruntein, watara sakilomèter ing kidulé Rafah. Sawisé pertempuran sing angèl, terobosané wong Selandia Anyar lan pasukan unta ngambrukaké pertahanan Utsmaniyah; posisi lan Rafah ing cedhaké direbut lan pasukan Inggris tekan tapel wates Palestina.", "7f90289f"]},
"OLAYLAR_P0057:1918-03-12:0":{"b": ["Gerakan mangsa adhem Kâzım Karabekir: bebarengan karo Erzurum, Hasankale (Pasinler) direbut manèh", "27df4879"], "d": ["Sawisé wadyabala Rusia ambyar, pasukan Utsmaniyah ing sangisoré Kâzım Karabekir Pasya sing obah ing sisih wétan, sanajan mangsa adhemé abot, ngrebut manèh Erzincan, Erzurum lan Hasankale ing wétané Erzurum; lakuné maju tekan Kars ing tanggal 25 April 1918.", "80a72c73"]},
"OLAYLAR_P0057:1919-01-23:0":{"b": ["Pendhudhukan Eskişehir déning Inggris", "8e349037"], "d": ["Sawisé Gencatan Sanjata Mudros, nagara-nagara Entente wiwit ngawasi simpang-simpang sepur ing Anatolia. Miturut artikel Eskişehir ing TDV, kutha iku dienggoni Inggris ing tanggal 23 Januari 1919. Pasukan Inggris ngosongaké Eskişehir ing tanggal 20 Maret 1920.", "5bb8774d"]},
"OLAYLAR_P0057:1919-05-11:0":{"b": ["Wong Italia ndharat ing pesisir Anatolia Kidul-Kulon — Marmaris, Bodrum, Kuşadası", "15d6fb7a"], "d": ["Italia, sing ninggal Konferensi Perdamaian Paris minangka protes marang sikapé sekutu sing mbélani Yunani, sawisé Antalya ngedhunaké prajurit ing pesisir kidul-kulon. Miturut TDV, Marmaris dienggoni Italia ing tanggal 5 Mèi, Bodrum 11 Mèi, lan Kuşadası 13 Mèi. Ing dina-dina iku uga wong Yunani ndharat ing Fethiye; saingan nagara loro iku ing Anatolia Kulon nyiapaké dalan tumuju pendhudhukan Izmir.", "82266143"]},
"OLAYLAR_P0057:1919-05-26:0":{"b": ["Pasukan Yunani mlebu Manisa lan Aydın", "a4230775"], "d": ["Wadyabala Yunani sing ndharat ing Izmir tanggal 15 Mèi enggal sumebar menyang pedhalaman. Miturut artikel Manisa ing TDV, pasukan Yunani mlebu kutha iku ing tanggal 26 Mèi 1919; miturut artikel Aydın, Aydın dienggoni ésuké, tanggal 27 Mèi. Pendhudhukan Manisa bakal lumaku nganti September 1922.", "514ead8b"]},
"OLAYLAR_P0057:1919-06-28:0":{"b": ["Pendhudhukan Italia ing Burdur — kompi sing tumuju Isparta mundur", "874e9d6d"], "d": ["Wong Italia sing ngenggoni Antalya maju menyang pedhalaman. Miturut artikel Isparta ing TDV, pasukan Italia ngenggoni Burdur ing tanggal 28 Juni lan ing tanggal 15 Agustus tumuju Isparta nganggo prajurit sakompi. Nalika warga Isparta nolak panjaluk masrahaké gaman lan mratélakaké bakal nglawan, wong Italia mundur ésuké.", "35806188"]},
"OLAYLAR_P0057:1919-06-30:0":{"b": ["Pambébasan sedhéla Aydın lan dienggoni manèh ing tanggal 4 Juli", "753c739f"], "d": ["Nglawan pendhudhukan Yunani, pasukan nasional ditata ing sakiwa-tengené Ödemiş, Nazilli lan Aydın. Miturut artikel Aydın ing TDV, kutha sing dienggoni ing tanggal 27 Mèi 1919 dibébasaké sedhéla ing tanggal 30 Juni, nanging ing tanggal 4 Juli dienggoni Yunani manèh. Sawisé iku kutha tetep dienggoni nganti 7 September 1922.", "a0031b01"]},
"OLAYLAR_P0057:1919-07-23:0":{"b": ["Pendhudhukan Italia ing Muğla", "a4f5a926"], "d": ["Italia ngambakaké pendhudhukané ing pesisir kidul-kulon menyang pedhalaman. Miturut artikel Muğla ing TDV, kutha iku dienggoni Italia ing tanggal 23 Juli 1919. Pendhudhukan Muğla lumaku nganti 5 Juli 1921.", "b77c243c"]},
"OLAYLAR_P0057:1919-10-15:0":{"b": ["Pamaréntahan militèr Prancis ing Trakia Kulon diwiwiti", "5801e6de"], "d": ["Trakia Kulon, sing isih ana ing tangané Bulgaria sing kalah ing Perang Donya Kapisan, nalika rembugan perdamaian isih lumaku dilebokaké ing pangawasan nagara-nagara Entente. Miturut artikel Trakia Kulon ing TDV, tlatah iku dienggoni pasukan Prancis ing tanggal 15 Oktober 1919; Paguyuban Pambélaan Hak Trakia Kulon ing mangsa iku mindhah punjeré menyang Komotini. Pamaréntahan Prancis lumaku nganti tlatah iku, miturut putusan San Remo, dipasrahaké marang Yunani ing Mèi 1920.", "58f44e3a"]},
"OLAYLAR_P0057:1920-03-20:0":{"b": ["Inggris ngosongaké Eskişehir", "6820e164"], "d": ["Eskişehir, sing wiwit Januari 1919 dienggoni Inggris, miturut artikel Eskişehir ing TDV dikosongaké Inggris ing tanggal 20 Maret 1920. Sawetara sasi sabanjuré, ing Juni 1920, kutha iku dadi punjer Front Kulon sing diadegaké TBMM.", "5f817d34"]},
"OLAYLAR_P0057:1920-06-22:0":{"b": ["Serangan mangsa panas Yunani — pendhudhukan Akhisar, Soma, Balıkesir lan Alaşehir", "f096d2b4"], "d": ["Nalika sekutu ngidini wadyabala Yunani maju ngliwati garis Milne, serangan Yunani sing gedhé diwiwiti ing Anatolia Kulon. Miturut artikel Perjuangan Nasional ing TDV, pasukan Yunani sing obah saka telung jurusan ing tanggal 22 Juni ngrebut Akhisar, Kırkağaç, Soma lan Balıkesir. Ing sisih kidul, Alaşehir dienggoni ing tanggal 26 Juni lan Nazilli ing tanggal 3 Juli.", "bb4b4b94"]},
"OLAYLAR_P0057:1920-07-08:0":{"b": ["Pendhudhukan Yunani ing Bursa", "7c2b32a1"], "d": ["Barisan lor serangan mangsa panas sawisé Balıkesir tumuju Marmara. Miturut artikel Bursa lan Perjuangan Nasional ing TDV, Bursa dienggoni Yunani ing tanggal 8 Juli 1920. Tumindak ora ngajèni marang makam para panguwasa Utsmaniyah kapisan nuwuhaké reaksi gedhé ing saindhenging nagara.", "2f040dcd"]},
"OLAYLAR_P0057:1920-07-20:0":{"b": ["Wadyabala Yunani ngenggoni Trakia Wétan — Edirne lan Kırklareli", "9eb3bda1"], "d": ["Yunani miwiti upaya ngrebut Trakia Wétan sacara nyata sadurungé Prajanjèn Sèvres ditandhatangani. Miturut artikel Perjuangan Nasional ing TDV, wadyabala Yunani ngrebut kabèh Trakia ing tanggal 20 Juli; kadadéan iki ndadèkaké sultan ing Istanbul rong dina sabanjuré nganakaké Dhéwan Kasultanan (Saltanat Şûrası). Kırklareli dienggoni ing tanggal 26 Juli, lan Edirne uga mlebu pamaréntahan Yunani ing sasi iku.", "4c68dd1f"]},
"OLAYLAR_P0057:1920-07-28:0":{"b": ["Wadyabala Abang mlebu Nakhchivan", "6dcb9005"], "d": ["Wong Inggris sing mlebu tlatah iku ing wiwitan 1919 wis mbubaraké Républik Aras, lan ing mangsa panas taun iku lunga saka Nakhchivan. Miturut artikel Nakhchivan ing TDV, Wadyabala Abang mlebu Nakhchivan ing tanggal 28 Juli 1920, masrahaké pamaréntahan marang wong komunis, lan Républik Sosialis Soviet Nakhchivan diadegaké. Status tlatah iku ing taun 1921, liwat prajanjèn sing ditandhatangani ing Kars, ditetepaké minangka unit otonom sing kagandhèng karo Azerbaijan.", "bc49ebba"]},
"OLAYLAR_P0057:1920-08-29:0":{"b": ["Pendhudhukan Yunani ing Uşak", "74ad2713"], "d": ["Wadyabala Yunani nerusaké lakuné maju supaya Prajanjèn Sèvres, sing ora diakoni Ankara, ditampa. Miturut artikel Uşak lan Perjuangan Nasional ing TDV, sawisé Gediz, Uşak uga dienggoni ing tanggal 29 Agustus 1920. Mustafa Kemal Pasya wis mriksa pasukan Kuvâ-yi Milliye ing kutha iku watara sesasi sadurungé pendhudhukan iki.", "b7c70a40"]},
"OLAYLAR_P0057:1920-10-25:0":{"b": ["Pendhudhukan Yunani ing İnegöl lan Yenişehir", "4a0460e7"], "d": ["Pasukan Yunani ing Bursa wiwit maju mangétan, menyang jurusan Eskişehir. Miturut artikel Perjuangan Nasional ing TDV, İnegöl lan Yenişehir direbut ing tanggal 25 Oktober 1920. Nalika wis cetha yèn majuné Yunani ora bisa dicegat karo pasukan milisi, front kulon ditata manèh adhedhasar wadyabala reguler.", "53e977e3"]},
"OLAYLAR_P0057:1921-01-01:0":{"b": ["Pungkasané pendhudhukan Italia ing Burdur (taun)", "609123c8"], "d": ["Burdur, sing dienggoni Italia ing tanggal 28 Juni 1919, miturut artikel Burdur ing TDV ngalami pendhudhukan Italia sing sedhéla antarané taun 1919-1921. Sumber ora nyebutaké dina pangosongané; ing peta pendhudhukan rampung ing wiwitan taun 1921. Italia mundur babar pisan saka tlatah pendhudhukané ing Anatolia ing mangsa panas 1921.", "0ac33ff9"]},
"OLAYLAR_P0057:1921-03-23:0":{"b": ["Serangan kapindho wadyabala Yunani — pendhudhukan Bilecik, Afyon lan Adapazarı", "9ae146e2"], "d": ["Wadyabala Yunani, sing sawisé kalah ing İnönü Kapisan ngedhunaké pasukan anyar ing Izmir, nyerang manèh sadurungé entèk wektu sing diwènèhaké Konferensi London. Miturut artikel Perjuangan Nasional ing TDV, wong Yunani ngenggoni Bilecik lan Afyon ing tanggal 23 Maret. Ing sisih lor, Adapazarı uga dienggoni Yunani ing tanggal 25 Maret.", "7d247e77"]},
"OLAYLAR_P0057:1921-03-28:0":{"b": ["Pasukan Turki ngosongaké Batumi", "ba5745dc"], "d": ["Nalika Inggris mundur saka Kaukasus ing Juli 1920, Batumi dikosongaké lan kutha iku dijupuk pamaréntah Géorgia. Miturut artikel Batumi ing TDV, Prajanjèn Moskwa sing ditandhatangani karo Rusia Soviet ing tanggal 16 Maret 1921 masrahaké Batumi marang Géorgia. Pasukan Turki ngosongaké kutha iku ing tanggal 28 Maret 1921 lan Batumi dadi punjeré Républik Otonom Ajaria sing diadegaké ing sajroning Géorgia.", "9555d8e0"]},
"OLAYLAR_P0057:1921-04-07:0":{"b": ["Afyon direbut manèh — perang-perang Aslıhanlar", "2bbba17b"], "d": ["Sawisé serangan Yunani dicegat ing İnönü Kapindho tanggal 1 April, ing front kidul Afyon direbut manèh ing tanggal 7 April. Artikel Perjuangan Nasional ing TDV ngringkes iki kanthi tembung 'sawisé dikalahaké abot ing Aslıhanlar, ing 7 April Afyon direbut manèh'; nanging panalitèn sajarah militèr nempataké pertempuran Aslıhanlar-Dumlupınar sawisé Afyon dikosongaké, antarané 8-15 April, lan nulis yèn kaunggulan taktis tetep ana ing pihak Yunani — crita loro iku ora cocog, mula loro-loroné diaturaké. Kamenangan İnönü dipèngeti karo rapat akbar ing saindhenging nagara, utamané ing Istanbul.", "3525b97a"]},
"OLAYLAR_P0057:1921-06-28:0":{"b": ["Pambébasan Izmit — sawisé Adapazarı", "cec60e36"], "d": ["Adapazarı, sing dienggoni Yunani ing Maret 1921, miturut artikel Adapazarı ing TDV direbut manèh ing tanggal 21 Juni. Miturut artikel Izmit ing TDV, Izmit, sing ing tanggal 6 Juli 1920 dienggoni Inggris dhisik banjur Yunani, uga dibébasaké ing tanggal 28 Juni 1921. Nalika ninggal kutha, wong Yunani ngobong tlatah pasar.", "da5f0806"]},
"OLAYLAR_P0057:1921-07-05:0":{"b": ["Muğla uwal saka pendhudhukan Italia", "143ddf98"], "d": ["Italia wiwit mundur saka tlatah pendhudhukané ing Anatolia ing mangsa panas 1921; pangosongan Antalya wis diwiwiti tanggal 1 Juni. Miturut artikel Muğla ing TDV, Muğla, sing wiwit 23 Juli 1919 dienggoni Italia, dibébasaké ing tanggal 5 Juli 1921.", "84bff82f"]},
"OLAYLAR_P0057:1921-07-20:0":{"b": ["Eskişehir dikosongaké — wadyabala Yunani mlebu Eskişehir, Kütahya lan Bilecik", "a948a74d"], "d": ["Wadyabala Turki sing durung siyaga nalika perang Kütahya-Eskişehir, miturut dhawuhé Mustafa Kemal Pasya, mundur menyang wétané Kali Sakarya. Miturut artikel-artikel TDV, wong Yunani mlebu Eskişehir ing tanggal 20 Juli 1921, Kütahya 21 Juli, lan Bilecik 22 Juli. Raja Yunani Konstantinos mimpin dhéwan perang ing Kütahya tanggal 28 Juli lan wadyabala cecawis nyerang menyang jurusan Ankara.", "29f7f871"]},
"OLAYLAR_P0057:1922-04-29:0":{"b": ["Pasukan Italia mundur saka Marmaris lan Kuşadası", "1d672994"], "d": ["Wong Italia, sing wiwit Mèi 1919 ana ing pesisir Anatolia kidul-kulon, sawisé rukun karo Pamaréntah Ankara ngosongaké tlatah pendhudhukané sethithik mbaka sethithik. Antalya lan Bodrum wis dikosongaké ing mangsa panas 1921; pasukan Italia pungkasan lunga uga saka Kuşadası lan Marmaris ing pungkasan April 1922.", "f956076c"]},
"OLAYLAR_P0057:1922-08-26:0":{"b": ["Serangan Agung diwiwiti", "efba4bd3"], "d": ["Sawisé cecawis setaun suwéné sabubaré Sakarya, wadyabala Turki miwiti serangan umum ing front Afyon. Miturut artikel Perjuangan Nasional lan Kütahya ing TDV, Serangan Agung diwiwiti saka Afyon ing ésuk 26 Agustus 1922 lan perlawanané wadyabala Yunani enggal jebol.", "7eaf426f"]},
"OLAYLAR_P0057:1922-08-27:0":{"b": ["Pambébasan Afyon", "beaeef23"], "d": ["Ing dina kapindho serangan, front Yunani jebol ing ngarep Afyon. Miturut artikel Afyonkarahisar ing TDV, ing pungkasan Serangan Agung sing dipimpin Atatürk piyambak, pasukan Yunani digawé bubrah lan kutha dibébasaké ing tanggal 27 Agustus 1922. Dina iki dipèngeti minangka dina pambébasan Afyon.", "bfb4dd98"]},
"OLAYLAR_P0057:1922-08-30:0":{"b": ["Perang Palagan Panglima Agung — pambébasan Kütahya", "376d3118"], "d": ["Pasukan utama wadyabala Yunani dikepung antarané Afyon lan Dumlupınar. Miturut artikel Perjuangan Nasional ing TDV, gerakan pangepungan dirampungaké ing tanggal 30 Agustus liwat Perang Panglima Agung sing dipimpin piyambak déning Panglima Agung Mustafa Kemal Pasya. Miturut artikel Kütahya ing TDV, ing dina iku uga sawijining divisi jaranan mbébasaké Kütahya sing diobong lan dirusak pasukan Yunani sing mundur.", "6ecd76e4"]},
"OLAYLAR_P0057:1922-09-01:0":{"b": ["Pambébasan Uşak", "0f2d44d1"], "d": ["Sawisé Perang Panglima Agung, sisa-sisa wadyabala Yunani mundur mangulon, menyang jurusan Izmir. Miturut artikel Uşak ing TDV, Uşak sing wiwit 29 Agustus 1920 dienggoni, uwal ing tanggal 1 September 1922 nalika pasukan nasional mlebu kutha. Ing kobongan sing digawé pasukan pendhudhuk sing mundur, watara telung prapat kutha kobong.", "ea4dc034"]},
"OLAYLAR_P0057:1922-09-02:0":{"b": ["Pambébasan Eskişehir", "f442de5c"], "d": ["Ing sayap lor Serangan Agung, pasukan Yunani kepeksa ninggal Eskişehir uga. Miturut artikel Eskişehir ing TDV, kutha sing wiwit 20 Juli 1921 dienggoni dibébasaké ing tanggal 2 September 1922 sawisé kamenangan 30 Agustus. Ing pungkasan pendhudhukan telulas sasi, tlatah pasar wis diobong lan kutha rusak setengah.", "3b15a7c5"]},
"OLAYLAR_P0057:1922-09-06:0":{"b": ["Pambébasan Bilecik", "35dbd49b"], "d": ["Miturut artikel Bilecik ing TDV, nalika Perjuangan Nasional kutha iku dienggoni Yunani kaping telu; pendhudhukan katelu sing diwiwiti 22 Juli 1921 rampung tanggal 6 September 1922. Ing kobongan sing digawé pasukan Yunani nalika ngosongaké kutha, pérangan gedhé omah, toko lan gedhong pamaréntah kobong.", "28e74c34"]},
"OLAYLAR_P0057:1922-09-07:0":{"b": ["Pambébasan Aydın", "ef1280b5"], "d": ["Nalika wadyabala Turki nyedhaki Izmir, pasukan Yunani ing lembah Menderes uga mundur. Miturut artikel Aydın ing TDV, ing tanggal 7 September 1922 kutha iku dibébasaké pasukan Turki ing kahanan rusak sapérangan lan pendhudhuké suda banget. Wong Yunani sing mundur wis ngobong pérangan gedhé kutha.", "358e3333"]},
"OLAYLAR_P0057:1922-09-11:0":{"b": ["Bursa direbut manèh", "6ad1da0b"], "d": ["Sawisé pambébasan Izmir, wadyabala Turki maju ing sisih lor menyang pesisir Marmara. Miturut artikel Bursa ing TDV, kutha sing wiwit 8 Juli 1920 dienggoni Yunani direbut manèh ing tanggal 10-11 September 1922. Lakuné wadyabala saka kéné menyang Çanakkale gawé Inggris kuwatir lan mbukak dalan tumuju rembugan Mudanya.", "caa09d48"]},
"OLAYLAR_P0057:1922-11-10:0":{"b": ["Trakia Wétan ditampa — Kırklareli lan Tekirdağ", "2a08d65c"], "d": ["Gencatan Sanjata Mudanya netepaké supaya Trakia Wétan dikosongaké wadyabala Yunani lan dipasrahaké marang Turki; Refet Pasya, sing ditugasi nampa Trakia, teka ing Istanbul tanggal 19 Oktober. Miturut TDV, Kırklareli sing wiwit 26 Juli 1920 dienggoni direbut manèh ing tanggal 10 November 1922, lan Tekirdağ uga dibalèkaké marang wong Turki ing tanggal 13 November miturut gencatan sanjata. Mangkono Trakia Wétan gabung karo wilayah Turki tanpa perang.", "cb085872"]},
"OLAYLAR_P0058:1339-01-01:0":{"b": ["Eretna nggandhèngaké tlatah Tokat, Kayseri lan Samsun karo kakuwasané", "4a088f9f"], "d": ["Amir Eretna, sing saya kuwat ing Anatolia minangka gubernur Ilkhaniyah, sawisé olèh manèh panyengkuyungé Sultan Mamluk an-Nasir Muhammad, ing taun 1339 ngambakaké tapel watesé lan nggandhèngaké tlatah Tokat, Kayseri lan Samsun karo kakuwasané. Tlatah Zamantı ing wétané Kayseri uga mlebu pamaréntahan Eretna ing mangsa iki. Kadipaten iku nglairaké kamardikané ing taun 1341 sawisé sédané an-Nasir.", "5be963a4"]},
"OLAYLAR_P0058:1360-01-01:0":{"b": ["Halil Bey saka Dulkadir ngambakaké tapel watesé nganti tekan Zamantı", "aa911e87"], "d": ["Wilayah Eretna, sing ringkih amarga Mehmed Bey dadi pangarsa Kadipaten Eretna nalika isih cilik, saya kerep diserang wong Turkmen saka kidul. Ing taun 1360, nalika Ömer Bey, salah siji pangarsa Turkmen, ngrebut Malatya, Halil Bey saka wangsa Dulkadir uga ngambakaké tapel wates kadipatené nganti tekan Zamantı ing wétané Kayseri. Mangkono tlatah Zamantı antarané Elbistan lan Kayseri tiba ing tangané wangsa Dulkadir, lan kadipaten iku nyekel tlatah iki nganti dianèksasi Utsmaniyah ing taun 1515.", "6f54371d"]},
"OLAYLAR_P0058:1394-01-01:0":{"b": ["Bayezid Yildirim ngepung kenceng Istanbul manèh", "244834ca"], "d": ["Istanbul, sing wiwit 1391 kala-kala diblokade, ing mangsa semi 1394 dikepung kenceng manèh déning Bayezid Yildirim. Mangkono sesambungan karo Bizantium, sing wiwit 1371 mbayar upeti marang Utsmaniyah lan ngirim bantuan militèr, dadi memungsuhan sing terang-terangan. Pangepungan dicabut amarga njedhulé bebaya Timur lan Perang Ankara 1402.", "c3af0f1d"]},
"OLAYLAR_P0058:1424-02-22:0":{"b": ["Perdamaian Murad II karo Bizantium — Bizantium nampa mbayar upeti manèh", "6474d704"], "d": ["Murad II, sing ing taun 1422 ngepung Istanbul amarga Bizantium nyengkuyung Mustafa Palsu (Düzmece Mustafa), ing tanggal 22 Fèbruari 1424 nandhatangani prajanjèn perdamaian karo kaisar Bizantium. Liwat prajanjèn iki Bizantium nampa mbayar upeti manèh marang Utsmaniyah lan sarujuk mbalèkaké panggonan-panggonan ing pesisir Marmara, Égéa lan Segara Ireng sing dijupuk sawisé 1402, kajaba bèntèng Silivri lan Terkos; mangkono upeti taunan, sing wis diuwali liwat prajanjèn karo Amir Suleyman ing 1403, bali manèh. Bizantium tetep ing kahanan iki nganti panaklukan Istanbul ing 1453.", "dd19c749"]},
"OLAYLAR_P0058:1514-10-23:0":{"b": ["Bèntèng Bayburt lan Kiğı ditampa saka Safawiyah — Erzincan lan Bayburt diparingaké marang Bıyıklı Mehmed Bey", "2c7fd65e"], "d": ["Nalika Yavuz Sultan Selim ana ing pasanggrahan wadyabala nalika bali saka Tabriz sawisé kamenangan Chaldiran, teka warta yèn bèntèng Bayburt lan Kiğı wis ditampa. Sanjak bey Trebizond Bıyıklı Mehmed Bey lan sanjak bey Ioannina Mustafa Bey ing Oktober 1514 ngrebut Bayburt sing dibélani Kara Maksud-i Sultani, salah siji amiré Syah Ismail. Erzincan, sing mlebu panguwasa Utsmaniyah tanpa perang, bebarengan karo Bayburt ing tanggal 23 Oktober 1514 diparingaké marang Bıyıklı Mehmed Bey minangka beylerbeylik, lan Bayburt didadèkaké punjer sanjak.", "d3796513"]},
"OLAYLAR_P0058:1514-11-24:0":{"b": ["Yavuz Sultan Selim bali saka ekspedisi Tabriz menyang Amasya lan ngliwati mangsa adhem ing kana", "49d51f94"], "d": ["Yavuz Sultan Selim, sing manggon sangang dina ing Tabriz, amarga kurang pangan lan prajurité emoh, wurung ngliwati mangsa adhem ing Iran lan bali liwat Kars lan Bayburt. Sultan sing ngrayakaké Riyaya Idul Fitri ing Niksar tekan Amasya lan ngliwati mangsa adhem ing kana. Taun sabanjuré panjenengané niyat nyerang Safawiyah manèh; ing Amasya wong Yanisari wiwit meksa supaya bali menyang Istanbul, lan ekspedisi diterusaké ing mangsa semi 1515 karo panaklukan Kemah.", "2693e398"]},
"OLAYLAR_P0059:1594-11-13:0":{"b": ["Wallachia, Moldavia lan Transylvania bebarengan mbrontak nglawan Utsmaniyah", "e71d3ee9"], "d": ["Ing tengah 1594 telung kavoivodan ing loré Donau — Wallachia, Moldavia lan Transylvania — mutusaké tumindak bebarengan nglawan Utsmaniyah. Voivoda Moldavia Aron Tiran gabung karo Liga Suci sing diadegaké Kaisar Austria lan Paus Clemens VIII lan ndadèkaké dhiriné bawahan Kapangéranan Transylvania; voivoda Wallachia Mihai Viteazul mèlu gerakan amarga ora marem karo pajeg sing abot. Ing tanggal 13 November 1594 pambrontakan bebarengan nglawan pamaréntahan Utsmaniyah diwiwiti ing Wallachia lan Moldavia, lan kanthi panyengkuyungé Transylvania gerakan iku mbludag menyang kidulé Donau, menyang wilayah Utsmaniyah. Miturut Ensiklopedi Islam TDV, sekutu telu iki mbukak front lor Perang Dawa Utsmaniyah-Habsburg (1593-1606) sing lumaku ing taun-taun iku.", "30f44add"]},
"OLAYLAR_P0069:1523-01-01:0":{"b": ["Panaklukan Bèntèng Ostrovica ing lembah Una", "5c6cc91b"], "d": ["Ostrovica, sing ana ing tangané Frankopan lan bangsawan Kroasia liyané, ana ing ndhuwur gigir curam sing nyambungaké pérangan lor lan kidul lembah Una. Ing 1523 pindhah menyang pamaréntahan Utsmaniyah lan nganti 1878 duwé garnisun Utsmaniyah. Bèntèng iku éntuk wigati sing satemené sawisé Karlowitz (1699): amarga cedhak wates Venesia lan Austria, diambakaké, lan dadi puser kapitanan Stara Ostrovica; kutha cilik Kulen Vakuf diadegaké ing sikilé ing wiwitan abad kaping-18.", "0978b370"]},
"OLAYLAR_P0069:1527-05-01:0":{"b": ["Panaklukan bèntèng Udbina lan Krbava — Lika mlebu pamaréntahan Utsmaniyah", "5fe329d3"], "d": ["Dhataran Krbava ing 1524 wis kothong, ing Udbina mung kari garnisuné Karlović. Karlović ing April 1527 menang pungkasan ing ngarep bèntèng, nanging ing pungkasan Mèi Udbina, bebarengan karo bèntèng Mrsinj lan Komić, tiba ing tangané pasya Bosnia. Ing taun sing padha tlatah Gospić diwènèhaké marang para agha Senković. Sawisé iku Lika lan Krbava dadi pérangan sanjak sing puseré ing Obrovac, sing ing 1580 nampa jeneng Krka.", "0e759e1a"]},
"OLAYLAR_P0069:1592-01-01:0":{"b": ["Pindhahé Drežnik lan županija Drežnik kanthi pungkasan menyang pamaréntahan Utsmaniyah", "6624ad14"], "d": ["Drežnik, sing wiwit 1323 ana ing tangané Frankopan, ing 1578 sauntara dicekel Utsmaniyah. Ing 1592 bèntèng lan sakabèhé županija Drežnik mlebu kanthi pungkasan ing pamaréntahan Utsmaniyah; ing taun sing padha Bihać uga tiba. Drežnik ing abad kaping-18 gumantung marang kapitanan Ostrožac.", "b41efb59"]},
"OLAYLAR_P0069:1636-01-01:0":{"b": ["Bèntèng Cetin direbut wong Utsmaniyah", "98815f97"], "d": ["Cetin, sing wiwit tengah abad kaping-16 dadi bèntèng kunci pertahanan tlatah Slunj nglawan Utsmaniyah, sawisé bola-bali dikepung, ing 1636 pindhah menyang pamaréntahan Utsmaniyah. Mangsa Utsmaniyah kapisan iki lumaku rong taun.", "44a52e6e"]},
"OLAYLAR_P0069:1638-01-01:0":{"b": ["Bèntèng Cetin bali menyang pihak Habsburg", "690f9f84"], "d": ["Cetin, sing ing 1636 tiba ing tangané Utsmaniyah, ing 1638 bali menyang pertahanan wates Kroasia-Habsburg lan tetep mangkono nganti 1670.", "8f16b3ec"]},
"OLAYLAR_P0069:1670-01-01:0":{"b": ["Cetin dadi manèh bèntèng Utsmaniyah", "e1750675"], "d": ["Cetin ing 1670 dadi manèh bèntèng Utsmaniyah lan ing abad kaping-18 dibètèngi kanthi temenan: bèntèng abad tengahan dikupengi témbok sing mawa bastion. Bèntèng iku nganti 1790 nyekel pucuk kulon-lor wates Bosnia.", "3cf8713d"]},
"OLAYLAR_P0069:1689-01-01:0":{"b": ["Ilangé Lika lan Krbava — Udbina lan Gospić tiba ing tangané wadyabala wates Habsburg", "01277a38"], "d": ["Ing perang sing lumaku sawisé kekalahan Wina, pasukan wates Kroasia ing sangisoré pimpinan jenderal Karlovac, Herberstein, ing 1689 ngrebut Udbina; Gospić uga ing taun sing padha metu saka pamaréntahan Utsmaniyah. Lika Utsmaniyah sing lumaku luwih saka 160 taun rampung, papan-papan sing kothong diisèni warga Kroasia anyar, lan Udbina nganti perdamaian Sistova (1791) dadi bèntèng wigati pertahanan wates nglawan Utsmaniyah.", "bde1a0dc"]},
"OLAYLAR_P0069:1788-01-01:0":{"b": ["Drežnik direbut Austria — garis ngarep kulon Perang Dubica", "05d5e5f1"], "d": ["Ing perang Utsmaniyah-Austria 1788-1791 wadyabala Habsburg ngrebut Drežnik ing sisih kuloné Bihać. Liwat pasal kaping-4 Prajanjèn Sistova, Drežnik lan Cetin tetep ing pamaréntahan Habsburg lan ora naté bali manèh menyang Bosnia.", "30f8f200"]},
"OLAYLAR_P0069:1790-01-01:0":{"b": ["Bèntèng Cetin direbut Austria", "df182480"], "d": ["Ing 1790 tentara Habsburg nyerang Cetin, Bužim lan Velika Kladuša, lan ngrebut Cetin. Mobilisasi sing diumumaké gubernur Bosnia lan serangan balesan ora bisa njupuk manèh bèntèng; pasal kaping-4 Prajanjèn Sistova ninggalaké Cetin marang Habsburg. Para prajurit wates Bosnia ngrebut manèh bèntèng liwat panggrebegan cekak ing 1809 lan 1813.", "fc69baec"]},
"OLAYLAR_SEHIR_ILK:1284-03-20:0":{"b": ["Bilecik disebut kanggo kaping pisanan — tapel wates karo Bizantium diwiwiti ing Bilecik", "7b69f743"], "d": ["Ing prastawa taun 683 sing diriwayataké Neşri, Bilecik disebut minangka panggonan wiwitané tapel wates antarané kadipaten pinggiran Osman Bey lan Bizantium. Iki panyebutan kapisan sing dingertèni bab panggonan iku ing sajarah; dudu wektu adegé.", "f668b296"]},
"OLAYLAR_SEHIR_ILK:1299-09-28:0":{"b": ["Dhuwit logam asmané Gazan Khan ing Burdur — saksi kapisan sing dingertèni bab kutha iku", "01974ddc"], "d": ["Wangsa Hamid, amarga ditekan Ilkhaniyah, ing taun 699 kepeksa nyithak dhuwit logam asmané Gazan Khan ing Burdur. Dhuwit logam iki saksi tinulis/mawa tanggal kapisan bab Burdur.", "83a1e1ee"]},
"OLAYLAR_SEHIR_ILK:1352-03-01:0":{"b": ["Çorum disebut ing nagarané Eretna — saksi kapisan sing dingertèni bab kutha iku", "bf7bd67f"], "d": ["Ing antarané kutha-kutha sing ana ing panguwasané Eretna Bey nalika sédané ing Muharam 753, Çorum uga kaétung. Adegé kutha ora dingertèni; panyebutan iki saksi mawa tanggal paling lawas sing bisa ditemokaké.", "68c8fd3f"]},
"OLAYLAR_SEHIR_ILK:1368-01-20:0":{"b": ["Brăila disebut kanggo kaping pisanan — piagam hak mligi Vlaicu Vodă marang para sudagar Brașov", "0b3517a7"], "d": ["Voivoda Wallachia Vladislav maringi piagam sing nggampangaké para sudagar Brașov nalika ngangkut dagangan liwat dalan Brăila. Piagam iki saksi tinulis kapisan sing dingertèni bab Brăila; panggonan iku ing kéné durung disebut minangka kutha, nanging minangka pucuk dalan ing Donau. Iki dudu tanggal adegé.", "8ed7db79"]},
"OLAYLAR_SEHIR_ILK:1420-01-01:0":{"b": ["Chișinău sepisanan disebut ing layang dhawuh voivoda Moldavia", "a50799d7"], "d": ["Jeneng Chișinău sepisanan katon ing layang dhawuh mawa taun 1420 saka voivoda Moldavia Alexandru. Kutha iku suwé tetep dadi kutha cilik Moldavia; nalika ing 1812 pindhah menyang Rusia bebarengan karo Bessarabia, dadi punjer provinsi.", "61d831d5"]},
"OLAYLAR_SEHIR_ILK:1445-01-01:0":{"b": ["Galați sepisanan disebut ing dokumèn voivoda Moldavia", "a31af8a2"], "d": ["Voivoda Moldavia Ștefan II mbébasaké saka béya pabéan rong grobag duwèké Biara Humor sing nggawa iwak saka Galați. Dokumèn iki saksi tinulis kapisan sing dingertèni kanthi pesthi bab Galați; panggonan iku bisa uga wis ana sadurungé minangka désa nelayan ing pinggir Donau.", "40d464f1"]},
"OLAYLAR_SEHIR_ILK:1452-04-03:0":{"b": ["Jeneng Mostar sepisanan katon ing dokumèn Dubrovnik", "a599bc55"], "d": ["Jeneng Mostar sepisanan katon ing dokumèn Dubrovnik mawa tanggal 3 April 1452; panggonan iku ana ing wilayah Kadipatèn Herzegovina. Panaklukan Utsmaniyah kelakon ing 1466-68.", "5fba613f"]},
"OLAYLAR_SEHIR_ILK:1458-01-01:0":{"b": ["Mesjid Hünkâr ing Sarajevo — saksi mawa tanggal paling lawas bab panggonan iku", "ad697a7d"], "d": ["Sanjak bey Bosnia İshak Bey, ing padunungan muslim kapisan ing ara-ara Saray, ngyasa dalem kanggo awaké, Mesjid Hünkâr asmané Mehmed Sang Penakluk, lan pemandhian ing sandhingé. Mesjid iku mawa tanggal 862 (1458); iki bangunan mawa tanggal paling lawas sing dingertèni ing Sarajevo.", "d7927c3d"]},
"OLAYLAR_SEHIR_ILK:1462-02-01:0":{"b": ["Piagam wakaf İshak Bey — wiji kutha Sarajevo diwakafaké", "0b364229"], "d": ["Saka piagam wakafé İshak Bey mawa tanggal Jumadilawal 866 (Fèbruari 1462) bisa dimangertèni yèn saliyané mesjid lan pemandhian uga dibangun zawiyah, omah tarékat Mevlevi, imaret, kreteg ing ndhuwur Miljacka, Penginepan Kolobara ing pinggir sabrang, pasar bedesten, karavanserai lan toko-toko. Dokumèn iki dhasar wakafé kutha; panggonané wis ana sadurungé.", "5f20e8f0"]},
"OLAYLAR_SEHIR_ILK:1472-06-08:0":{"b": ["Pazardzhik sepisanan kacathet ing buku daftar pasukan akıncı", "3b1c839e"], "d": ["Cathetan paling lawas bab kutha iku tekan taun 877 (1472): sawijining buku daftar akıncı ing Perpustakaan Nasional Sofia nyathet panggonan iku.", "45a744f9"]},
"OLAYLAR_SEHIR_ILK:1494-02-06:0":{"b": ["Banja Luka sepisanan disebut ing instruksi Raja Vladislaus II", "0ebc6288"], "d": ["Jeneng Banja Luka sepisanan katon ing instruksi mawa tanggal 6 Fèbruari 1494 saka raja Hungaria-Kroasia Vladislaus II; tlatah iku kagandhèng karo makutha Hungaria liwat banat Jajce. Panaklukan Utsmaniyah kelakon ing mangsa adhem 1527-28.", "02da21ca"]},
"OLAYLAR_SEHIR_ILK:1494-10-02:0":{"b": ["Warga Basrah ngrampungaké pindhahan menyang papan sing saiki — Basrah lawas ditinggal", "20f96eac"], "d": ["Warga suwé-suwé wiwit manggon ing Basrah sing saiki, sing dianggep luwih aman saka serangan Badui lan luwih gampang nyukupi banyuné; pindhahan menyang papan anyar rampung ing taun 900 (1494-95). Basrah lawas sing diadegaké ing jaman Khalifah Umar dumunung watara 25 km saka kutha saiki.", "7e2ce96c"]},
"OLAYLAR_SEHIR_ILK:1503-01-01:0":{"b": ["Mengli Giray Khan ngyasa Kraton Khan ing pinggir Churuksu — dhasar Bakhchysarai", "0792497c"], "d": ["Ing lembah sing biyèn dadi panggonan beburu lan ngaso mangsa panasé para gubernur Orda Emas lan para khan Krimea kapisan, Mengli Giray Khan I ngyasa ing pinggir Churuksu kraton sing saiki dikenal minangka Kraton Khan lan nyèlèhaké dhasar Bakhchysarai. Kutha ngrembaka ing sakiwa-tengené kraton lan sadawané lembah Churuksu sing ciyut, dadi reja ing pungkasan abad XVI, lan dadi punjer Kakhanan Krimea.", "dbbc246c"]},
"OLAYLAR_SEHIR_ILK:1552-01-01:0":{"b": ["Wong Kazak Zaporizhzhia ngedegaké Sich kapisan ing pulo Khortytsia", "e6ca0dd9"], "d": ["Pangéran Dmytro Vyshnevetsky ngedegaké Sich Zaporizhzhia kapisan ing pulo Khortytsia Cilik ing Kali Dnieper. Ing 1558 bèntèng iku dikepung lan dirubuhaké wong Tatar Krimea; Sich sabanjuré dipindhah menyang pulo-pulo ing sisih kidul. Istilah: «Sich» (basa Ukraina Sich) yaiku kémah punjer wong Kazak Zaporizhzhia ing pulo-pulo Dnieper sing dikuwataké nganggo glondhong kayu lan pager parit; iki papan markas, dhéwan (Rada) lan punjeré pangarsa wadyabala pilihan (koshovyi), dudu ibu kutha nagara.", "2af408f9"]},
"OLAYLAR_SEHIR_ILK:1593-01-01:0":{"b": ["Sich Bazavluk diadegaké", "fcd507ae"], "d": ["Sawisé wong Tatar ngrubuhaké Sich Tomakivka, wong Kazak Zaporizhzhia ngedegaké Sich anyar ing pulo Bazavluk, ing panggonan tempuré Dnieper karo cabang Chortomlyk, Pidpilna lan Skarbna. Ing 1638, sawisé pambrontakan Kazak ditumpes, Sich iku dirubuhaké ekspedisi Polandia. Istilah: «Sich» (basa Ukraina Sich) yaiku kémah punjer wong Kazak Zaporizhzhia ing pulo-pulo Dnieper sing dikuwataké nganggo glondhong kayu lan pager parit; iki papan markas, dhéwan (Rada) lan punjeré pangarsa wadyabala pilihan (koshovyi), dudu ibu kutha nagara. Ing tanggal iki «Kahetmanan» durung ana (1648); jeneng Zaporizhzhia tegesé «sabrangé grojogan» lan Sich dumunung ing tapel wates stepa ing sangisoré grojogan Dnieper. Ora ana sesambungan sedulur sacara etnis karo wong Kazakh ing Kazakhstan: wong Kazak Zaporizhzhia yaiku masarakat Slavia Wétan (Ukraina), Ortodoks; sing padha mung tembung «kazak» (prajurit mardika) sing asalé saka basa Turkik.", "ecc27d31"]},
"OLAYLAR_SEHIR_ILK:1628-01-01:0":{"b": ["Sich Mykytyn Rih sepisanan disebut", "61e22abc"], "d": ["Jeneng Sich kapapat sing diadegaké ing Mykytyn Rih, papan Nikopol saiki, sepisanan katon ing 1628; ing 1648 direbut Bohdan Khmelnytsky. Iki saksi kapisan sing dingertèni bab panggonan iku, dudu adegé.", "63f059d0"]},
"OLAYLAR_SEHIR_ILK:1652-01-01:0":{"b": ["Sich Chortomlyk diadegaké", "4b6e8197"], "d": ["Wong Kazak Zaporizhzhia ngedegaké Sich Chortomlyk, sing uga diarani 'Sich Lawas', ing tanjung panggonan tempuré Dnieper karo Kali Chortomlyk. Sich iku dirubuhaké wadyabala Rusia ing tanggal 25 Mèi 1709 amarga nyengkuyung Mazepa.", "e7b8c2ca"]},
"OLAYLAR_SEHIR_ILK:1654-01-01:0":{"b": ["Kharkiv diadegaké déning para pindhahan Kazak", "288b303c"], "d": ["Ing pinggir lor stepa alas, ing panggonan tempuré Kali Lopan lan Kharkiv, para pindhahan Kazak saka pinggir tengen Dnieper ngedegaké padunungan. Kharkiv ora suwé dadi punjer Sloboda Ukraina sing kagandhèng karo Moskwa.", "0d185061"]},
"OLAYLAR_SEHIR_ILK:1711-01-01:0":{"b": ["Wong Kazak Zaporizhzhia ngedegaké Sich Oleshky kanthi idin khan Krimea", "ed26f29d"], "d": ["Nalika serangan Rusia meksa Sich ing Kamianka dikosongaké, wong Kazak Zaporizhzhia kanthi idin khan Krimea manggon ing wilayah kakhanan, ing Oleshky ing pinggir kiwa Kali Konka. Sawisé Prajanjèn Prut, wong Kazaké Hordiienko uga gabung. Khan ora ngidini Sich duwé témbok bèntèng lan mriyem.", "acb5924a"]},
"OLAYLAR_SEHIR_ILK:1728-01-01:0":{"b": ["Sich Oleshky dijarah lan ditinggal", "52361709"], "d": ["Wong Kazak Samara sing mbélani Rusia nggropyok lan njarah Sich Oleshky lan ngobong barak-baraké. Sich iku ora diadegaké manèh; wong Kazak bali menyang Kamianka ing 1730 lan ing 1734 sumpah setya marang Rusia banjur ngedegaké Sich Anyar.", "bf03f792"]},
"OLAYLAR_SEHIR_ILK:1738-01-01:0":{"b": ["Bèntèng Stavropol diadegaké ing pinggir Volga", "eb087a50"], "d": ["Ing Volga Tengah, bèntèng Stavropol diadegaké kanggo wong Kalmyk sing ngrasuk agama Kristen (saiki Tolyatti).", "d486bb18"]},
"OLAYLAR_SEHIR_ILK:1738-03-24:0":{"b": ["Nadir Syah ngrebut Kandahar lan dhawuh ngrubuhaké kutha lawas", "9cc23e6b"], "d": ["Panguwasa Afshariyah Nadir Syah ngrebut Kandahar saka tangané wong Afghan Ghilzai sawisé pangepungan sing suwé. Kutha dirusak lan wargané pindhah menyang Nadirabad sing diadegaké ing kidul-wétané papan lawas; Kandahar lawas ora tau dadi kutha manèh.", "c8df437b"]},
"OLAYLAR_SEHIR_ILK:1777-01-01:0":{"b": ["Bèntèng Stavropol diadegaké ing garis Azov-Mozdok", "7fd9b9f1"], "d": ["Ing garis pertahanan Azov-Mozdok, sing diadegaké sawisé Küçük Kaynarca kanggo ngawasi stepa antarané Kuban lan Terek, digawé sepuluh bèntèng; salah sijiné Stavropol. Bèntèng iku sabanjuré dadi punjer kagubernuran Kaukasus lan gubernia Stavropol.", "f27157a3"]},
"OLAYLAR_SEHIR_ILK:1778-01-01:0":{"b": ["Galangan kapal Kherson diadegaké ing muara Dnieper", "115f2c34"], "d": ["Ing muara Dnieper sing sawisé Küçük Kaynarca pindhah menyang Rusia, cedhak bèntèng pertahanan Aleksandr-shanets sing digawé ing 1737 lan ora suwé banjur rubuh, diadegaké galangan kapal lan dijenengi Kherson. Kutha iku dadi punjer kaza ing 1784 lan punjer gubernia ing 1803.", "a664a96e"]},
"OLAYLAR_SEHIR_ILK:1779-01-01:0":{"b": ["Wong Yunani saka Krimea ngedegaké Mariupol ing pesisir Azov", "4e3af209"], "d": ["Wong Yunani saka Krimea ngedegaké Mariupol ing panggonan Kali Kalmius mili menyang Segara Azov. Kutha iku ing 1784 dadi punjer kaza ing sangisoré kagubernuran Yekaterinoslav.", "d36ebbc5"]},
"OLAYLAR_SEHIR_ILK:1783-01-01:0":{"b": ["Yekaterinoslav dipindhah menyang papan sing saiki ing pinggir Dnieper", "ec361381"], "d": ["Yekaterinoslav, sing diadegaké Potemkin ing 1778 ing panggonan tempuré Kali Kilchen lan Samara, amarga papané ora séhat ing 1783 dipindhah menyang papan sing saiki.", "b37ccddb"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:0":{"b": ["Sevastopol, pelabuhan armada Rusia, diadegaké ing teluk Akhtiar", "01058a25"], "d": ["Sawisé Krimea dianèksasi Rusia ing 1783, teluk panggonan désa Tatar Krimea Akhtiar (Akyar) dipilih kanggo pelabuhan militèr; pelabuhan diadegaké taun sabanjuré lan dijenengi Sevastopol. Kutha iku ing 1804 dadi pelabuhan utama armada Segara Ireng Rusia.", "03079154"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:1":{"b": ["Bèntèng pertahanan Nikolayev (Mykolaiv) diadegaké ing muara Bug", "d57e52b9"], "d": ["Ing panggonan tempuré Kali Bug Kidul lan Inhul, miturut dhawuhé Knyaz Potemkin diadegaké bèntèng pertahanan. Ing 1788 galangan kapal dibukak ing kéné lan panggonan iku dadi salah siji punjer pambangunan kapal armada Segara Ireng.", "76edde36"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:2":{"b": ["Padunungan tapel wates sing dadi wiji Melitopol diadegaké ing pinggir Molochna", "637d5817"], "d": ["Sawisé anèksasi Krimea, padunungan tapel wates diadegaké ing pinggir Kali Molochna. Padunungan iku ing 1816 dijenengi Novooleksandrivka, lan ing 1841 didadèkaké kutha kanthi jeneng Melitopol.", "9151422f"]},
"OLAYLAR_SEHIR_ILK:1805-01-01:0":{"b": ["Novocherkassk, punjer anyar Wadyabala Kazak Don, diadegaké", "bf5709fd"], "d": ["Punjer pamaréntahan Wadyabala Kazak Don pindhah saka Cherkassk, sing nganti wektu iku dadi punjer, menyang Novocherkassk sing diadegaké ing papan Biryuchy Kut antarané Kali Aksay lan Tuzlov.", "544a425d"]},
"OLAYLAR_SEHIR_ILK:1813-03-06:0":{"b": ["Wadi Halfa kacathet ing lelungané Burckhardt ing Nubia", "6efc72ec"], "d": ["Juru lelana Swiss J. L. Burckhardt ing cathetan padinané tanggal 6 Maret 1813 nulis yèn dhèwèké liwat Wadi Halfa lan ing kana ana dedagangan sawetara. Iki saksi mawa tanggal kapisan sing bisa ditemokaké.", "a3a1877c"]},
"OLAYLAR_SEHIR_ILK:1827-01-01:0":{"b": ["Dermaga Berdyansk diadegaké ing pesisir Azov", "908ac3cf"], "d": ["Saka prakarsané Knyaz Mikhail Vorontsov, Berdyansk diadegaké ing panggonan Kali Berda mili menyang Segara Azov. Panggonan iku dadi kutha ing 1835 lan punjer kaza ing 1842.", "8742949e"]},
"OLAYLAR_SEHIR_ILK:1838-01-01:0":{"b": ["Warga Malatya tetep ing kebon anggur Aspuzu — wiji Malatya modhèrn", "d1dba159"], "d": ["Markas gedhé umum Utsmaniyah nglawan wadyabala Mesir Ibrahim Pasya dipindhah ing mangsa panas 1838 saka Mezraa menyang Malatya. Wong Malatya sing manggon ing omah mangsa panasé ing Aspuzu, sawisé wadyabala lunga, ora bali menyang omah mangsa adhemé ing kutha lawas sing wis rusak; Aspuzu dadi wiji Malatya modhèrn. Malatya Lawas (Battalgazi) terus urip kanthi saya cilik.", "f4d616ac"]},
"OLAYLAR_SEHIR_ILK:1918-04-02:0":{"b": ["Van diadegaké ing papan anyar — kutha lawas sing rusak ditinggal", "6d278578"], "d": ["Van dibébasaké saka pendhudhukan ing tanggal 2 April 1918. Wong-wong sing bali ora ndandani Van lawas ing pinggir tlaga sing rusak ing taun-taun perang, nanging ngedegaké kutha anyar watara 7 km saka pinggir tlaga, ing papan kampung lawas Norşen lan Arak. Kutha lawas ditinggal.", "5a729844"]},
"OLAYLAR_SENKRON_0930:1298-01-01:0":{"b": ["Maraş pindhah menyang wong Mamluk — naib Aleppo Bilban al-Tabbakhi ngrebuté manèh saka wong Armenia", "03171265"], "d": ["Maraş, sing wiwit 1258 ana ing tangané Karajan Armenia Cilicia, ing 1293 liwat prajanjiané Sultan Khalil karo wong Armenia sawetara wektu pindhah menyang wong Mamluk, lan sawisé wong Mamluk mundur tiba manèh ing tangané wong Armenia. Ing 697 (1298) naib Mamluk ing Aleppo, Bilban al-Tabbakhi, ngrebut manèh kutha iku. Sawisé iku Maraş tetep dadi tanah Mamluk nganti munggahé Wangsa Dulkadir.", "8fd31b13"]},
"OLAYLAR_SENKRON_0930:1372-01-01:0":{"b": ["Kakaisaran Bizantium dadi pambayar upeti marang Utsmaniyah", "615df998"], "d": ["Sawisé kamenangan Chernomen (1371), kaisar Bizantium Ioannes V ing mangsa adhem 1372 nampa dadi pambayar upeti Murad I: dhèwèké bakal mbayar upeti taunan lan menèhi prajurit kanggo ekspedisiné sultan. Wiwit tanggal iki nganti 1403 Bizantium tetep dadi nagara bawahan sing gumantung marang Utsmaniyah; blokade Bayezid Yildirim ing 1391 nambah upetiné. Sawisé kekalahan Ankara, prajanjian Gallipoli (1403) karo Suleyman Celebi ngluwari Bizantium saka upeti; liwat prajanjian karo Murad II ing 1424 upeti diwiwiti manèh.", "e3c816ac"]},
"OLAYLAR_SENKRON_0930:1399-09-01:0":{"b": ["Sawisé sédané Barquq, Bayezid Yildirim nggandhèngaké Besni, Darende lan Divriği menyang tanah Utsmaniyah", "8e57d7e6"], "d": ["Sawisé sédané Sultan Mamluk Barquq (Juni 1399), nalika urusan pamaréntahan Nagara Mamluk kacau, Bayezid Yildirim mudhun menyang cekungan Efrat lan nggandhèngaké Besni (Behisni), Darende lan Divriği, bebarengan karo Malatya, menyang tanah Utsmaniyah. Sivas sadurungé iku, sawisé sédané Qadi Burhanuddin ing mangsa panas 1398, wis dipasrahaké marang Utsmaniyah. Divriği wiwit 1391 ana ing sangisoré kakuwasan Mamluk lan dadi pos ngarep sing gumantung marang provinsi Aleppo. Pamaréntahan Utsmaniyah ing kéné ora suwé: amarga bebaya Timur sing nyedhak, ing 1401 Divriği dibalèkaké marang wong Mamluk, lan mlebuné kutha iku kanthi pungkasan ing pamaréntahan Utsmaniyah dumadi sawisé Marj Dabiq 1516.", "ec7cd171"]},
"OLAYLAR_SENKRON_0930:1400-08-01:0":{"b": ["Nalika ekspedisi Timur menyang Sivas lan Malatya, Besni pindhah menyang wong Mamluk", "4853da9a"], "d": ["Besni, sing ing 1398 direbut Bayezid Yildirim bebarengan karo Sivas, Darende lan Malatya, ing 1400 tiba ing tangané Mamluk nalika Timur ngrebut Sivas lan Malatya. Tanggal 27 September 1400, sawisé pengepungan sing sengit, Timur uga ngrebut Besni; nalika dhèwèké lunga saka tlatah iku, Besni bali menyang kakuwasan Mamluk lan tetep ing Mamluk (kajaba mangsa antara Dulkadir) nganti direbut Yavuz Sultan Selim ing Agustus 1516.", "0ead96f9"]},
"OLAYLAR_SENKRON_0930:1401-01-01:0":{"b": ["Divriği dibalèkaké marang wong Mamluk amarga bebaya Timur", "97196b1f"], "d": ["Divriği, sing dijupuk Bayezid Yildirim saka wong Mamluk ing 1398, nalika Timur nyedhaki Anatolia ing 1401 dipasrahaké manèh marang wong Mamluk. Mulané sawisé Timur ngrusak Sivas (1400), Divriği ing peta katon mawa warna Mamluk; ing sasi-sasi sing padha Bayezid ing sisih wétan lagi ngrebut Erzincan lan Kemah, tegesé tanah Mamluk ana ing antarané tanah Utsmaniyah ing sisih kulon (Sivas) lan ing wétan-lor (Kemah). Divriği lagi pindhah kanthi pungkasan menyang Utsmaniyah sawisé Marj Dabiq 1516.", "3f13d015"]},
"OLAYLAR_SENKRON_0930:1414-01-01:0":{"b": ["Sultan Mamluk Syekh njupuk manèh Antep lan Darende saka Wangsa Dulkadir", "f90c9508"], "d": ["Sultan Mamluk Syekh, sing kuwatir marang sesambungan becik Wangsa Dulkadir karo Utsmaniyah, ing 1414 mangkat ekspedisi; dhèwèké njupuk manèh Antep lan Darende sing sadurungé diwènèhaké marang Wangsa Dulkadir kanthi karepé dhéwé.", "9f9b94e1"]},
"OLAYLAR_SENKRON_0930:1418-01-01:0":{"b": ["Mehmed Bey Dulkadiroğlu njupuk manèh Darende, lan uga nggandhèngaké Besni menyang tanahé", "df914dcb"], "d": ["Darende, sing dijupuk wong Mamluk ing 1414, ing 1418 dijupuk manèh déning Mehmed Bey Dulkadiroğlu, lan dhèwèké uga nggandhèngaké Besni menyang tanahé.", "d469f850"]},
"OLAYLAR_SENKRON_0930:1436-01-01:0":{"b": ["Wong Mamluk ngalahaké Wangsa Dulkadir ing Antep; Besni bali menyang pamaréntahan Mamluk (kira-kira)", "72742430"], "d": ["Tentara Mamluk ing 1436 ngalahaké Wangsa Dulkadir ing Antep, lan Mehmed Bey mundur menyang Akdağ. Taun baliné Besni menyang Mamluk ora ditulis ing sumber; Besni ing 1418 digandhèngaké menyang Dulkadir, lan sadurungé Şehsuvar Bey ngrebuté saka wong Mamluk ing 1465, wis bali menyang Mamluk. Atlas mbalèkaké Besni marang Mamluk bebarengan karo kekalahan iki ing puser tetanggan, Antep (kira-kira kanthi katrangan).", "dc3b71ff"]},
"OLAYLAR_SENKRON_0930:1467-01-01:0":{"b": ["Şehsuvar Bey Dulkadiroğlu ngrebut Besni saka wong Mamluk (kira-kira)", "843f0fc4"], "d": ["Şehsuvar Bey (1465-1472), sing diangkat dadi bey Dulkadir déning Mehmed Sang Penakluk, ngrebut Besni, Gerger, Birecik lan Rumkale sing ana ing tangané Mamluk; wong Mamluk kalah ing Turnadağı ing mangsa gugur 1467 lan cedhak Antep ing mangsa semi 1468.", "c812ae2a"]},
"OLAYLAR_SENKRON_0930:1471-01-01:0":{"b": ["Emir Yasybak ngalahaké Şehsuvar Bey; Besni bali menyang pamaréntahan Mamluk (kira-kira)", "4d856aee"], "d": ["Ing mangsa semi 1471 Emir Yasybak ngalahaké Şehsuvar Bey ing kali Savron; wong Mamluk njupuk manèh Kadirli lan Kozan. Ing 1472 Şehsuvar diukum pati ing Kairo, lan wong Mamluk ngangkat manèh Shahbudak dadi bey. Liwat baliné iki Besni uga mlebu pamaréntahan Mamluk (TDV besni: 'tumeka pungkasan abad kaping-15 tiba manèh ing tangané wong Mamluk').", "3ba3c319"]},
"OLAYLAR_SENKRON_0930:1550-09-15:0":{"b": ["Wadyabalané Ferdinand ngenggoni Szolnok lan mbètèngi", "6c8416e6"], "d": ["Nalika wong Utsmaniyah siyap-siyap mbangun bèntèng ing Szolnok ing pinggir Tisza, wadyabalané Ferdinand I ndhisiki: ing tengah September 1550 padha ngenggoni Szolnok lan ing tengah Oktober bèntèng wis bisa dipertahanaké. Kanthi mangkono Szolnok, duwèké nagarané Izabella, tiba ing tangané Habsburg setaun sadurungé Transylvania pindhah menyang Ferdinand; wong Utsmaniyah ngrebut bèntèng iku ing 1552.", "eea8389b"]},
"OLAYLAR_SENKRON_0930:1551-07-26:0":{"b": ["Transylvania pindhah menyang pamaréntahan Habsburg: dhéwan Kolozsvár ngakoni anggoné Izabella ngeculaké hak", "8458a566"], "d": ["Amarga kasepakatan Martinuzzi karo Ferdinand, Ratu Izabella tanggal 19 Juni 1551 ing bèntèng Szászsebes, atas jenengé raja cilik János Zsigmond, nandhatangani layang pangeculan hak sing dipeksakaké marang dhèwèké. Tanggal 26 Juli dhéwan Transylvania sing nglumpuk ing Kolozsvár ngakoni pangeculan iki lan kakuwasan Raja Ferdinand; tentara Habsburgé Jenderal Castaldo mlebu Alba Iulia (Gyulafehérvár). Kanthi mangkono Transylvania, sing gumantung marang Utsmaniyah, pindhah menyang pamaréntahan Habsburg sing bakal lumaku limang taun.", "d8d0aad9"]},
"OLAYLAR_SENKRON_0930:1556-03-12:0":{"b": ["Pamaréntahan Habsburg ing Transylvania rampung: Transylvania dadi manèh kavoivodan sing gumantung marang Utsmaniyah", "721a482a"], "d": ["Amarga János Zsigmond isih cilik, liwat pastor keturunan Kroasia, Martinuzzi (Fráter György), sing diangkat dadi waliné, wong Habsburg ing 1551 nyoba nguwasani Transylvania; Alba Iulia (Gyulafehérvár), Kolozsvár, Brassó lan Segesvár limang taun tetep ing pamaréntahan Habsburg. Wong Utsmaniyah nyegah kahanan iki, lan Transylvania dadi manèh kavoivodan pambayar upeti sing gumantung marang dhèwèké. Sawisé iku Transylvania, sajroné watara 150 taun ing abad kaping-16 lan 17, njaga status sing adhedhasar otonomi amba ing urusan njero lan kasetyan marang Istanbul ing urusan njaba.", "0566dd84"]},
"OLAYLAR_SENKRON_0930:1557-01-01:0":{"b": ["Várad, Huszt lan Tokaj pindhah menyang pihak Szapolyai", "587c782d"], "d": ["Sawisé Izabella lan János Zsigmond bali menyang Transylvania ing 1556, para pandhèrèk Szapolyai ing taun 1556 ngepung Nagyvárad. Ing 1557 para bangsawan Tisza Ndhuwur ngrebut bèntèng-bèntèng karajan sing paling wigati — Várad, Huszt lan Tokaj; ing tangané Ferdinand mung kari Gyula lan Világos. Sawisé iku Várad dadi bèntèng kapangéranan Transylvania lan tetep mangkono nganti direbut wong Utsmaniyah ing 1660.", "3f850e28"]},
"OLAYLAR_SENKRON_0930:1565-02-01:0":{"b": ["Schwendi ngrebut Szatmár — pucuk lor Transylvania pindhah menyang Habsburg", "2256bb27"], "d": ["Szatmár, sing pindhah menyang Habsburg amarga Balassa Menyhért ganti pihak ing 1561, direbut manèh déning Báthory István liwat panggrebegan ing mangsa gugur 1564 lan digandhèngaké menyang Transylvania. Panglima Habsburg Lazarus von Schwendi ing Februari 1565 nindakaké serangan balesan: Tokaj tiba tanggal 9 Februari, Szerencs patang dina sabanjuré, lan Szatmár tiba ing tangané wadyabala kakaisaran meh tanpa perlawanan.", "8735c789"]},
"OLAYLAR_SENKRON_0930:1605-01-21:0":{"b": ["Wadyabalané Bocskai ngrebut Szatmár", "e93b098b"], "d": ["Nalika pambrontakan Bocskai nyebar menyang Hungaria wétan-lor, Gyulaffy tanggal 21 Januari 1605 ngrebut Szatmár sing dikepung. Perdamaian Wina 23 Juni 1606 masrahaké kabupatèn Szatmár marang Bocskai salawasé urip; amarga ora ana ahli waris lanang, kanthi sédané Bocskai tanggal 29 Desember 1606 kabupatèn iku bali menyang karajan.", "a7cde19a"]},
"OLAYLAR_SENKRON_0930:1606-12-29:0":{"b": ["Sédané Bocskai István — kabupatèn Szatmár bali menyang karajan", "3721bb9b"], "d": ["Pangéran Transylvania, Bocskai István, séda ing Kassa tanggal 29 Desember 1606. Perdamaian Wina (23 Juni 1606) wis masrahaké kabupatèn-kabupatèn, kalebu Szatmár, marang dhèwèké salawasé urip, kanthi syarat bali menyang karajan yèn ora ana ahli waris lanang; liwat katemtuan iki kabupatèn Szatmár bali menyang karajan Hungaria Habsburg. Transylvania wiwit nggolèki pangéran anyar.", "bbe08ca4"]},
"OLAYLAR_SENKRON_0930:1619-11-01:0":{"b": ["Bethlen Gábor ngendhalèni kabupatèn Szatmár", "80263da1"], "d": ["Liwat ekspedisiné Bethlen Gábor menyang Hungaria ing mangsa gugur 1619, kabupatèn Szatmár mlebu ing kendhalèné pangéran Transylvania; ing November 1619 dhèwèké wis ngirimi layang marang kabupatèn iku. Prajanjian pambuka 23 Januari 1620 lan perdamaian Nikolsburg masrahaké pitung kabupatèn, kalebu Szatmár, marang Bethlen salawasé urip. Sawisé sédané Bethlen (15 November 1629), pambalèkan kabupatèn-kabupatèn marang karajan rampung tanggal 30 Maret 1630.", "76c6a30b"]},
"OLAYLAR_SENKRON_0930:1630-03-30:0":{"b": ["Pambalèkan pitung kabupatènné Bethlen Gábor marang karajan rampung", "31b5968f"], "d": ["Perdamaian Nikolsburg wis masrahaké pitung kabupatèn Hungaria Ndhuwur, kalebu Szatmár, marang Bethlen Gábor salawasé urip. Sawisé sédané Bethlen tanggal 15 November 1629, pambalèkan kabupatèn marang karajan diwiwiti liwat prentah 30 November 1629 lan rampung tanggal 30 Maret 1630.", "dd97dafd"]},
"OLAYLAR_SENKRON_0930:1644-02-01:0":{"b": ["Rákóczi György I nampa Szatmár", "f398635b"], "d": ["Nalika ekspedisi 1644 saka pangéran Transylvania, Rákóczi György I, garnisun Jerman ing Szatmár pindhah ngabdi marang Rákóczi lan bèntèng tiba ing tangané Transylvania. Perdamaian Linz 16 Desember 1645 masrahaké bèntèng marang para ahli waris Rákóczi, sasuwéné ana wong Rákóczi ing dhampar Transylvania.", "17240548"]},
"OLAYLAR_SENKRON_0930:1664-05-03:0":{"b": ["Ilangé Nitra — De Souches njupuk manèh bèntèng", "c71bf012"], "d": ["Nitra, sing sawisé direbuté Uyvar ing 1663 nungkul kanthi perlawanan cekak, tanggal 15 April 1664 dikepung panglima kakaisaran De Souches; bèntèng nungkul tanggal 3 Mèi 1664. Amarga Prajanjèn Vasvár ninggalaké papan-papan sing direbut miturut kahanané, Uyvar tetep ing Utsmaniyah déné Nitra tetep ing tangané Habsburg.", "b1d01f51"]},
"OLAYLAR_SENKRON_0930:1664-06-14:0":{"b": ["Ilangé Léva", "f311920e"], "d": ["Sawisé Nitra, De Souches tanggal 9 Juni 1664 ngepung Léva; tanggal 13 Juni prajanjian nungkul ditandhatangani lan tanggal 14 Juni bèntèng wis ana ing tangané wadyabala kakaisaran. Perang Léva (Garamszentbenedek) tanggal 19 Juli 1664 ora ngowahi kapamilikan; asilé Habsburg tetep nyekel Léva lan Nitra.", "7fe0a206"]},
"OLAYLAR_SENKRON_0930:1676-09-19:0":{"b": ["Doroshenko masrahaké Chyhyryn marang Samoilovych", "3b538237"], "d": ["Hetman Tepi Tengen ing sangisoré pangayoman Utsmaniyah, Petro Doroshenko, tanggal 19 September 1676 masrahaké kutha krajané, Chyhyryn, marang hetman Tepi Kiwa Samoilovych lan wadyabala Rusia. Wong Utsmaniyah mecat Doroshenko lan ngganti karo Yurii Khmelnytsky; pengepungan ing 1677 kanggo ngetokaké garnisun Rusia saka Chyhyryn gagal, lan bèntèng lagi direbut tanggal 21 Agustus 1678.", "cccf7b79"]},
"OLAYLAR_SENUSI_0919:1551-07-01:0":{"b": ["Pamasrahan bèntèng-bèntèng Banat Transylvania (Temeşvar, Lipova, Lugoj, Caransebeș) marang Raja Hungaria Ferdinand", "0e354976"], "d": ["Ing 1551 tentara Habsburg sing dipimpin Jenderal Castaldo mlebu Transylvania; Ratu Izabella lan putrané kepeksa ngeculaké hak tumrap dhampar Hungaria. Martinuzzi, kanthi pasarujukan Castaldo, ing tengah Juli 1551 ngirim Báthory Endre supaya nampa bèntèng Temeşvar, Lipova, Solymos, Caransebeș, Lugoj, Becse, Becskerek lan Cenad atas jenengé Ferdinand. Kanthi mangkono bèntèng-bèntèng kidul Transylvania sing ing pangayoman Utsmaniyah tiba ing tangané Habsburg; ekspedisi Kanunî 1551-1552 iku wangsulané.", "420ca62a"]},
"OLAYLAR_SENUSI_0919:1554-04-07:0":{"b": ["Petrovics Péter diangkat dadi sanjakbey Lugoj lan Caransebeș", "bcbe73e4"], "d": ["Amarga panyuwunan sing terus-terusan saka Izabella lan Petrovics, Kanunî mutusaké mbalèkaké János Zsigmond sing isih cilik menyang Transylvania. Liwat layang sing ditulis saka Aleppo tanggal 7 April 1554 dhèwèké ndhawuhi Transylvania nampa bocah iku bali menyang nagarané; dhèwèké uga ndhawuhi para voivoda Wallachia lan Moldavia mbiyantu Petrovics ing prakara iki, sing ing wektu sing padha diangkat dadi sanjakbey Lugoj lan Caransebeș. Kanthi mangkono Lugoj, sing ditaklukaké ing 1552, diwènèhaké marang Petrovics minangka sanjak Utsmaniyah.", "6c5be465"]},
"OLAYLAR_SENUSI_0919:1596-05-10:0":{"b": ["Pengepungan Lipova diudhari — panggrebegané ban Lugoj marang Temeşvar", "be03430e"], "d": ["Ing mangsa semi 1596 pasya Temeşvar ngepung Lipova. Ing wengi tanggal 10 ngadhepi 11 Mèi, miturut prentah ban Lugoj saka Transylvania, Palatics György, prajurité Buday György nggerebeg lan ngobong kampung njaban kutha Temeşvar; anggoné Borbély György ing bèntèng ndhawuhi nembakaké kabèh meriamé uga ndadèkaké pasya percaya yèn bantuan wis teka. Tanggal 11 Mèi pasya mundur saka ngarep Lipova lan kesusu njaga pusere dhéwé. Ing wektu iku Lugoj ana ing tangané Kapangéranan Transylvania.", "07e2cb97"]},
"OLAYLAR_SENUSI_0919:1688-01-01:0":{"b": ["Orsova dienggoni wadyabala Austria sing dipimpin Veterani", "1b4a4f6c"], "d": ["Ing ekspedisi 1688, Jenderal Veterani sawisé ngrebut Caransebeș mlaku menyang Orsova lan uga ngenggoni. Ing sumber ora ana dina pendhudhukan; dienggo tanggal dhasar taun, 1 Januari 1688.", "1dfe042e"]},
"OLAYLAR_SENUSI_0919:1689-07-15:0":{"b": ["Orsova direbut manèh déning wadyabala Thököly lan Utsmaniyah", "c5645da9"], "d": ["Menyang Orsova sing ing 1688 dienggoni Veterani, sawisé Fetislam direbut, Thököly lan para pasya Utsmaniyah mlaku. Sawisé bentrokan sing ora wigati, Thököly tanggal 15 Juli 1689 mlebu Orsova. Heissler, sing teka amarga kabar bebaya, weruh yèn wadyabala ing ngarepé kacekapan mesiu lan kapal, banjur mundur kanggo njaga Transylvania. Ing Agustus serangané Herbeville ing ngarep kutha uga ora bisa njupuk manèh Orsova.", "6d469bdd"]},
"OLAYLAR_SENUSI_0919:1691-01-01:0":{"b": ["Sanjak Lugoj mlebu pendhudhukan Habsburg (1691-1695)", "c8bcd6bd"], "d": ["Sanjak Lugoj antarané 1691-1695 tetep ing pendhudhukan Habsburg (Jerman); Mustafa II naklukaké manèh tanggal 22 September 1695. Ing cathetan lawas, antarané 1689-1695 iku kekosongan kanthi katrangan; pérangan 1691-1695 saiki diwarnani minangka Habsburg, 1689-1691 tetep kosong. Tanggalé mung dijupuk minangka taun.", "053d32c8"]},
"OLAYLAR_SENUSI_0919:1716-10-18:0":{"b": ["Bèntèng Lugoj mlebu pamaréntahan Habsburg", "6a9d401f"], "d": ["Lugoj, bèntèng sanjak sing gumantung marang eyalet Temeşvar, wiwit 1695 ana ing tangané Utsmaniyah; kanthi nungkulé puser eyalet ing pungkasan pengepungan 1716, dipasrahaké marang Monarki Habsburg. Cathetan lawas nyèlèhaké pamasrahan ing 1 Januari 1716, sing dadi tanggal dhasar taun.", "ab78a026"]},
"OLAYLAR_SENUSI_0919:1717-01-01:0":{"b": ["Orsova direbut tentara Habsburg (ekspedisi 1717)", "7a4faffe"], "d": ["Ing ekspedisi 1717, Jenderal Splényi tanggal 27 Agustus tekan ngarep Orsova lan gampang ngrebut kutha; kanthi mangkono Orsova, sing ing 1716 ora bisa direbut Mercy, tiba ing tangané Habsburg. Petak-petak pinggir Donau sakiwa-tengené (kalebu pérangan Đerdap ing sisih Serbia), amarga gumantung marang titik pamukiman paling cedhak yaiku Orsova, diwarnani miturut sing nduwé Orsova. Tanggalé mung dijupuk minangka taun; dina pastiné durung dikonfirmasi.", "724e03d5"]},
"OLAYLAR_SENUSI_0919:1738-05-08:0":{"b": ["Palanka Orsova pindhah menyang Utsmaniyah — para penjaga mundur menyang Ada Kaleh", "de759b16"], "d": ["Ing wiwitan ekspedisi 1738, penjaga Vidin Hacı Mehmed Pasya nyerang bètèng Erzsébet ing pinggir Donau. Tanggal 8 Mèi awan, pasukan sipahi 4-5 èwu wong mlaku saka pinggir kiwa Donau menyang Orsova lan nyerang palanka Orsova; penjaga Austria, sing karugian watara satus wong, mundur menyang Orsova Anyar, yaiku bèntèng pulo Ada Kaleh. Sawisé bentrokan Mehadia ing Juli, Ada Kaleh uga tiba ing tangané Utsmaniyah ing Agustus 1738; Prajanjèn Beograd 1739 ngakoni kahanan iki.", "70ee9650"]},
"OLAYLAR_SERHAT:1428-01-01:0":{"b": ["Murad II ngrebut Kruševac, Niš lan Pirot bali menyang Utsmaniyah", "54af926a"], "d": ["Sawisé sédané Despot Serbia Stefan Lazarević tanpa ahli waris (1427), Murad II, adhedhasar palakramané Bayezid Yildirim karo putri Serbia, ngaku dadi ahli waris sah Serbia, banjur tumindak lan ngrebut Kruševac (1428). Ing taun sing padha, sawisé sédané Lazarević, wong Utsmaniyah uga njupuk manèh bèntèng Pirot — kutha iku ing 1412 direbut Stefan lan dipertahanaké nglawan Musa Celebi. Miturut artikel TDV nis, wong Utsmaniyah uga njupuk manèh Niš ing taun sing padha (831/1428). Kanthi mangkono garis sing nyambungaké lembah Morava Gedhé lan Nišava mlebu kendhali Utsmaniyah.", "01c87afb"]},
"OLAYLAR_SERHAT:1443-01-01:0":{"b": ["Tentara Salib ngrebut Pirot — pang Nišava saka 'Ekspedisi Dawa'", "fdf6140c"], "d": ["Tentara Salib sing dipimpin Raja Władysław lan Despot Serbia Đurađ Branković ing 1443 ngrebut Pirot. Ing lanjutan ekspedisi sing padha, wadyabala Utsmaniyah ing November bakal kalah abot ing celah Zlatitsa. Pirot, sawisé Prajanjèn Szeged (1444), diwènèhaké manèh marang wong Serbia déning Murad II, nanging sawisé sédané Đurađ Branković ing 1456 pindhah menyang Utsmaniyah.", "f56645a4"]},
"OLAYLAR_SERHAT:1458-01-01:0":{"b": ["Kakuwasan Utsmaniyah sing mantep ing tlatah Kruševac kawujud", "9715382a"], "d": ["Kruševac, sing ing pungkasan prajanjian 1444 karo delegasi Hungaria dipasrahaké marang Branković, ing taun-taun sawisé kamenangan Varna mlebu manèh kakuwasan Turki. Panaklukan kapindho kutha iki ora dibuktèkaké nganggo cathetan perang, nanging nganggo cathetan keuangan: cathetan timar sawetara désa sing gumantung marang Kruševac ditanggali pungkasan 1453/wiwitan 1454; nanging iki mung kesaksian désa — ing 1454 wadyabala Utsmaniyah kalah ing sakiwa-tengené Kruševac, lan ing 1455 Kruševac ditinggalaké marang Branković minangka wates. Miturut TDV, kakuwasan Utsmaniyah sing mantep ing tlatah iku kawujud ing 1458.", "2b6aba24"]},
"OLAYLAR_SESSIZBORC0919:1349-01-01:0":{"b": ["Ngadegé Kadespotan Morea — Manuel Kantakouzenos ing Mystras", "87660b82"], "d": ["Kaisar Bizantium Ioannes Kantakouzenos menèhi putrané, Manuel, tlatah pamaréntahan kapisah ing Morea; kanthi mangkono lair Kadespotan Morea sing puseré ing Mystras. Manuel mréntah nganti 1380; ing mangsa iki kabudayan lan kasenian Bizantium ngrembaka mligi ing Mystras. Kadespotan lumaku nganti ditaklukaké Sang Penakluk ing 1460.", "f5596d5e"]},
"OLAYLAR_SESSIZBORC0919:1430-01-01:0":{"b": ["Despot Konstantinos ngrebut Patras saka wong Frank", "cb0dd18c"], "d": ["Despot Morea Konstantinos (ing 1449 kaisar Bizantium pungkasan) njupuk manèh Patras saka wong Latin; kanthi mangkono pelabuhan wigati ing kulon-lor semenanjung iki uga digandhèngaké menyang kadespotan. Patras ing 1458, nalika ekspedisi Moreané Mehmed Sang Penakluk, mlebu kakuwasan Utsmaniyah.", "98b8dff0"]},
"OLAYLAR_SESSIZBORC0919:1448-01-01:0":{"b": ["Stjepan Vukčić-Kosača 'Adipati St. Sava' — laire Herzegovina", "cc67061f"], "d": ["Stjepan Vukčić-Kosača, sing nyawijikaké Hum lan Trebinje ing siji kadipatèn, mbrontak marang raja Bosnia lan ngumumaké awaké dadi 'Herceg (adipati) St. Sava'; gelar iku ing 1448 diwènèhaké Kaisar Friedrich III. Jeneng Herzegovina ('tanahé Herceg') asalé saka gelar iki. Herzegovina wiwit 1466 sapérangan-sapérangan pindhah menyang Utsmaniyah, ing 1470 dadi sanjak; tanah sing isih kari digandhèngaké ing wiwitan 1482.", "e6a77d9c"]},
"OLAYLAR_SESSIZBORC0919:1525-04-08:0":{"b": ["Perdamaian Kraków — nagara ordo Teutonik owah dadi Kadipatèn Prusia", "78666ddd"], "d": ["Guru agung Ksatria Teutonik, Albrecht saka Brandenburg, amarga ora éntuk pitulungan nglawan Polandia, nandhatangani Perdamaian Kraków. Nagara ordo (Ordensstaat) dadi kadipatèn warisan lan sekuler sing pindhah menyang wangsa Brandenburg, ing sangisoré kapangéranan agung Polandia. Puseré Königsberg; Albrecht ing 1544 ngadegaké Universitas Albertus ing kono. Kadipatèn iku ing 1701 owah dadi Karajan Prusia.", "d38ad9a3"]},
"OLAYLAR_SESSIZBORC0919:1918-11-12:0":{"b": ["Proklamasi Républik Austria — pungkasané monarki Habsburg", "c84f316c"], "d": ["Sadina sawisé Kaisar Karl I tanggal 11 November nglereni anggoné ngurusi nagara, Majelis Nasional Sauntara nampa undhang-undhang bab wujud nagara lan pamaréntahan, lan républik diproklamasikaké. Austria Habsburg digantèni Républik Kapisan sing puseré ing Wina. Liwat proklamasi iki Wina, Linz, Salzburg, Innsbruck, Klagenfurt, Bregenz lan kutha Jerman-Austria liyané dadi tanahé Républik Austria (Deutschösterreich).", "2dcc1399"]}
});
